-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_c99455e110c655', 'subj_phys', 'gauss-ampere', 'Gauss''s and Ampère''s laws', '\oint \vec E\cdot d\vec A = \frac{Q_{enc}}{\varepsilon_0}, \quad \oint \vec B\cdot d\vec\ell = \mu_0 I_{enc}, \quad V = -\int \vec E\cdot d\vec r', 'Gauss''s law for electric fields, Ampère''s law for magnetic fields, and potential as the line integral of the field.', '[{"symbol":"\\varepsilon_0","meaning":"permittivity of free space","unit":"C²/(N·m²)"},{"symbol":"\\mu_0","meaning":"permeability of free space","unit":"T·m/A"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_4cbbd40290b610', 'subj_phys', 'induction-circuits', 'Induction and inductor circuits', '\varepsilon = -\frac{d\Phi_B}{dt}, \quad \varepsilon_L = -L\frac{dI}{dt}, \quad \tau_{LR} = \frac{L}{R}, \quad \omega_{LC} = \frac{1}{\sqrt{LC}}', 'Faraday''s law, self-induced emf, the LR time constant and the LC oscillation frequency.', '[{"symbol":"L","meaning":"inductance","unit":"H"},{"symbol":"\\Phi_B","meaning":"magnetic flux","unit":"Wb"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_44896c7ca7b24b', 'subj_chem', 'molarity-dilution', 'Molarity and dilution', 'M = \frac{n_{solute}}{V_{solution}}, \quad M_1V_1 = M_2V_2', 'Concentration in moles per liter of solution, and the dilution relation (moles of solute stay the same).', '[{"symbol":"M","meaning":"molarity","unit":"mol/L"},{"symbol":"V","meaning":"volume of solution","unit":"L"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d1e3a95f6199f0', 'subj_chem', 'heat-enthalpy', 'Heat and enthalpy', 'q = mc\Delta T, \quad \Delta H_{rxn} = -\frac{q_{solution}}{n}', 'Heat absorbed by a sample, and the molar enthalpy change measured by a coffee-cup calorimeter.', '[{"symbol":"q","meaning":"heat","unit":"J"},{"symbol":"c","meaning":"specific heat","unit":"J/(g·°C)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_8429b0ce94e711', 'subj_chem', 'ph-scale', 'pH and pOH', '\text{pH} = -\log[\text{H}^+], \quad \text{pOH} = -\log[\text{OH}^-], \quad \text{pH} + \text{pOH} = 14', 'Logarithmic acidity scale at 25 °C, where [H⁺][OH⁻] = 1.0 × 10⁻¹⁴.', '[{"symbol":"[\\text{H}^+]","meaning":"hydrogen ion concentration","unit":"M"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_feaf87dea7bc10', 'subj_chem', 'equilibrium-constant', 'Equilibrium constant', 'aA + bB \rightleftharpoons cC + dD: \quad K = \frac{[C]^c[D]^d}{[A]^a[B]^b}', 'Law of mass action; compare the reaction quotient Q with K to predict the direction of shift.', '[{"symbol":"K","meaning":"equilibrium constant"},{"symbol":"Q","meaning":"reaction quotient"}]', 'published');

-- Lesson: acids-bases-definitions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7c8ea5da5e2bc6', 'acids-bases-definitions', 'Properties and definitions of acids and bases', 'Describe acid and base properties, apply the Arrhenius and Brønsted–Lowry definitions, identify conjugate pairs, and distinguish strong from weak.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7bdfd1061d7494', 'les_7c8ea5da5e2bc6', 1, 'Describe properties of acids and bases.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4e2d9874d13277', 'les_7c8ea5da5e2bc6', 2, 'Apply Arrhenius (H⁺/OH⁻) and Brønsted–Lowry (proton donor/acceptor) definitions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd690f723a4e73', 'les_7c8ea5da5e2bc6', 3, 'Identify conjugate acid–base pairs and strong versus weak acids.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bdfd1061d7494', 'les_7c8ea5da5e2bc6', 'learn', 1, 'definition', '{"term":"Properties","body":"Acids taste sour, turn blue litmus red and react with active metals to give H₂. Bases taste bitter, feel slippery and turn red litmus blue. Never taste lab chemicals."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4e2d9874d13277', 'les_7c8ea5da5e2bc6', 'learn', 2, 'definition', '{"term":"Definitions","body":"Arrhenius: acids produce H⁺ (as H₃O⁺) in water; bases produce OH⁻. Brønsted–Lowry: acids donate protons; bases accept them. Removing H⁺ from an acid gives its conjugate base."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd690f723a4e73', 'les_7c8ea5da5e2bc6', 'learn', 3, 'worked_example', '{"title":"NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","steps":[{"latex":"\\text{NH}_3 \\to \\text{NH}_4^+","explanation":"NH₃ accepts H⁺, so it''s the base; NH₄⁺ is its conjugate acid."},{"latex":"\\text{H}_2\\text{O} \\to \\text{OH}^-","explanation":"Water donates H⁺, so it''s the acid; OH⁻ is its conjugate base. Water can act as either."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e16b2125773041', 'les_7c8ea5da5e2bc6', 'learn', 4, 'definition', '{"term":"Strong and weak","body":"Strong acids ionize completely in water: HCl, HBr, HI, HNO₃, H₂SO₄, HClO₄. Weak acids only partly: acetic acid, HF, carbonic acid. \"Strong\" describes ionization, not concentration."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ef957eaae0372f', 'les_7c8ea5da5e2bc6', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Stomach acid (HCl), antacids (bases), vinegar (acetic acid), and ocean acidification from dissolved CO₂."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bdfd1061d7494', 'les_7c8ea5da5e2bc6', 1, 'practice', 'multiple_choice', 1, 'Which is a strong acid?', '{"choices":["HF","CH₃COOH","HNO₃","H₂CO₃"],"answer":2}', '[]', 'One of the six common strong acids.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4e2d9874d13277', 'les_7c8ea5da5e2bc6', 2, 'practice', 'multiple_choice', 2, 'What is the conjugate base of HSO₄⁻?', '{"choices":["H₂SO₄","SO₄²⁻","HSO₃⁻","OH⁻"],"answer":1}', '[]', 'Remove one H⁺.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd690f723a4e73', 'les_7c8ea5da5e2bc6', 3, 'practice', 'multiple_choice', 2, 'In HCl + H₂O → H₃O⁺ + Cl⁻, water acts as…', '{"choices":["an acid","a base","a salt","a catalyst"],"answer":1}', '[]', 'It accepts a proton.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e16b2125773041', 'les_7c8ea5da5e2bc6', 4, 'review', 'multiple_choice', 3, 'A dilute solution of a strong acid and a concentrated solution of a weak acid differ mainly in…', '{"choices":["nothing","how much of the acid ionizes versus how much acid there is","color","their bases"],"answer":1}', '[]', 'Strength ≠ concentration.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_745130d4876933', 'subj_chem', 'acids-bases', 'Acids and bases', 'Proton donors and acceptors, pH and neutralization.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7c8ea5da5e2bc6', (SELECT id FROM concepts WHERE slug = 'acids-bases'));

-- Lesson: atomic-theory
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cbbafe51423d42', 'atomic-theory', 'Atomic theory and subatomic particles', 'Trace atomic models from Dalton to Bohr, describe protons, neutrons and electrons, and count particles in atoms and ions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5f911caedb6aa5', 'les_cbbafe51423d42', 1, 'Summarize Dalton''s theory and the experiments of Thomson and Rutherford.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eaecfab63dc62d', 'les_cbbafe51423d42', 2, 'Compare the charge, mass and location of protons, neutrons and electrons.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_37b68fc1a1ece4', 'les_cbbafe51423d42', 3, 'Count protons, neutrons and electrons from atomic number, mass number and charge.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f911caedb6aa5', 'les_cbbafe51423d42', 'learn', 1, 'definition', '{"term":"Models of the atom","body":"Dalton (1803): elements are made of identical atoms that combine in whole-number ratios. Thomson (1897) discovered electrons with cathode rays: the \"plum pudding\" model. Rutherford (1911) fired alpha particles at gold foil; a few bounced back, revealing a tiny, dense, positive nucleus. Bohr (1913) put electrons in fixed energy levels."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaecfab63dc62d', 'les_cbbafe51423d42', 'learn', 2, 'definition', '{"term":"Particles","body":"Protons: +1 charge, about 1 u, in the nucleus. Neutrons: neutral, about 1 u, in the nucleus. Electrons: −1 charge, about $\\frac{1}{1836}$ u, around the nucleus. The atomic number Z counts protons and identifies the element; the mass number A = protons + neutrons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37b68fc1a1ece4', 'les_cbbafe51423d42', 'learn', 3, 'worked_example', '{"title":"Chlorine-37 and the Mg²⁺ ion","steps":[{"latex":"^{37}_{17}\\text{Cl}:\\ 17\\ p,\\ 37 - 17 = 20\\ n,\\ 17\\ e^-","explanation":""},{"latex":"^{24}_{12}\\text{Mg}^{2+}:\\ 12\\ p,\\ 12\\ n,\\ 12 - 2 = 10\\ e^-","explanation":"Positive ions have lost electrons."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d504b0b461ee6', 'les_cbbafe51423d42', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rutherford-style scattering is still used to analyze materials; mass spectrometers sort atoms by mass to identify substances."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f911caedb6aa5', 'les_cbbafe51423d42', 1, 'practice', 'numeric', 1, 'How many neutrons are in iron-56 (Z = 26)?', '{"answer":30}', '[]', '$56 - 26$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eaecfab63dc62d', 'les_cbbafe51423d42', 2, 'practice', 'numeric', 2, 'How many electrons does the sulfide ion S²⁻ (Z = 16) have?', '{"answer":18}', '[]', 'Negative ions gain electrons: $16 + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37b68fc1a1ece4', 'les_cbbafe51423d42', 3, 'practice', 'multiple_choice', 2, 'Rutherford''s gold-foil experiment showed that atoms…', '{"choices":["are solid spheres","have a small, dense, positive nucleus","contain electrons","have energy levels"],"answer":1}', '[]', 'Rare large-angle deflections.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d504b0b461ee6', 'les_cbbafe51423d42', 4, 'review', 'multiple_choice', 3, 'What identifies an element?', '{"choices":["its number of neutrons","its mass number","its number of protons","its number of electrons"],"answer":2}', '[]', 'The atomic number Z.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4627f09e2fbf74', 'subj_chem', 'atomic-structure', 'Atomic structure', 'The particles inside atoms and how electrons are arranged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cbbafe51423d42', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));

-- Lesson: balancing-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ffe2c9c0357c3b', 'balancing-equations', 'Writing and balancing chemical equations', 'Translate word equations into chemical equations with state symbols, and balance them by adjusting coefficients so atoms are conserved.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0d56b4a3bee3b', 'les_ffe2c9c0357c3b', 1, 'Write chemical equations with formulas and state symbols (s, l, g, aq).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4263967cb2fb7', 'les_ffe2c9c0357c3b', 2, 'Balance equations by changing coefficients, never subscripts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ac5422ba0cc8b', 'les_ffe2c9c0357c3b', 3, 'Use a systematic order: elements in only one compound first, lone elements last.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0d56b4a3bee3b', 'les_ffe2c9c0357c3b', 'learn', 1, 'definition', '{"term":"Why balance","body":"Atoms are neither created nor destroyed, so each element must have the same count on both sides. Change only the coefficients; changing a subscript would change the substance (H₂O vs H₂O₂)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4263967cb2fb7', 'les_ffe2c9c0357c3b', 'learn', 2, 'worked_example', '{"title":"Propane burns: C₃H₈ + O₂ → CO₂ + H₂O","steps":[{"latex":"\\text{C}_3\\text{H}_8 + \\text{O}_2 \\to 3\\text{CO}_2 + \\text{H}_2\\text{O}","explanation":"Balance C first."},{"latex":"\\text{C}_3\\text{H}_8 + \\text{O}_2 \\to 3\\text{CO}_2 + 4\\text{H}_2\\text{O}","explanation":"Then H."},{"latex":"\\text{C}_3\\text{H}_8 + 5\\text{O}_2 \\to 3\\text{CO}_2 + 4\\text{H}_2\\text{O}","explanation":"O last: 6 + 4 = 10 atoms, so 5 O₂."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ac5422ba0cc8b', 'les_ffe2c9c0357c3b', 'learn', 3, 'worked_example', '{"title":"Iron rusts: Fe + O₂ → Fe₂O₃","steps":[{"latex":"4\\text{Fe} + 3\\text{O}_2 \\to 2\\text{Fe}_2\\text{O}_3","explanation":"Make O even on both sides (6), then balance Fe."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a0db0cfcda606', 'les_ffe2c9c0357c3b', 'experiment', 4, 'activity', '{"activity":"stoichiometry","title":"A balanced reaction in action"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc734215e23e76', 'les_ffe2c9c0357c3b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engine tuning (the ratio of fuel to air comes from the balanced combustion equation) and dosing reactants in industrial chemistry."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0d56b4a3bee3b', 'les_ffe2c9c0357c3b', 1, 'practice', 'numeric', 2, 'Balance __H₂ + __N₂ → __NH₃. What is the coefficient of H₂?', '{"answer":3}', '[]', '$3\text{H}_2 + \text{N}_2 \to 2\text{NH}_3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4263967cb2fb7', 'les_ffe2c9c0357c3b', 2, 'practice', 'numeric', 2, 'Balance __CH₄ + __O₂ → __CO₂ + __H₂O with lowest whole numbers. What is the sum of the coefficients?', '{"answer":6}', '[]', '1 + 2 + 1 + 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ac5422ba0cc8b', 'les_ffe2c9c0357c3b', 3, 'practice', 'numeric', 3, 'Balance __Al + __HCl → __AlCl₃ + __H₂. What is the coefficient of HCl?', '{"answer":6}', '[]', '$2\text{Al} + 6\text{HCl} \to 2\text{AlCl}_3 + 3\text{H}_2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a0db0cfcda606', 'les_ffe2c9c0357c3b', 4, 'review', 'multiple_choice', 3, 'Why can''t you balance H₂ + O₂ → H₂O by writing H₂O₂?', '{"choices":["it''s too hard","it changes the product to a different substance","subscripts aren''t allowed in equations","it doesn''t balance"],"answer":1}', '[]', 'H₂O₂ is hydrogen peroxide.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c310af44564c4d', 'subj_chem', 'chemical-reactions', 'Chemical reactions', 'How substances rearrange into new ones, described by balanced equations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ffe2c9c0357c3b', (SELECT id FROM concepts WHERE slug = 'chemical-reactions'));

-- Lesson: chem-measurement
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3cbee6bcb8b19b', 'chem-measurement', 'Measurement, significant figures and unit conversion', 'Use SI units and prefixes, count and round with significant figures, and convert units with dimensional analysis, including density.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_18a671b4d5680b', 'les_3cbee6bcb8b19b', 1, 'Use SI base units and metric prefixes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ee0772d13017b6', 'les_3cbee6bcb8b19b', 2, 'Count significant figures and apply the rules for calculations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2715dc6d0708b8', 'les_3cbee6bcb8b19b', 3, 'Convert units with conversion factors, including density, d = m/V.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_18a671b4d5680b', 'les_3cbee6bcb8b19b', 'learn', 1, 'definition', '{"term":"Significant figures","body":"All nonzero digits count; zeros between them count; leading zeros never count; trailing zeros count only with a decimal point. So 0.00450 has 3 significant figures and 1200 has 2. Multiplying or dividing: keep the fewest significant figures. Adding or subtracting: keep the fewest decimal places."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee0772d13017b6', 'les_3cbee6bcb8b19b', 'learn', 2, 'definition', '{"term":"Dimensional analysis","body":"Multiply by conversion factors equal to 1 (such as $\\frac{1000\\ \\text{mL}}{1\\ \\text{L}}$), arranged so unwanted units cancel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2715dc6d0708b8', 'les_3cbee6bcb8b19b', 'learn', 3, 'worked_example', '{"title":"What volume does 50.0 g of mercury (d = 13.6 g/mL) occupy?","steps":[{"latex":"V = 50.0\\ \\text{g}\\times\\tfrac{1\\ \\text{mL}}{13.6\\ \\text{g}} = 3.68\\ \\text{mL}","explanation":"Three significant figures."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1371061483c5fc', 'les_3cbee6bcb8b19b', 'learn', 4, 'worked_example', '{"title":"Convert 65 mi/h to m/s (1 mi = 1609 m)","steps":[{"latex":"65\\tfrac{\\text{mi}}{\\text{h}}\\times\\tfrac{1609\\ \\text{m}}{1\\ \\text{mi}}\\times\\tfrac{1\\ \\text{h}}{3600\\ \\text{s}}","explanation":""},{"latex":"\\approx 29\\ \\text{m/s}","explanation":"65 has two significant figures."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_398ea37c39104f', 'les_3cbee6bcb8b19b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Medication dosing in mg/kg, and the 1999 Mars Climate Orbiter, lost because one team used pound-seconds and another newton-seconds."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_18a671b4d5680b', 'les_3cbee6bcb8b19b', 1, 'practice', 'numeric', 1, 'How many significant figures are in 0.004050?', '{"answer":4}', '[]', '4, 0, 5 and the trailing 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee0772d13017b6', 'les_3cbee6bcb8b19b', 2, 'practice', 'numeric', 2, 'Find 12.0 × 3.1, rounded correctly.', '{"answer":37}', '[]', '37.2 rounds to 2 significant figures.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2715dc6d0708b8', 'les_3cbee6bcb8b19b', 3, 'practice', 'numeric', 2, 'A 25.0 mL sample has a mass of 19.7 g. Find its density, in g/mL.', '{"answer":0.788,"tolerance":0.001,"unit":"g/mL"}', '[]', '$\frac{19.7}{25.0}$ (it''s ethanol).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1371061483c5fc', 'les_3cbee6bcb8b19b', 4, 'review', 'multiple_choice', 3, '2.50 L in mL, with correct significant figures, is…', '{"choices":["2500 mL","2.50 × 10³ mL","250 mL","2.5 × 10³ mL"],"answer":1}', '[]', 'Scientific notation keeps 3 significant figures.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c7bb9f61d2349', 'subj_chem', 'matter', 'Matter', 'Anything with mass and volume, classified as pure substances or mixtures.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3cbee6bcb8b19b', (SELECT id FROM concepts WHERE slug = 'matter'));

-- Lesson: classifying-matter
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a345ba1b2e75ff', 'classifying-matter', 'Classifying matter', 'Sort matter into elements, compounds and mixtures, tell homogeneous from heterogeneous mixtures, and choose separation methods.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ac80bc6506a449', 'les_a345ba1b2e75ff', 1, 'Distinguish elements, compounds and mixtures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d365d432e773b4', 'les_a345ba1b2e75ff', 2, 'Tell homogeneous mixtures (solutions) from heterogeneous ones.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0f9ac1dd999175', 'les_a345ba1b2e75ff', 3, 'Choose a method to separate a mixture: filtration, distillation, evaporation or chromatography.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac80bc6506a449', 'les_a345ba1b2e75ff', 'learn', 1, 'definition', '{"term":"Pure substances","body":"An element contains only one kind of atom (iron, oxygen gas). A compound has two or more elements chemically combined in a fixed ratio (water is always 2 H : 1 O by atoms) and can only be separated by chemical reactions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d365d432e773b4', 'les_a345ba1b2e75ff', 'learn', 2, 'definition', '{"term":"Mixtures","body":"A mixture is a physical combination in any proportion. Homogeneous mixtures (solutions such as salt water, air or brass) look uniform throughout. Heterogeneous mixtures (salad, sand in water) have visibly different parts."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f9ac1dd999175', 'les_a345ba1b2e75ff', 'learn', 3, 'definition', '{"term":"Separating mixtures","body":"Filtration removes undissolved solids; evaporation recovers a dissolved solid; distillation separates liquids by boiling point; chromatography separates by how strongly components stick to a surface."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d194248191223', 'les_a345ba1b2e75ff', 'learn', 4, 'worked_example', '{"title":"A mixture contains 20 g of salt dissolved in 80 g of water","steps":[{"latex":"\\text{mass percent salt} = \\tfrac{20}{20 + 80}\\times100\\% = 20\\%","explanation":"A homogeneous mixture; evaporation recovers the salt."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e88a00d624cc2', 'les_a345ba1b2e75ff', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Water treatment plants filter, settle and disinfect; oil refineries use fractional distillation; forensic labs use chromatography to identify inks and drugs."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac80bc6506a449', 'les_a345ba1b2e75ff', 1, 'practice', 'multiple_choice', 1, 'Which is a compound?', '{"choices":["oxygen gas","salt water","carbon dioxide","brass"],"answer":2}', '[]', 'CO₂ has two elements chemically combined.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d365d432e773b4', 'les_a345ba1b2e75ff', 2, 'practice', 'multiple_choice', 2, 'Air is best classified as…', '{"choices":["an element","a compound","a homogeneous mixture","a heterogeneous mixture"],"answer":2}', '[]', 'Uniform, with variable composition.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f9ac1dd999175', 'les_a345ba1b2e75ff', 3, 'practice', 'numeric', 2, '15 g of sugar dissolves in 135 g of water. Find the mass percent of sugar.', '{"answer":10,"unit":"%"}', '[]', '$\frac{15}{150}\times100$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d194248191223', 'les_a345ba1b2e75ff', 4, 'review', 'multiple_choice', 3, 'To separate ethanol (bp 78 °C) from water, the best method is…', '{"choices":["filtration","distillation","a magnet","decanting"],"answer":1}', '[]', 'Different boiling points.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c7bb9f61d2349', 'subj_chem', 'matter', 'Matter', 'Anything with mass and volume, classified as pure substances or mixtures.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a345ba1b2e75ff', (SELECT id FROM concepts WHERE slug = 'matter'));

-- Lesson: collision-theory-rates
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_54bacd10639587', 'collision-theory-rates', 'Collision theory and reaction rates', 'Explain reaction rates with collision theory and activation energy, compute average rates from data, and predict how concentration, temperature, surface area and catalysts change the rate.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_16fcdc5a20cd47', 'les_54bacd10639587', 1, 'Explain collision theory: particles must collide with enough energy and the right orientation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d6ceddf475be3f', 'les_54bacd10639587', 2, 'Compute an average rate, −Δ[A]/Δt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af7a1c72620cd4', 'les_54bacd10639587', 3, 'Predict the effects of concentration, temperature, surface area and catalysts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16fcdc5a20cd47', 'les_54bacd10639587', 'learn', 1, 'definition', '{"term":"Collision theory","body":"Reactions happen when particles collide with at least the activation energy Eₐ and in a suitable orientation. Anything that raises the number of effective collisions per second raises the rate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d6ceddf475be3f', 'les_54bacd10639587', 'learn', 2, 'definition', '{"term":"Factors","body":"Higher concentration (or pressure) means more collisions. Higher temperature means faster particles: more collisions, and a much larger fraction above Eₐ. More surface area (powders) means more exposed particles. A catalyst lowers Eₐ by providing another pathway, without being used up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af7a1c72620cd4', 'les_54bacd10639587', 'learn', 3, 'worked_example', '{"title":"[A] drops from 0.80 M to 0.50 M in 30 s","steps":[{"latex":"\\text{rate} = -\\tfrac{\\Delta[A]}{\\Delta t} = -\\tfrac{0.50 - 0.80}{30}","explanation":""},{"latex":"\\text{rate} = 0.010\\ \\text{M/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_363ef6c9c48e43', 'les_54bacd10639587', 'experiment', 4, 'activity', '{"activity":"kinetics","title":"Temperature and activation energy","params":{"order":"1","k":0.1,"A0":1,"temperature":298,"Ea":50}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e65f57b4fd7179', 'les_54bacd10639587', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Raise the temperature from 298 K to 308 K with Eₐ = 50 kJ/mol: the rate constant roughly doubles, the old \"10-degree rule\". Then lower Eₐ, as a catalyst would."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3caf9cadef57c2', 'les_54bacd10639587', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Refrigerators slow spoilage, catalytic converters clean exhaust, and grain-dust explosions show what huge surface area can do."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16fcdc5a20cd47', 'les_54bacd10639587', 1, 'practice', 'numeric', 2, '[B] rises from 0 to 0.24 M in 60 s. Find the average rate of formation, in M/s.', '{"answer":0.004,"tolerance":0.0001,"unit":"M/s"}', '[]', '$\frac{0.24}{60}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d6ceddf475be3f', 'les_54bacd10639587', 2, 'practice', 'multiple_choice', 2, 'A catalyst speeds up a reaction by…', '{"choices":["raising the temperature","lowering the activation energy","adding reactants","changing ΔH"],"answer":1}', '[]', 'It offers a lower-energy pathway.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af7a1c72620cd4', 'les_54bacd10639587', 3, 'practice', 'multiple_choice', 2, 'Why does powdered sugar dissolve faster than a sugar cube?', '{"choices":["it''s a different compound","more surface area","higher temperature","it''s lighter"],"answer":1}', '[]', 'More particles exposed.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_363ef6c9c48e43', 'les_54bacd10639587', 4, 'review', 'multiple_choice', 3, 'Raising temperature speeds reactions mainly because…', '{"choices":["particles get bigger","a larger fraction of collisions exceeds Eₐ","Eₐ decreases","fewer collisions happen"],"answer":1}', '[]', 'The energy distribution shifts upward.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b5a2446cb394cd', 'subj_chem', 'kinetics', 'Chemical kinetics', 'Reaction rates, rate laws and what controls how fast reactions go.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_54bacd10639587', (SELECT id FROM concepts WHERE slug = 'kinetics'));

-- Lesson: covalent-lewis
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8a9b8c25ddcbac', 'covalent-lewis', 'Covalent bonding and Lewis structures', 'Explain covalent bonds as shared electron pairs, draw Lewis structures by counting valence electrons, and recognize multiple bonds.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8dd2563db62463', 'les_8a9b8c25ddcbac', 1, 'Explain covalent bonding between nonmetals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_425b466861efb4', 'les_8a9b8c25ddcbac', 2, 'Draw Lewis structures: count valence electrons, connect atoms, complete octets.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9db201c2c73a8e', 'les_8a9b8c25ddcbac', 3, 'Recognize when double or triple bonds are needed.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8dd2563db62463', 'les_8a9b8c25ddcbac', 'learn', 1, 'definition', '{"term":"Shared pairs","body":"Nonmetals bond by sharing electron pairs so each atom reaches a stable octet (2 for hydrogen). A single bond shares one pair, a double bond two, a triple bond three. More shared pairs means a shorter, stronger bond."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_425b466861efb4', 'les_8a9b8c25ddcbac', 'learn', 2, 'definition', '{"term":"Drawing Lewis structures","body":"1. Add up all valence electrons. 2. Put the least electronegative atom in the center (never H) and connect atoms with single bonds. 3. Complete the outer atoms'' octets with lone pairs. 4. Put leftover electrons on the central atom. 5. If the central atom lacks an octet, turn lone pairs into multiple bonds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9db201c2c73a8e', 'les_8a9b8c25ddcbac', 'learn', 3, 'worked_example', '{"title":"Carbon dioxide, CO₂","steps":[{"latex":"4 + 2(6) = 16\\ \\text{valence electrons}","explanation":""},{"latex":"\\text{O–C–O}","explanation":"Completing the oxygens'' octets uses all 16 electrons, leaving carbon with only 4: no octet."},{"latex":"\\text{O=C=O}","explanation":"Move one lone pair from each O into a double bond."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8d4922ee31a4bd', 'les_8a9b8c25ddcbac', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Lewis structures predict which molecules are reactive: O₂''s double bond, N₂''s very strong triple bond (why nitrogen gas is so unreactive) and the radicals in smog."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8dd2563db62463', 'les_8a9b8c25ddcbac', 1, 'practice', 'numeric', 1, 'How many valence electrons are in NH₃?', '{"answer":8}', '[]', '$5 + 3(1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_425b466861efb4', 'les_8a9b8c25ddcbac', 2, 'practice', 'numeric', 2, 'How many lone pairs are on the oxygen in H₂O?', '{"answer":2}', '[]', '8 electrons: 2 bonds and 2 lone pairs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9db201c2c73a8e', 'les_8a9b8c25ddcbac', 3, 'practice', 'multiple_choice', 2, 'N₂ contains a…', '{"choices":["single bond","double bond","triple bond","ionic bond"],"answer":2}', '[]', '10 valence electrons: N≡N with one lone pair on each N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8d4922ee31a4bd', 'les_8a9b8c25ddcbac', 4, 'review', 'multiple_choice', 3, 'Which bond is strongest?', '{"choices":["C–C","C=C","C≡C","all equal"],"answer":2}', '[]', 'More shared pairs.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_793ae6aa1f37d6', 'subj_chem', 'chemical-bonding', 'Chemical bonding', 'Ionic, covalent and metallic bonds and the shapes and polarity of molecules.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8a9b8c25ddcbac', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: electron-configurations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e292acb290c036', 'electron-configurations', 'Electron configurations', 'Write electron configurations and orbital diagrams with the Aufbau principle, Pauli exclusion and Hund''s rule, use noble-gas shorthand, and count valence electrons.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e1bef64f17d1f', 'les_e292acb290c036', 1, 'Fill orbitals in Aufbau order: 1s 2s 2p 3s 3p 4s 3d 4p…');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bda02f88513803', 'les_e292acb290c036', 2, 'Apply the Pauli exclusion principle and Hund''s rule in orbital diagrams.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6106de90ce130e', 'les_e292acb290c036', 3, 'Write noble-gas shorthand and identify valence electrons.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e1bef64f17d1f', 'les_e292acb290c036', 'learn', 1, 'definition', '{"term":"Orbitals","body":"Energy levels (n = 1, 2, 3…) contain sublevels s, p, d and f with 1, 3, 5 and 7 orbitals. Each orbital holds 2 electrons with opposite spins (Pauli). Electrons fill the lowest energy first (Aufbau), and spread out singly within a sublevel before pairing (Hund)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bda02f88513803', 'les_e292acb290c036', 'learn', 2, 'worked_example', '{"title":"Oxygen (8 electrons) and iron (26)","steps":[{"latex":"\\text{O}:\\ 1s^2\\,2s^2\\,2p^4","explanation":"Two of the three 2p orbitals have one unpaired electron each."},{"latex":"\\text{Fe}:\\ [\\text{Ar}]\\,4s^2\\,3d^6","explanation":"4s fills before 3d."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6106de90ce130e', 'les_e292acb290c036', 'learn', 3, 'definition', '{"term":"Valence electrons","body":"The electrons in the outermost energy level drive chemical behavior. Main-group elements in the same group share the same valence count: Group 1 has 1, Group 17 has 7."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_39c4b4a6ca24db', 'les_e292acb290c036', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electron configurations explain magnetism (iron''s unpaired d electrons), the colors of transition-metal compounds, and why the periodic table has its shape."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e1bef64f17d1f', 'les_e292acb290c036', 1, 'practice', 'numeric', 2, 'How many unpaired electrons does nitrogen (1s² 2s² 2p³) have?', '{"answer":3}', '[]', 'Hund''s rule: one in each 2p orbital.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bda02f88513803', 'les_e292acb290c036', 2, 'practice', 'numeric', 2, 'How many valence electrons does phosphorus ([Ne] 3s² 3p³) have?', '{"answer":5}', '[]', '$2 + 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6106de90ce130e', 'les_e292acb290c036', 3, 'practice', 'multiple_choice', 2, 'Which is the correct configuration for sulfur (16 e⁻)?', '{"choices":["1s² 2s² 2p⁶ 3s² 3p⁴","1s² 2s² 2p⁶ 3s⁶","1s² 2s² 2p⁸ 3s² 3p²","[Ar] 3s² 3p⁴"],"answer":0}', '[]', 'Fill in order to 16.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_39c4b4a6ca24db', 'les_e292acb290c036', 4, 'review', 'multiple_choice', 3, 'Which rule says two electrons in one orbital must have opposite spins?', '{"choices":["Aufbau","Hund''s rule","Pauli exclusion","octet rule"],"answer":2}', '[]', 'No two electrons share all quantum numbers.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4627f09e2fbf74', 'subj_chem', 'atomic-structure', 'Atomic structure', 'The particles inside atoms and how electrons are arranged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e292acb290c036', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));

-- Lesson: em-ampere-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b5176dea0545be', 'em-ampere-law', 'Ampère''s law', 'Apply Ampère''s law with symmetric loops to find fields inside and outside thick wires, solenoids and toroids.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_570a557f7817c6', 'les_b5176dea0545be', 1, 'State Ampère''s law, ∮B·dℓ = μ₀I_enc.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9b80af58ac1515', 'les_b5176dea0545be', 2, 'Find B inside and outside a thick wire with uniform current.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1410a5120e7e11', 'les_b5176dea0545be', 3, 'Derive B = μ₀nI for a solenoid and B = μ₀NI/(2πr) for a toroid.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_570a557f7817c6', 'les_b5176dea0545be', 'learn', 1, 'definition', '{"term":"Ampère''s law","body":"For any closed loop, $\\oint\\vec B\\cdot d\\vec\\ell = \\mu_0I_{enc}$. Like Gauss''s law, it''s always true but useful only when symmetry makes $B$ constant and tangent along an Amperian loop."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9b80af58ac1515', 'les_b5176dea0545be', 'learn', 2, 'worked_example', '{"title":"A thick wire of radius R = 4 mm carrying 10 A uniformly; find B at r = 2 mm","steps":[{"latex":"I_{enc} = I\\tfrac{r^2}{R^2}","explanation":""},{"latex":"B(2\\pi r) = \\mu_0 I\\tfrac{r^2}{R^2} \\Rightarrow B = \\tfrac{\\mu_0 Ir}{2\\pi R^2}","explanation":""},{"latex":"B = \\tfrac{(4\\pi\\times10^{-7})(10)(0.002)}{2\\pi(0.004)^2}","explanation":""},{"latex":"B = 2.5\\times10^{-4}\\ \\text{T}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1410a5120e7e11', 'les_b5176dea0545be', 'learn', 3, 'definition', '{"term":"Solenoids and toroids","body":"A rectangular loop half inside a long solenoid gives $BL = \\mu_0nLI$, so $B = \\mu_0nI$ inside (n turns per meter) and nearly zero outside. In a toroid of N turns, a circular loop gives $B = \\frac{\\mu_0NI}{2\\pi r}$, confined inside the windings."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_41bc452a98f44f', 'les_b5176dea0545be', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Solenoids are electromagnets, relays and MRI bores; tokamak fusion reactors use toroidal fields to confine plasma."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_570a557f7817c6', 'les_b5176dea0545be', 1, 'practice', 'numeric', 2, 'A solenoid with 2000 turns/m carries 3 A. Find B inside, in mT, to two decimal places.', '{"answer":7.54,"tolerance":0.01,"unit":"mT"}', '[]', '$4\pi\times10^{-7}(2000)(3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9b80af58ac1515', 'les_b5176dea0545be', 2, 'practice', 'numeric', 2, 'A toroid with 500 turns carries 2 A. Find B at r = 0.1 m, in mT.', '{"answer":2,"tolerance":0.001,"unit":"mT"}', '[]', '$\frac{4\pi\times10^{-7}(1000)}{2\pi(0.1)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1410a5120e7e11', 'les_b5176dea0545be', 3, 'practice', 'multiple_choice', 2, 'For the thick wire, B is largest at…', '{"choices":["the center","the surface","far away","it''s constant"],"answer":1}', '[]', 'It grows linearly inside, then falls as 1/r.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_41bc452a98f44f', 'les_b5176dea0545be', 4, 'review', 'multiple_choice', 3, 'A loop around a wire carrying 5 A up and another carrying 5 A down has ∮B·dℓ equal to…', '{"choices":["10μ₀","5μ₀","0","−5μ₀"],"answer":2}', '[]', 'The net enclosed current is zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b5176dea0545be', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b5176dea0545be', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 1);

-- Lesson: em-biot-savart
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2024a32d4a054d', 'em-biot-savart', 'Magnetic fields of current-carrying wires and the Biot–Savart law', 'Use the Biot–Savart law to find magnetic fields at the center of loops and arcs and near straight wires, and combine them by superposition.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_06504bd38db2fc', 'les_2024a32d4a054d', 1, 'State the Biot–Savart law, dB = (μ₀/4π) I dℓ × r̂/r².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a506c5a8c81f8e', 'les_2024a32d4a054d', 2, 'Derive B at the center of a loop, μ₀I/(2R), and of an arc, μ₀Iθ/(4πR).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_93f6a590b3cf24', 'les_2024a32d4a054d', 3, 'Find B near a long straight wire, μ₀I/(2πd), and combine segments.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06504bd38db2fc', 'les_2024a32d4a054d', 'learn', 1, 'definition', '{"term":"Biot–Savart law","body":"Each current element contributes $d\\vec B = \\frac{\\mu_0}{4\\pi}\\frac{I\\,d\\vec\\ell\\times\\hat r}{r^2}$, with $\\mu_0 = 4\\pi\\times10^{-7}$ T·m/A. It''s the magnetic analog of Coulomb''s law: integrate along the wire."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a506c5a8c81f8e', 'les_2024a32d4a054d', 'learn', 2, 'worked_example', '{"title":"The center of a circular loop of radius R","steps":[{"latex":"d\\vec\\ell \\perp \\hat r\\ \\text{everywhere, and}\\ r = R","explanation":""},{"latex":"B = \\tfrac{\\mu_0 I}{4\\pi R^2}\\oint d\\ell = \\tfrac{\\mu_0I}{4\\pi R^2}(2\\pi R)","explanation":""},{"latex":"B = \\tfrac{\\mu_0I}{2R}","explanation":""},{"latex":"I = 5\\ \\text{A},\\ R = 0.1\\ \\text{m}:\\ B \\approx 3.14\\times10^{-5}\\ \\text{T}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93f6a590b3cf24', 'les_2024a32d4a054d', 'learn', 3, 'definition', '{"term":"Arcs and straight wires","body":"An arc subtending angle $\\theta$ gives $B = \\frac{\\mu_0I\\theta}{4\\pi R}$ at its center: a quarter circle gives a quarter of the full loop. Straight segments pointing directly at the center contribute nothing ($d\\vec\\ell\\parallel\\hat r$). Integrating along an infinite straight wire gives $B = \\frac{\\mu_0I}{2\\pi d}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e560e9e80c187d', 'les_2024a32d4a054d', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"MRI and particle-detector magnet coils are designed by integrating Biot–Savart over every turn."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06504bd38db2fc', 'les_2024a32d4a054d', 1, 'practice', 'numeric', 2, 'Find B at the center of a quarter-circle arc (R = 0.1 m, I = 5 A) with straight leads pointing at the center, in μT, to two decimal places.', '{"answer":7.85,"tolerance":0.02,"unit":"μT"}', '[]', '$\frac{\mu_0I}{8R} = \frac{4\pi\times10^{-7}(5)}{0.8}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a506c5a8c81f8e', 'les_2024a32d4a054d', 2, 'practice', 'numeric', 2, 'A 20-turn flat coil of radius 0.05 m carries 2 A. Find B at its center, in mT, to three decimal places.', '{"answer":0.503,"tolerance":0.002,"unit":"mT"}', '[]', '$20\frac{\mu_0I}{2R}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93f6a590b3cf24', 'les_2024a32d4a054d', 3, 'practice', 'multiple_choice', 2, 'A straight wire segment aimed directly at point P contributes ___ to B at P.', '{"choices":["the most","nothing","half","a negative amount"],"answer":1}', '[]', '$d\vec\ell\times\hat r = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e560e9e80c187d', 'les_2024a32d4a054d', 4, 'review', 'multiple_choice', 3, 'Doubling a loop''s radius (same current) changes B at its center by a factor of…', '{"choices":["2","½","4","¼"],"answer":1}', '[]', '$B \propto \frac1R$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2024a32d4a054d', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2024a32d4a054d', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: em-capacitance-calculus
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e5c8fe86a5d44b', 'em-capacitance-calculus', 'Capacitors and capacitance', 'Derive capacitance from Gauss''s law and ΔV = −∫E·dr for parallel-plate, spherical and cylindrical capacitors, and find stored energy and energy density.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f27ccce02a65e8', 'les_e5c8fe86a5d44b', 1, 'Follow the recipe: assume ±Q, find E by Gauss''s law, integrate for ΔV, then C = Q/ΔV.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b94157243b253', 'les_e5c8fe86a5d44b', 2, 'Derive C for parallel-plate, spherical and cylindrical geometries.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a151985dcadc8e', 'les_e5c8fe86a5d44b', 3, 'Compute stored energy ½CV² and energy density u = ½ε₀E².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f27ccce02a65e8', 'les_e5c8fe86a5d44b', 'learn', 1, 'definition', '{"term":"Recipe","body":"1. Put $+Q$ and $-Q$ on the conductors. 2. Use Gauss''s law for E between them. 3. Integrate $\\Delta V = \\int E\\,dr$. 4. $C = \\frac{Q}{\\Delta V}$, which depends only on geometry."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b94157243b253', 'les_e5c8fe86a5d44b', 'learn', 2, 'worked_example', '{"title":"Spherical capacitor: inner radius a, outer radius b","steps":[{"latex":"E = \\tfrac{kQ}{r^2}\\ (a < r < b)","explanation":""},{"latex":"\\Delta V = kQ\\left(\\tfrac1a - \\tfrac1b\\right)","explanation":""},{"latex":"C = \\tfrac{4\\pi\\varepsilon_0ab}{b - a}","explanation":"For a = 0.1 m, b = 0.2 m: C ≈ 22.3 pF."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a151985dcadc8e', 'les_e5c8fe86a5d44b', 'learn', 3, 'worked_example', '{"title":"Cylindrical capacitor (coaxial cable), length ℓ","steps":[{"latex":"E = \\tfrac{\\lambda}{2\\pi\\varepsilon_0 r}","explanation":""},{"latex":"\\Delta V = \\tfrac{\\lambda}{2\\pi\\varepsilon_0}\\ln\\tfrac ba","explanation":""},{"latex":"C = \\tfrac{2\\pi\\varepsilon_0\\ell}{\\ln(b/a)}","explanation":"For b/a = 2: about 80 pF per meter."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4429c2981baf5', 'les_e5c8fe86a5d44b', 'learn', 4, 'definition', '{"term":"Energy","body":"Charging takes work $\\int_0^Q\\frac{q}{C}\\,dq = \\frac{Q^2}{2C} = \\frac12CV^2$. The energy lives in the field with density $u = \\frac12\\varepsilon_0E^2$ (J/m³)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0eb2ba48115341', 'les_e5c8fe86a5d44b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Coaxial cables have a capacitance per meter that limits signal speed; supercapacitors store kilojoules in porous electrodes with huge effective areas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f27ccce02a65e8', 'les_e5c8fe86a5d44b', 1, 'practice', 'numeric', 2, 'Find the energy density in a 1 × 10⁵ V/m field, in mJ/m³, to two decimal places.', '{"answer":44.27,"tolerance":0.05,"unit":"mJ/m³"}', '[]', '$\frac12(8.854\times10^{-12})(10^{10})$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b94157243b253', 'les_e5c8fe86a5d44b', 2, 'practice', 'numeric', 3, 'A coaxial cable has a = 0.5 mm and b = 2 mm. Find its capacitance per meter, in pF.', '{"answer":40.1,"tolerance":0.2,"unit":"pF"}', '[]', '$\frac{2\pi\varepsilon_0}{\ln 4} \approx 4.01\times10^{-11}$ F/m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a151985dcadc8e', 'les_e5c8fe86a5d44b', 3, 'practice', 'multiple_choice', 2, 'An isolated charged capacitor''s plates are pulled farther apart. Its stored energy…', '{"choices":["decreases","increases (you did work)","stays the same","becomes zero"],"answer":1}', '[]', 'Q fixed, C falls, $U = \frac{Q^2}{2C}$ rises.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d4429c2981baf5', 'les_e5c8fe86a5d44b', 4, 'review', 'multiple_choice', 3, 'Capacitance depends on…', '{"choices":["the charge stored","the voltage applied","geometry and the material between","the current"],"answer":2}', '[]', '$C = \frac QV$ but the ratio is set by geometry.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e5c8fe86a5d44b', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e5c8fe86a5d44b', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e5c8fe86a5d44b', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 2);

-- Lesson: em-charge-redistribution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f91a6ebb74ef6d', 'em-charge-redistribution', 'Redistribution of charge between conductors', 'Find how charge divides between connected conductors by equalizing their potentials, and explain why smaller spheres get higher surface densities.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5505b93b5759ca', 'les_f91a6ebb74ef6d', 1, 'Use the condition that connected conductors reach the same potential.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5d40ce1c8cab37', 'les_f91a6ebb74ef6d', 2, 'Divide charge between connected spheres: q₁/r₁ = q₂/r₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd62f3cd37a532', 'les_f91a6ebb74ef6d', 3, 'Compare surface charge densities and fields: σ ∝ 1/r.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5505b93b5759ca', 'les_f91a6ebb74ef6d', 'learn', 1, 'definition', '{"term":"Equal potentials","body":"When conductors are joined by a wire, charge flows until they''re at the same potential. For two distant spheres, $\\frac{kq_1}{r_1} = \\frac{kq_2}{r_2}$, together with charge conservation $q_1 + q_2 = Q$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d40ce1c8cab37', 'les_f91a6ebb74ef6d', 'learn', 2, 'worked_example', '{"title":"10 nC shared between spheres of radius 0.1 m and 0.3 m, far apart and joined by a thin wire","steps":[{"latex":"q_1 = Q\\tfrac{r_1}{r_1 + r_2} = 10\\tfrac{0.1}{0.4} = 2.5\\ \\text{nC}","explanation":""},{"latex":"q_2 = 7.5\\ \\text{nC}","explanation":"The bigger sphere takes more charge."},{"latex":"\\tfrac{\\sigma_1}{\\sigma_2} = \\tfrac{q_1/r_1^2}{q_2/r_2^2} = \\tfrac{r_2}{r_1} = 3","explanation":"But the small sphere has 3 times the surface density and field."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd62f3cd37a532', 'les_f91a6ebb74ef6d', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"This is why charge (and sparking) concentrates at sharp tips, and why grounding a charged object drains nearly all its charge to the enormous Earth."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5505b93b5759ca', 'les_f91a6ebb74ef6d', 1, 'practice', 'numeric', 2, 'Spheres of radii 2 cm and 6 cm are joined and share 16 nC. Find the charge on the small sphere.', '{"answer":4,"unit":"nC"}', '[]', '$16\cdot\frac{2}{8}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d40ce1c8cab37', 'les_f91a6ebb74ef6d', 2, 'practice', 'numeric', 2, 'Find the common potential of the spheres in the example, to the nearest volt.', '{"answer":225,"tolerance":1,"unit":"V"}', '[]', '$\frac{k(2.5\times10^{-9})}{0.1}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd62f3cd37a532', 'les_f91a6ebb74ef6d', 3, 'practice', 'multiple_choice', 2, 'A charged sphere touches a large grounded object. Afterward the sphere is nearly…', '{"choices":["fully charged","neutral","doubly charged","opposite charge"],"answer":1}', '[]', 'Earth''s huge size takes almost everything.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e38c43cd0955c1', 'les_f91a6ebb74ef6d', 4, 'review', 'multiple_choice', 3, 'After connection, which sphere has the stronger field at its surface?', '{"choices":["the larger","the smaller","equal","neither has a field"],"answer":1}', '[]', '$E = \frac{V}{r}$ with V shared.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f91a6ebb74ef6d', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f91a6ebb74ef6d', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: em-conductors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c4f0848fd9ddd3', 'em-conductors', 'Electrostatics with conductors', 'Use the properties of conductors in equilibrium: zero field inside, charge on the surface, equipotential volume, and E = σ/ε₀ just outside.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dbe80bbd3a44be', 'les_c4f0848fd9ddd3', 1, 'Explain why E = 0 inside a conductor in electrostatic equilibrium.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa0be9a5646624', 'les_c4f0848fd9ddd3', 2, 'Use Gauss''s law to show excess charge resides on the surface, with E = σ/ε₀ just outside.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5f833627460542', 'les_c4f0848fd9ddd3', 3, 'Explain shielding and why charge concentrates at sharp points.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dbe80bbd3a44be', 'les_c4f0848fd9ddd3', 'learn', 1, 'definition', '{"term":"Equilibrium rules","body":"Free charges in a conductor move until they feel no force, so $\\vec E = 0$ inside and the whole conductor is one equipotential. A Gaussian surface just inside the surface encloses zero charge, so any excess charge sits on the surface. Just outside, the field is perpendicular to the surface with $E = \\frac{\\sigma}{\\varepsilon_0}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa0be9a5646624', 'les_c4f0848fd9ddd3', 'learn', 2, 'worked_example', '{"title":"A conducting sphere of radius 0.1 m holds 6 nC","steps":[{"latex":"\\sigma = \\tfrac{6\\times10^{-9}}{4\\pi(0.1)^2} \\approx 4.77\\times10^{-8}\\ \\text{C/m}^2","explanation":""},{"latex":"E_{surface} = \\tfrac{\\sigma}{\\varepsilon_0} \\approx 5390\\ \\text{N/C}","explanation":"Equal to kQ/R², as it must be."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5f833627460542', 'les_c4f0848fd9ddd3', 'learn', 3, 'definition', '{"term":"Cavities and shielding","body":"An empty cavity inside a conductor has zero field, whatever charges sit outside: a Faraday cage. A charge $q$ placed in a cavity induces $-q$ on the cavity wall and $+q$ on the outer surface."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0277e367bc97e', 'les_c4f0848fd9ddd3', 'experiment', 4, 'activity', '{"activity":"gauss-field","title":"Conductor vs insulator","params":{"distribution":"shell","charge":6,"radius":0.1,"gaussian":0.05}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4c22483944ac1', 'les_c4f0848fd9ddd3', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Faraday cages shield MRI rooms and microwave ovens; lightning rods are sharp because the field, and so ionization, is strongest at points."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dbe80bbd3a44be', 'les_c4f0848fd9ddd3', 1, 'practice', 'numeric', 2, 'Find the field just outside a conductor with σ = 8.854 × 10⁻⁹ C/m².', '{"answer":1000,"unit":"N/C"}', '[]', '$\frac{\sigma}{\varepsilon_0}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa0be9a5646624', 'les_c4f0848fd9ddd3', 2, 'practice', 'numeric', 3, 'A +3 nC charge sits in a cavity inside a neutral conducting shell. How much charge is on the shell''s outer surface, in nC?', '{"answer":3,"unit":"nC"}', '[]', '−3 nC is induced on the cavity wall, leaving +3 nC outside.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5f833627460542', 'les_c4f0848fd9ddd3', 3, 'practice', 'multiple_choice', 2, 'Inside a solid charged conductor in equilibrium, the electric potential is…', '{"choices":["zero","constant, equal to the surface value","largest at the center","undefined"],"answer":1}', '[]', 'E = 0 means V doesn''t change.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e0277e367bc97e', 'les_c4f0848fd9ddd3', 4, 'review', 'multiple_choice', 3, 'On an irregularly shaped conductor, surface charge density is greatest where…', '{"choices":["the surface is flattest","the surface is most sharply curved","it''s thickest","it''s uniform"],"answer":1}', '[]', 'Sharp points have small radius of curvature.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c4f0848fd9ddd3', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c4f0848fd9ddd3', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 1);

-- Lesson: em-continuous-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9a2a7a7efbe745', 'em-continuous-distributions', 'Electric fields of point charges and continuous distributions', 'Integrate over charge elements to find the fields of rods, rings and infinite lines, using symmetry to cancel components.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f5c5055a75081', 'les_9a2a7a7efbe745', 1, 'Write dE = k dq/r² with dq = λ dx (or σ dA).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e58e1f76a46238', 'les_9a2a7a7efbe745', 2, 'Find the field on the axis of a finite rod and of a ring.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1056bf20de73e0', 'les_9a2a7a7efbe745', 3, 'Use symmetry to cancel perpendicular components, and find the field of an infinite line, λ/(2πε₀r).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f5c5055a75081', 'les_9a2a7a7efbe745', 'learn', 1, 'definition', '{"term":"Method","body":"Split the object into point-like pieces $dq$, write $d\\vec E = \\frac{k\\,dq}{r^2}\\hat r$ for each, and integrate component by component. Look for symmetry first: components that cancel in pairs don''t need integrating."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e58e1f76a46238', 'les_9a2a7a7efbe745', 'learn', 2, 'worked_example', '{"title":"A rod of length L and charge Q, at a point on its axis a distance d beyond one end","steps":[{"latex":"dE = \\tfrac{k\\lambda\\,dx}{x^2},\\ \\lambda = \\tfrac QL","explanation":"x is measured from the point."},{"latex":"E = k\\lambda\\int_d^{d+L}\\tfrac{dx}{x^2} = \\tfrac{kQ}{d(d + L)}","explanation":""},{"latex":"Q = 4\\ \\text{nC}","explanation":""},{"latex":"L = 0.2,\\ d = 0.1:\\ E \\approx 1.20\\times10^3\\ \\text{N/C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1056bf20de73e0', 'les_9a2a7a7efbe745', 'learn', 3, 'worked_example', '{"title":"A ring of radius R and charge Q, on its axis at distance x","steps":[{"latex":"dE_x = \\tfrac{k\\,dq}{x^2 + R^2}\\cdot\\tfrac{x}{\\sqrt{x^2 + R^2}}","explanation":"Perpendicular parts cancel around the ring."},{"latex":"E = \\tfrac{kQx}{(x^2 + R^2)^{3/2}}","explanation":"Zero at the center, and kQ/x² far away."},{"latex":"Q = 5\\ \\text{nC},\\ R = 0.3,\\ x = 0.4:\\ E \\approx 108\\ \\text{N/C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a74b547ddcca8', 'les_9a2a7a7efbe745', 'learn', 4, 'definition', '{"term":"Infinite line","body":"Integrating over an infinite line of charge density $\\lambda$ gives $E = \\frac{2k\\lambda}{r} = \\frac{\\lambda}{2\\pi\\varepsilon_0 r}$, pointing radially. It falls off as $\\frac1r$, not $\\frac1{r^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4591a8e2c5e57f', 'les_9a2a7a7efbe745', 'experiment', 5, 'activity', '{"activity":"gauss-field","title":"Field of an infinite line","params":{"distribution":"line","charge":2,"gaussian":0.05}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c37bc85a7fbfeb', 'les_9a2a7a7efbe745', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Power lines, coaxial cables and ion beams are modeled as line charges; ring and disk fields describe charged particle accelerators."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f5c5055a75081', 'les_9a2a7a7efbe745', 1, 'practice', 'numeric', 2, 'An infinite line with λ = 2 nC/m. Find E 5 cm away, to the nearest N/C.', '{"answer":719,"tolerance":1,"unit":"N/C"}', '[]', '$\frac{2k\lambda}{r} = \frac{2(8.99\times10^9)(2\times10^{-9})}{0.05}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e58e1f76a46238', 'les_9a2a7a7efbe745', 2, 'practice', 'numeric', 3, 'At what distance x on a ring''s axis is the field largest? Answer as a multiple of R, to three decimal places.', '{"answer":0.707,"tolerance":0.002}', '[]', '$\frac{d}{dx}\frac{x}{(x^2 + R^2)^{3/2}} = 0$ gives $x = \frac{R}{\sqrt2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1056bf20de73e0', 'les_9a2a7a7efbe745', 3, 'practice', 'multiple_choice', 2, 'At the center of a uniformly charged ring, the field is…', '{"choices":["maximum","zero","kQ/R²","infinite"],"answer":1}', '[]', 'Contributions cancel by symmetry.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a74b547ddcca8', 'les_9a2a7a7efbe745', 4, 'review', 'multiple_choice', 3, 'Far from a finite rod (d ≫ L), its field approaches…', '{"choices":["zero faster than 1/d²","kQ/d², like a point charge","a constant","λ/(2πε₀d)"],"answer":1}', '[]', '$d(d + L) \to d^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9a2a7a7efbe745', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9a2a7a7efbe745', (SELECT id FROM formulas WHERE slug = 'coulombs-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9a2a7a7efbe745', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 2);

-- Lesson: em-coulomb-vectors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3c384ce4ab57b4', 'em-coulomb-vectors', 'Electric charge and electric force', 'Write Coulomb''s law in vector form and use superposition to find the net force on a charge from several others in two dimensions.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ebf7c9e797571d', 'les_3c384ce4ab57b4', 1, 'Write Coulomb''s law as a vector: F = kq₁q₂ r̂/r².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_465f95c0280348', 'les_3c384ce4ab57b4', 2, 'Add forces from several charges by components (superposition).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96eb99480e74bc', 'les_3c384ce4ab57b4', 3, 'Use k = 1/(4πε₀) and ε₀ = 8.85 × 10⁻¹² C²/(N·m²).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ebf7c9e797571d', 'les_3c384ce4ab57b4', 'learn', 1, 'definition', '{"term":"Vector form","body":"The force on charge 2 from charge 1 is $\\vec F_{12} = \\frac{kq_1q_2}{r^2}\\hat r_{12} = \\frac{kq_1q_2}{r^3}\\vec r_{12}$, where $\\vec r_{12}$ points from 1 to 2 and $k = \\frac{1}{4\\pi\\varepsilon_0}$. A positive product means repulsion along $\\hat r$. Forces from several charges add as vectors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_465f95c0280348', 'les_3c384ce4ab57b4', 'learn', 2, 'worked_example', '{"title":"+1 μC at (0, 0.4) m; +2 μC at the origin; −3 μC at (0.3, 0) m. Find the force on the +1 μC charge","steps":[{"latex":"\\vec F_1 = \\tfrac{k(2\\times10^{-6})(10^{-6})}{0.4^2}\\,\\hat\\jmath","explanation":""},{"latex":"\\vec F_1 = 0.112\\,\\hat\\jmath\\ \\text{N}","explanation":"Repelled straight up."},{"latex":"|\\vec F_2| = \\tfrac{k(3\\times10^{-6})(10^{-6})}{0.5^2} = 0.108\\ \\text{N}","explanation":"Attracted toward (0.3, 0)."},{"latex":"\\vec F_2 = 0.108(0.6\\,\\hat\\imath - 0.8\\,\\hat\\jmath)","explanation":"Unit vector from (0, 0.4) toward (0.3, 0)."},{"latex":"\\vec F = (0.0647,\\ 0.0261)\\ \\text{N}","explanation":""},{"latex":"|\\vec F| \\approx 0.070\\ \\text{N at}\\ 21.9°","explanation":"Above the +x axis."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96eb99480e74bc', 'les_3c384ce4ab57b4', 'experiment', 3, 'activity', '{"activity":"electric-field","title":"Superposition of two charges","params":{"q1":2,"q2":-3,"separation":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82378f4195862e', 'les_3c384ce4ab57b4', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every molecular-dynamics simulation of proteins sums Coulomb forces from thousands of charges, exactly like this."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ebf7c9e797571d', 'les_3c384ce4ab57b4', 1, 'practice', 'numeric', 2, 'Two +3 μC charges sit at (±0.1, 0) m. Find the size of the net force on a +1 μC charge at (0, 0.1) m, to two decimal places.', '{"answer":1.91,"tolerance":0.01,"unit":"N"}', '[]', 'Each pair is $\frac{k(3\times10^{-12})}{0.02} \approx 1.35$ N at 45°; x components cancel, so $2(1.35)(0.707)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_465f95c0280348', 'les_3c384ce4ab57b4', 2, 'practice', 'numeric', 2, 'Find the force between +5 nC and −5 nC charges 2 cm apart, in mN, to two decimal places.', '{"answer":0.56,"tolerance":0.01,"unit":"mN"}', '[]', '$\frac{8.99\times10^9(25\times10^{-18})}{4\times10^{-4}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96eb99480e74bc', 'les_3c384ce4ab57b4', 3, 'practice', 'multiple_choice', 2, 'Superposition means the force from one charge…', '{"choices":["changes when others are added","is unaffected by other charges","is shielded by others","depends on the total charge"],"answer":1}', '[]', 'Forces add independently.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82378f4195862e', 'les_3c384ce4ab57b4', 4, 'review', 'multiple_choice', 3, 'Doubling one charge and halving the distance multiplies the force by…', '{"choices":["2","4","8","1"],"answer":2}', '[]', '$2 \times 2^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3c384ce4ab57b4', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3c384ce4ab57b4', (SELECT id FROM formulas WHERE slug = 'coulombs-law'), 1);

-- Lesson: em-current-density
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_07d05413f12ebb', 'em-current-density', 'Electric current', 'Define current as I = dQ/dt, relate it to current density and drift velocity, J = nqv_d, and find charge from a current function by integration.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd15308f47c6fb', 'les_07d05413f12ebb', 1, 'Use I = dQ/dt and Q = ∫I dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7da3d1e47816c5', 'les_07d05413f12ebb', 2, 'Define current density J = I/A and relate it to drift velocity: J = nqv_d.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9552add4fed9b', 'les_07d05413f12ebb', 3, 'Estimate drift speeds in metals.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd15308f47c6fb', 'les_07d05413f12ebb', 'learn', 1, 'definition', '{"term":"Current","body":"Current is the rate charge passes a point: $I = \\frac{dQ}{dt}$, so $Q = \\int I\\,dt$. Conventional current points the way positive charge would move, opposite to electron flow."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7da3d1e47816c5', 'les_07d05413f12ebb', 'learn', 2, 'worked_example', '{"title":"Charge through a wire is Q(t) = 3t² coulombs","steps":[{"latex":"I = \\tfrac{dQ}{dt} = 6t","explanation":""},{"latex":"I(2) = 12\\ \\text{A}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9552add4fed9b', 'les_07d05413f12ebb', 'learn', 3, 'definition', '{"term":"Drift velocity","body":"Current density is $J = \\frac IA$ (A/m²). In a conductor with $n$ free charges per m³, each of charge $q$ drifting at $v_d$: $J = nqv_d$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcde37df73cdab', 'les_07d05413f12ebb', 'learn', 4, 'worked_example', '{"title":"10 A in a copper wire of cross-section 1 mm² (n = 8.5 × 10²⁸ m⁻³)","steps":[{"latex":"v_d = \\tfrac{I}{nqA}","explanation":""},{"latex":"v_d = \\tfrac{10}{(8.5\\times10^{28})(1.6\\times10^{-19})(10^{-6})}","explanation":""},{"latex":"v_d \\approx 7.3\\times10^{-4}\\ \\text{m/s}","explanation":"Under a millimeter per second."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb526ab086caa0', 'les_07d05413f12ebb', 'learn', 5, 'callout', '{"tone":"note","title":"Why lights turn on instantly","body":"Electrons crawl, but the electric field that pushes them spreads along the wire at nearly the speed of light, so every electron starts moving almost at once."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4f5033b02d9d1', 'les_07d05413f12ebb', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Wire gauges limit current density to prevent overheating; electroplating deposits mass in proportion to ∫I dt."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd15308f47c6fb', 'les_07d05413f12ebb', 1, 'practice', 'numeric', 2, 'I(t) = 4e^{−t} A. How much charge passes from t = 0 to ∞?', '{"answer":4,"unit":"C"}', '[]', '$\int_0^\infty 4e^{-t}\,dt$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7da3d1e47816c5', 'les_07d05413f12ebb', 2, 'practice', 'numeric', 2, 'Find the current density for 2 A through a 0.5 mm² wire, in units of $10^6$ A/m².', '{"answer":4}', '[]', '$\frac{2}{5\times10^{-7}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9552add4fed9b', 'les_07d05413f12ebb', 3, 'practice', 'multiple_choice', 2, 'Doubling the current in the same wire doubles the…', '{"choices":["number of electrons per m³","drift speed","wire''s resistance","speed of the field"],"answer":1}', '[]', '$v_d \propto I$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fcde37df73cdab', 'les_07d05413f12ebb', 4, 'review', 'multiple_choice', 3, 'A wire narrows to half its cross-section. The same current there has…', '{"choices":["half the drift speed","twice the drift speed","the same drift speed","zero drift"],"answer":1}', '[]', '$v_d = \frac{I}{nqA}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_07d05413f12ebb', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_07d05413f12ebb', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: em-dielectrics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0bac7d104f8dba', 'em-dielectrics', 'Dielectrics', 'Explain how dielectric polarization reduces the field and raises capacitance by κ, contrast battery-connected and isolated capacitors, and handle partly filled capacitors.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bacb6863bf3174', 'les_0bac7d104f8dba', 1, 'Explain polarization and induced surface charge in a dielectric.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e5b8b9d8c428df', 'les_0bac7d104f8dba', 2, 'Use C = κC₀ and E = E₀/κ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc66bc78ef67be', 'les_0bac7d104f8dba', 3, 'Predict changes in Q, V, E and U with and without a battery connected.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bacb6863bf3174', 'les_0bac7d104f8dba', 'learn', 1, 'definition', '{"term":"Polarization","body":"In an insulator, molecules stretch or rotate so their charges line up slightly with the field. This leaves induced surface charge that partly cancels the applied field: $E = \\frac{E_0}{\\kappa}$, where $\\kappa$ is the dielectric constant (glass ≈ 5, water ≈ 80). The capacitance rises: $C = \\kappa C_0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5b8b9d8c428df', 'les_0bac7d104f8dba', 'learn', 2, 'definition', '{"term":"Two cases","body":"Connected to a battery, V is fixed, so Q, C and U all rise by $\\kappa$. Isolated, Q is fixed, so V and U fall by $\\kappa$ (the dielectric is pulled in)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc66bc78ef67be', 'les_0bac7d104f8dba', 'learn', 3, 'worked_example', '{"title":"Half the gap of a parallel-plate capacitor (C₀ = 10 pF) is filled with κ = 4, slab parallel to the plates","steps":[{"latex":"C_1 = 2\\kappa C_0 = 80\\ \\text{pF}","explanation":"Treat it as two capacitors in series, each with half the gap: the filled half."},{"latex":"C_2 = 2C_0 = 20\\ \\text{pF}","explanation":"The air half."},{"latex":"C = \\left(\\tfrac{1}{80} + \\tfrac{1}{20}\\right)^{-1} = 16\\ \\text{pF}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0614cc7a19dad0', 'les_0bac7d104f8dba', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Nearly every real capacitor uses a dielectric (ceramic, plastic film or oxide) to pack more capacitance in less space; dielectrics also raise the breakdown voltage."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bacb6863bf3174', 'les_0bac7d104f8dba', 1, 'practice', 'numeric', 2, 'A 50 pF capacitor connected to 12 V has a κ = 3 dielectric inserted. Find the new charge, in pC.', '{"answer":1800,"unit":"pC"}', '[]', '$3(50)(12)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5b8b9d8c428df', 'les_0bac7d104f8dba', 2, 'practice', 'numeric', 3, 'A 20 pF capacitor is filled side by side, half with κ = 5 and half with air (each over half the plate area). Find C.', '{"answer":60,"unit":"pF"}', '[]', 'Parallel: $\frac12(20)(5) + \frac12(20)(1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc66bc78ef67be', 'les_0bac7d104f8dba', 3, 'practice', 'multiple_choice', 2, 'An isolated charged capacitor gets a dielectric. Its voltage…', '{"choices":["increases","decreases by κ","stays the same","becomes zero"],"answer":1}', '[]', 'Q fixed, C up by κ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0614cc7a19dad0', 'les_0bac7d104f8dba', 4, 'review', 'multiple_choice', 3, 'Why is a dielectric slab pulled into a charged isolated capacitor?', '{"choices":["magnetism","the system''s energy decreases as it enters","gravity","it isn''t"],"answer":1}', '[]', '$U = \frac{Q^2}{2C}$ falls as C rises.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0bac7d104f8dba', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0bac7d104f8dba', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: em-electric-flux
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e91a4e596b270c', 'em-electric-flux', 'Electric flux', 'Define electric flux as ∫E·dA, compute it for flat and closed surfaces, and see why net flux through a closed surface depends only on enclosed charge.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_110781cc1a7a53', 'les_e91a4e596b270c', 1, 'Compute Φ = E·A = EA cos θ for a uniform field through a flat surface.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2c5b17f007eb79', 'les_e91a4e596b270c', 2, 'Use Φ = ∫E·dA for non-uniform fields and closed surfaces (outward normals).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6576ebb63b4914', 'les_e91a4e596b270c', 3, 'Explain why a closed surface with no charge inside has zero net flux.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_110781cc1a7a53', 'les_e91a4e596b270c', 'learn', 1, 'definition', '{"term":"Flux","body":"Electric flux measures how much field passes through a surface: $\\Phi_E = \\int\\vec E\\cdot d\\vec A$, where $d\\vec A$ is perpendicular to the surface. For a uniform field and a flat surface, $\\Phi = EA\\cos\\theta$. For a closed surface, $d\\vec A$ points outward: field leaving counts positive, field entering negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2c5b17f007eb79', 'les_e91a4e596b270c', 'learn', 2, 'worked_example', '{"title":"A 500 N/C uniform field through a 0.02 m² square tilted so its normal is 30° from the field","steps":[{"latex":"\\Phi = (500)(0.02)\\cos 30° \\approx 8.66\\ \\text{N·m}^2/\\text{C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6576ebb63b4914', 'les_e91a4e596b270c', 'learn', 3, 'worked_example', '{"title":"A cube in a uniform field along +x","steps":[{"latex":"\\Phi_{right} = +EA,\\ \\Phi_{left} = -EA","explanation":"The other four faces are parallel to E."},{"latex":"\\Phi_{net} = 0","explanation":"No charge inside: every field line that enters also leaves."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b29e167aeeac6c', 'les_e91a4e596b270c', 'learn', 4, 'callout', '{"tone":"note","title":"Coming next","body":"For any closed surface, the net flux equals $\\frac{Q_{enc}}{\\varepsilon_0}$: a 3 nC charge anywhere inside gives about 339 N·m²/C, whatever the surface''s shape. That''s Gauss''s law."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c297ab52132f55', 'les_e91a4e596b270c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Flux is the same idea as water flow through a net, and it underlies sensors that measure field strength across a known area."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_110781cc1a7a53', 'les_e91a4e596b270c', 1, 'practice', 'numeric', 2, 'A 2 nC charge sits inside a closed balloon. Find the net flux through the balloon, to the nearest unit.', '{"answer":226,"tolerance":1,"unit":"N·m²/C"}', '[]', '$\frac{2\times10^{-9}}{8.854\times10^{-12}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2c5b17f007eb79', 'les_e91a4e596b270c', 2, 'practice', 'numeric', 2, 'A 0.1 m² sheet sits in a 400 N/C uniform field with its normal at 60° to the field. Find the flux.', '{"answer":20,"unit":"N·m²/C"}', '[]', '$400(0.1)(0.5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6576ebb63b4914', 'les_e91a4e596b270c', 3, 'practice', 'multiple_choice', 2, 'A 5 nC charge is at the center of a cube. The flux through one face is…', '{"choices":["Q/ε₀","Q/(6ε₀)","zero","6Q/ε₀"],"answer":1}', '[]', 'By symmetry, each of six faces carries a sixth.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b29e167aeeac6c', 'les_e91a4e596b270c', 4, 'review', 'multiple_choice', 3, 'A closed surface has zero net flux. Which must be true?', '{"choices":["E = 0 everywhere on it","the net enclosed charge is zero","no charges are nearby","the surface is a sphere"],"answer":1}', '[]', 'Outside charges can make field lines pass through, but they cancel.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e91a4e596b270c', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e91a4e596b270c', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 1);

-- Lesson: em-energy-conservation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6318c8a7b100ec', 'em-energy-conservation', 'Conservation of electric energy', 'Use K + qV = constant for charged particles moving through fields of point charges and distributions, including closest-approach problems.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_33b2f91ddd2138', 'les_6318c8a7b100ec', 1, 'Apply K_i + qV_i = K_f + qV_f with potentials from point charges or distributions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3739aff8ad23d0', 'les_6318c8a7b100ec', 2, 'Find closest-approach distances in head-on encounters.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ab250ca044a45', 'les_6318c8a7b100ec', 3, 'Find escape speeds from charged objects.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_33b2f91ddd2138', 'les_6318c8a7b100ec', 'learn', 1, 'definition', '{"term":"Energy conservation","body":"For a charge moving only under electric forces, $\\frac12mv_i^2 + qV_i = \\frac12mv_f^2 + qV_f$. The potential can come from any source, so no path integrals are needed once V is known."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3739aff8ad23d0', 'les_6318c8a7b100ec', 'learn', 2, 'worked_example', '{"title":"An alpha particle (q = 3.2 × 10⁻¹⁹ C) with 5 MeV heads straight at a gold nucleus (q = 79e)","steps":[{"latex":"K_i = \\tfrac{kq_\\alpha Q}{r_{min}}","explanation":"All kinetic energy becomes potential energy at closest approach."},{"latex":"r_{min} = \\tfrac{kq_\\alpha(79e)}{K}","explanation":"K = 5 MeV = 8.0 × 10⁻¹³ J; q_α = 3.2 × 10⁻¹⁹ C; 79e = 1.26 × 10⁻¹⁷ C."},{"latex":"r_{min} = \\tfrac{(8.99\\times10^9)(4.03\\times10^{-36})}{8.0\\times10^{-13}}","explanation":"The two charges multiply to 4.03 × 10⁻³⁶ C²."},{"latex":"r_{min} \\approx 4.5\\times10^{-14}\\ \\text{m}","explanation":"Rutherford used this to bound the nucleus''s size."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ab250ca044a45', 'les_6318c8a7b100ec', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rutherford scattering, ion implantation in chip making and particle accelerators are all energy-conservation problems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_33b2f91ddd2138', 'les_6318c8a7b100ec', 1, 'practice', 'numeric', 3, 'A proton is released from rest 1 cm from a fixed +2 nC point charge. Find its speed far away, in units of $10^5$ m/s, to two decimal places.', '{"answer":5.88,"tolerance":0.02}', '[]', '$\frac12mv^2 = \frac{kqQ}{r}$: $v = \sqrt{\frac{2(8.99\times10^9)(1.6\times10^{-19})(2\times10^{-9})}{1.67\times10^{-27}(0.01)}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3739aff8ad23d0', 'les_6318c8a7b100ec', 2, 'practice', 'numeric', 2, 'An electron is released from rest at a point where V = 90 V and moves to the center of a ring where V = 150 V. Find its kinetic energy there, in eV.', '{"answer":60,"unit":"eV"}', '[]', '$\Delta K = -q\Delta V = -(-e)(60\ \text{V}) = 60$ eV; electrons speed up moving toward higher potential.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ab250ca044a45', 'les_6318c8a7b100ec', 3, 'practice', 'multiple_choice', 2, 'Two protons are released from rest near each other. As they separate, their total kinetic energy…', '{"choices":["decreases","increases toward their initial potential energy","stays zero","becomes infinite"],"answer":1}', '[]', '$U \to K$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b2a8a61518b037', 'les_6318c8a7b100ec', 4, 'review', 'multiple_choice', 3, 'Doubling an alpha particle''s kinetic energy changes its closest approach to a nucleus by a factor of…', '{"choices":["2","½","4","¼"],"answer":1}', '[]', '$r_{min} \propto \frac1K$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6318c8a7b100ec', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6318c8a7b100ec', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: em-faraday-lenz
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b52d08260ec29c', 'em-faraday-lenz', 'Faraday''s law and Lenz''s law', 'Compute induced emf from ε = −N dΦ/dt for changing fields, areas and angles, including AC generators, and find current directions with Lenz''s law.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9be8dd2ff08207', 'les_b52d08260ec29c', 1, 'Apply ε = −N dΦ_B/dt to fields that change with time.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d9a3e3abce59fe', 'les_b52d08260ec29c', 2, 'Derive the generator emf ε = NBAω sin ωt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b57c5827ae88ee', 'les_b52d08260ec29c', 3, 'Use Lenz''s law to find the direction of induced current.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9be8dd2ff08207', 'les_b52d08260ec29c', 'learn', 1, 'definition', '{"term":"Faraday''s law","body":"$\\varepsilon = -N\\frac{d\\Phi_B}{dt}$. The minus sign is Lenz''s law: the induced current makes a field that opposes the change in flux. Flux can change through B, the area or the angle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9a3e3abce59fe', 'les_b52d08260ec29c', 'learn', 2, 'worked_example', '{"title":"A 50-turn loop of area 0.05 m² in a perpendicular field B(t) = 0.2t² T","steps":[{"latex":"\\varepsilon = -N A\\tfrac{dB}{dt} = -50(0.05)(0.4t)","explanation":""},{"latex":"|\\varepsilon(2)| = 2\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b57c5827ae88ee', 'les_b52d08260ec29c', 'learn', 3, 'worked_example', '{"title":"A generator: N = 100 turns, A = 0.02 m², B = 0.5 T, spinning at 60 Hz","steps":[{"latex":"\\Phi = BA\\cos\\omega t \\Rightarrow \\varepsilon = NBA\\omega\\sin\\omega t","explanation":""},{"latex":"\\varepsilon_{max} = 100(0.5)(0.02)(120\\pi) \\approx 377\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c3320c32d0a0e', 'les_b52d08260ec29c', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every power station, bike dynamo, induction charger and electric guitar pickup runs on Faraday''s law."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9be8dd2ff08207', 'les_b52d08260ec29c', 1, 'practice', 'numeric', 2, 'A loop of area 0.1 m² sits in B(t) = 0.5e^{−2t} T. Find |ε| at t = 0.', '{"answer":0.1,"unit":"V"}', '[]', '$A\left|\frac{dB}{dt}\right| = 0.1(1.0)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9a3e3abce59fe', 'les_b52d08260ec29c', 2, 'practice', 'numeric', 2, 'Find the peak emf of a 200-turn, 0.01 m² coil spinning at 50 rad/s in 0.3 T.', '{"answer":30,"unit":"V"}', '[]', '$NBA\omega$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b57c5827ae88ee', 'les_b52d08260ec29c', 3, 'practice', 'multiple_choice', 2, 'The flux through a loop increases out of the page. The induced current flows…', '{"choices":["clockwise (seen from the front)","counterclockwise","not at all","alternately"],"answer":0}', '[]', 'Its field must point into the page: clockwise.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c3320c32d0a0e', 'les_b52d08260ec29c', 4, 'review', 'multiple_choice', 3, 'A generator''s emf is zero at the moment its coil''s plane is…', '{"choices":["parallel to B","perpendicular to B (max flux)","at 45°","never zero"],"answer":1}', '[]', '$\frac{d\Phi}{dt} = 0$ when the flux peaks.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b52d08260ec29c', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b52d08260ec29c', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 1);

-- Lesson: em-gauss-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_562639fcbeade6', 'em-gauss-law', 'Gauss''s law', 'Apply Gauss''s law with spherical, cylindrical and planar symmetry to find fields of spheres, lines and sheets, inside and outside.', 45, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba53144fbf4ce1', 'les_562639fcbeade6', 1, 'State Gauss''s law, ∮E·dA = Q_enc/ε₀.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42942bf63676b5', 'les_562639fcbeade6', 2, 'Choose Gaussian surfaces that match the symmetry so E can be pulled out of the integral.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7d0da843719fab', 'les_562639fcbeade6', 3, 'Find E inside and outside uniformly charged spheres and cylinders, and near infinite planes, σ/(2ε₀).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba53144fbf4ce1', 'les_562639fcbeade6', 'learn', 1, 'definition', '{"term":"Gauss''s law","body":"$\\oint\\vec E\\cdot d\\vec A = \\frac{Q_{enc}}{\\varepsilon_0}$ for any closed surface. It''s always true, but it''s useful for finding E only when symmetry makes $E$ constant and perpendicular over the surface, so the integral becomes $E\\times\\text{area}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42942bf63676b5', 'les_562639fcbeade6', 'learn', 2, 'worked_example', '{"title":"A uniformly charged insulating sphere (Q = 6 nC, R = 10 cm)","steps":[{"latex":"r > R:\\ E(4\\pi r^2) = \\tfrac{Q}{\\varepsilon_0}","explanation":""},{"latex":"E = \\tfrac{kQ}{r^2}","explanation":"Like a point charge."},{"latex":"r < R:\\ Q_{enc} = Q\\tfrac{r^3}{R^3} \\Rightarrow E = \\tfrac{kQr}{R^3}","explanation":""},{"latex":"E(5\\ \\text{cm}) \\approx 2700\\ \\text{N/C},\\ E(20\\ \\text{cm}) \\approx 1350\\ \\text{N/C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d0da843719fab', 'les_562639fcbeade6', 'learn', 3, 'worked_example', '{"title":"An infinite sheet with surface charge σ = 2 μC/m²","steps":[{"latex":"E(2A) = \\tfrac{\\sigma A}{\\varepsilon_0}","explanation":""},{"latex":"E = \\tfrac{\\sigma}{2\\varepsilon_0}","explanation":"A pillbox through the sheet; flux leaves both caps."},{"latex":"E \\approx 1.13\\times10^5\\ \\text{N/C}","explanation":"The same at any distance."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_478b60f5df25c7', 'les_562639fcbeade6', 'experiment', 4, 'activity', '{"activity":"gauss-field","title":"Move the Gaussian surface","params":{"distribution":"solid","charge":6,"radius":0.1,"gaussian":0.05}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b02b86ea70fada', 'les_562639fcbeade6', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Compare the solid sphere and the conductor with the same charge: outside they match exactly; inside, the conductor''s field is zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edee29de7b4398', 'les_562639fcbeade6', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gauss''s law explains why a car shields you from lightning and why charge sits on a conductor''s surface; it''s one of Maxwell''s four equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba53144fbf4ce1', 'les_562639fcbeade6', 1, 'practice', 'numeric', 2, 'Find E 30 cm from the center of the 6 nC sphere in the example, to the nearest N/C.', '{"answer":599,"tolerance":1,"unit":"N/C"}', '[]', '$\frac{8.99\times10^9(6\times10^{-9})}{0.09}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42942bf63676b5', 'les_562639fcbeade6', 2, 'practice', 'numeric', 3, 'An infinite cylinder of radius 2 cm holds 4 nC per meter, uniformly through its volume. Find E 1 cm from the axis, to the nearest N/C.', '{"answer":1798,"tolerance":2,"unit":"N/C"}', '[]', '$\frac{\lambda r}{2\pi\varepsilon_0R^2} = \frac{2k\lambda r}{R^2} = \frac{2(8.99\times10^9)(4\times10^{-9})(0.01)}{0.0004}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d0da843719fab', 'les_562639fcbeade6', 3, 'practice', 'multiple_choice', 2, 'Two parallel infinite sheets carry +σ and −σ. The field between them is…', '{"choices":["zero","σ/(2ε₀)","σ/ε₀","2σ/ε₀"],"answer":2}', '[]', 'The two fields add between the sheets and cancel outside.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_478b60f5df25c7', 'les_562639fcbeade6', 4, 'review', 'multiple_choice', 3, 'Gauss''s law can''t easily give the field of a finite charged cube because…', '{"choices":["it''s false for cubes","E isn''t constant over any simple closed surface","cubes have no flux","the charge is too big"],"answer":1}', '[]', 'The law holds, but without symmetry E can''t be pulled out of the integral.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_562639fcbeade6', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_562639fcbeade6', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 1);

-- Lesson: em-induced-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5ea98a982edf2e', 'em-induced-forces', 'Induced currents and magnetic forces', 'Solve the sliding-rod problem with calculus: induced emf, current, magnetic drag force, exponential slowdown and terminal velocity, and connect it to eddy-current braking.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_702bece5e3a89f', 'les_5ea98a982edf2e', 1, 'Find the drag force on a moving conductor, F = B²L²v/R.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eaf3cb5a6d0ff7', 'les_5ea98a982edf2e', 2, 'Solve m dv/dt = −B²L²v/R for v(t).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ee20b65073ca5c', 'les_5ea98a982edf2e', 3, 'Find terminal velocity when a constant force drives the rod.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_702bece5e3a89f', 'les_5ea98a982edf2e', 'learn', 1, 'definition', '{"term":"Magnetic drag","body":"A rod of length L sliding at v on rails through field B has $\\varepsilon = BLv$, current $I = \\frac{BLv}{R}$, and feels $F = BIL = \\frac{B^2L^2v}{R}$ opposing the motion: a drag force proportional to v."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eaf3cb5a6d0ff7', 'les_5ea98a982edf2e', 'learn', 2, 'worked_example', '{"title":"A 0.1 kg rod (L = 0.5 m) coasts at 4 m/s through 0.8 T on rails joined by a 2 Ω resistor","steps":[{"latex":"m\\tfrac{dv}{dt} = -\\tfrac{B^2L^2}{R}v","explanation":""},{"latex":"v = v_0e^{-t/\\tau}","explanation":""},{"latex":"\\tau = \\tfrac{mR}{B^2L^2} = \\tfrac{0.1(2)}{0.64(0.25)} = 1.25\\ \\text{s}","explanation":""},{"latex":"v(1.25) \\approx 4e^{-1} \\approx 1.47\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ee20b65073ca5c', 'les_5ea98a982edf2e', 'learn', 3, 'definition', '{"term":"Terminal velocity","body":"If a constant force F pulls the rod (gravity on a vertical rail, say), it speeds up until $F = \\frac{B^2L^2v}{R}$: $v_T = \\frac{FR}{B^2L^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c8c59ba845fc79', 'les_5ea98a982edf2e', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Eddy-current brakes on trains and roller coasters, induction cooktops, and the damping of balance needles all use induced currents."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_702bece5e3a89f', 'les_5ea98a982edf2e', 1, 'practice', 'numeric', 2, 'In the example, a constant 0.4 N force pulls the rod. Find its terminal speed.', '{"answer":5,"unit":"m/s"}', '[]', '$\frac{0.4(2)}{0.16}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eaf3cb5a6d0ff7', 'les_5ea98a982edf2e', 2, 'practice', 'numeric', 3, 'How far does the coasting rod travel before stopping?', '{"answer":5,"unit":"m"}', '[]', '$\int_0^\infty v_0e^{-t/\tau}\,dt = v_0\tau = 4(1.25)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ee20b65073ca5c', 'les_5ea98a982edf2e', 3, 'practice', 'multiple_choice', 2, 'Where does the rod''s kinetic energy go as it slows?', '{"choices":["into the magnet","heat in the resistor","it''s destroyed","back into the rod"],"answer":1}', '[]', '$\int I^2R\,dt = \frac12mv_0^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c8c59ba845fc79', 'les_5ea98a982edf2e', 4, 'review', 'multiple_choice', 3, 'Doubling B makes the magnetic braking force (same v)…', '{"choices":["2× larger","4× larger","½","the same"],"answer":1}', '[]', '$F \propto B^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5ea98a982edf2e', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5ea98a982edf2e', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5ea98a982edf2e', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 2);

-- Lesson: em-inductance
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ebe88d33a44aa2', 'em-inductance', 'Inductance', 'Define self-inductance, derive the inductance of a solenoid, use ε = −L dI/dt, and find energy stored in magnetic fields.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_89114735e12da2', 'les_ebe88d33a44aa2', 1, 'Define L = NΦ_B/I and use ε_L = −L dI/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9fb2560a4fda1a', 'les_ebe88d33a44aa2', 2, 'Derive L = μ₀N²A/ℓ for a solenoid.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a058e2824987b', 'les_ebe88d33a44aa2', 3, 'Compute stored energy ½LI² and magnetic energy density B²/(2μ₀).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89114735e12da2', 'les_ebe88d33a44aa2', 'learn', 1, 'definition', '{"term":"Self-inductance","body":"A coil''s own current makes flux through it: $N\\Phi_B = LI$, with inductance $L$ in henries. Changing the current induces a back emf $\\varepsilon_L = -L\\frac{dI}{dt}$ that resists the change, giving circuits a kind of electrical inertia."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9fb2560a4fda1a', 'les_ebe88d33a44aa2', 'learn', 2, 'worked_example', '{"title":"A solenoid: 500 turns, ℓ = 0.25 m, A = 1 × 10⁻³ m²","steps":[{"latex":"B = \\mu_0\\tfrac N\\ell I,\\ N\\Phi = NBA = \\tfrac{\\mu_0N^2A}{\\ell}I","explanation":""},{"latex":"L = \\tfrac{(4\\pi\\times10^{-7})(500^2)(10^{-3})}{0.25} \\approx 1.26\\ \\text{mH}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a058e2824987b', 'les_ebe88d33a44aa2', 'learn', 3, 'definition', '{"term":"Energy","body":"Building up the current takes work $\\int LI\\,dI = \\frac12LI^2$, stored in the field with density $u_B = \\frac{B^2}{2\\mu_0}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e97771ecccc9c2', 'les_ebe88d33a44aa2', 'learn', 4, 'worked_example', '{"title":"0.2 H carrying 3 A","steps":[{"latex":"U = \\tfrac12(0.2)(3^2) = 0.9\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80e5acc8e3b590', 'les_ebe88d33a44aa2', 'experiment', 5, 'activity', '{"activity":"inductor-circuit","title":"Current can''t change instantly","params":{"mode":"rise","emf":12,"resistance":4,"inductance":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd107b2e8079eb', 'les_ebe88d33a44aa2', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Switch-mode power supplies store energy in inductors; the spark when unplugging a motor is the back emf from a sudden dI/dt."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89114735e12da2', 'les_ebe88d33a44aa2', 1, 'practice', 'numeric', 2, 'Current in a 0.05 H inductor rises at 200 A/s. Find the back emf''s size.', '{"answer":10,"unit":"V"}', '[]', '$L\frac{dI}{dt}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9fb2560a4fda1a', 'les_ebe88d33a44aa2', 2, 'practice', 'numeric', 2, 'Find the magnetic energy density in a 1 T field, in units of $10^5$ J/m³, to two decimal places.', '{"answer":3.98,"tolerance":0.01}', '[]', '$\frac{1}{2(4\pi\times10^{-7})}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a058e2824987b', 'les_ebe88d33a44aa2', 3, 'practice', 'multiple_choice', 2, 'Doubling the number of turns (same length and area) multiplies L by…', '{"choices":["2","4","½","1"],"answer":1}', '[]', '$L \propto N^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e97771ecccc9c2', 'les_ebe88d33a44aa2', 4, 'review', 'multiple_choice', 3, 'An inductor in a DC circuit, long after switching on, acts like…', '{"choices":["an open switch","a plain wire","a capacitor","a battery"],"answer":1}', '[]', 'dI/dt = 0, so no back emf.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ebe88d33a44aa2', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ebe88d33a44aa2', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 1);

-- Lesson: em-lc-circuits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7ed843036382f4', 'em-lc-circuits', 'Circuits with capacitors and inductors (LC circuits)', 'Derive the LC differential equation, show it''s simple harmonic motion with ω = 1/√(LC), and track energy sloshing between the capacitor and inductor.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_832b740dbe39a0', 'les_7ed843036382f4', 1, 'Derive d²q/dt² = −q/(LC) from the loop rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_04a95d19bc79a9', 'les_7ed843036382f4', 2, 'Use q = Q₀cos ωt and I = −Q₀ω sin ωt with ω = 1/√(LC).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_92b193591e624f', 'les_7ed843036382f4', 3, 'Track energy between ½q²/C and ½LI², and find the maximum current.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_832b740dbe39a0', 'les_7ed843036382f4', 'learn', 1, 'definition', '{"term":"The equation","body":"Around the loop, $\\frac qC + L\\frac{dI}{dt} = 0$ with $I = \\frac{dq}{dt}$: $\\frac{d^2q}{dt^2} = -\\frac{1}{LC}q$. That''s SHM: charge plays position, inductance plays mass and $\\frac1C$ plays the spring constant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04a95d19bc79a9', 'les_7ed843036382f4', 'learn', 2, 'worked_example', '{"title":"L = 10 mH, C = 1 μF, capacitor starts with 5 μC","steps":[{"latex":"\\omega = \\tfrac{1}{\\sqrt{(0.01)(10^{-6})}} = 10^4\\ \\text{rad/s}","explanation":""},{"latex":"f = \\tfrac{\\omega}{2\\pi} \\approx 1590\\ \\text{Hz}","explanation":""},{"latex":"I_{max} = Q_0\\omega = (5\\times10^{-6})(10^4) = 0.05\\ \\text{A}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92b193591e624f', 'les_7ed843036382f4', 'learn', 3, 'definition', '{"term":"Energy","body":"$\\frac{q^2}{2C} + \\frac12LI^2 = \\frac{Q_0^2}{2C}$ at all times, like $U + K$ for a spring. Real circuits have some resistance, so the oscillation decays, the way a damped spring does."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34c657cdddd3c5', 'les_7ed843036382f4', 'experiment', 4, 'activity', '{"activity":"inductor-circuit","title":"Energy sloshing in an LC circuit","params":{"mode":"lc","emf":12,"inductance":0.5,"capacitance":100}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a1e6563d2099b', 'les_7ed843036382f4', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every radio tuner is an LC circuit adjusted to resonate at one station''s frequency; metal detectors and wireless chargers use them too."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_832b740dbe39a0', 'les_7ed843036382f4', 1, 'practice', 'numeric', 2, 'Find f for L = 2 mH and C = 50 nF, in kHz, to one decimal place.', '{"answer":15.9,"tolerance":0.1,"unit":"kHz"}', '[]', '$\frac{1}{2\pi\sqrt{10^{-10}}} \approx 15{,}915$ Hz.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04a95d19bc79a9', 'les_7ed843036382f4', 2, 'practice', 'numeric', 3, 'An LC circuit (L = 0.5 H, C = 100 μF) starts with its capacitor at 12 V. Find the maximum current, to three decimal places.', '{"answer":0.17,"tolerance":0.001,"unit":"A"}', '[]', '$I_{max} = Q_0\omega = (1.2\times10^{-3})(141.4) \approx 0.170$ A.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92b193591e624f', 'les_7ed843036382f4', 3, 'practice', 'multiple_choice', 2, 'When the capacitor''s charge is zero, the current is…', '{"choices":["zero","maximum","half of maximum","reversing"],"answer":1}', '[]', 'All the energy is in the inductor.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34c657cdddd3c5', 'les_7ed843036382f4', 4, 'review', 'multiple_choice', 3, 'In the mechanical analogy, inductance corresponds to…', '{"choices":["spring constant","mass","position","friction"],"answer":1}', '[]', 'It resists changes in current, as mass resists changes in velocity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7ed843036382f4', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7ed843036382f4', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 1);

-- Lesson: em-lr-circuits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_261e697fbad815', 'em-lr-circuits', 'Circuits with resistors and inductors (LR circuits)', 'Solve the differential equations for current rising and decaying in LR circuits, with time constant τ = L/R, and analyze circuits just after and long after switching.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a833d66c72108', 'les_261e697fbad815', 1, 'Write ε − IR − L dI/dt = 0 and solve: I = (ε/R)(1 − e^(−t/τ)), τ = L/R.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7d5b1fb2be7f96', 'les_261e697fbad815', 2, 'Solve the decay I = I₀e^(−t/τ).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c1ca83cff52aaf', 'les_261e697fbad815', 3, 'Use the rules: inductors keep their current at the instant of switching, and act as wires at steady state.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a833d66c72108', 'les_261e697fbad815', 'learn', 1, 'definition', '{"term":"Rising current","body":"Around the loop, $\\varepsilon - IR - L\\frac{dI}{dt} = 0$. Separating variables gives $I = \\frac\\varepsilon R(1 - e^{-t/\\tau})$ with $\\tau = \\frac LR$. The inductor''s voltage, $\\varepsilon e^{-t/\\tau}$, starts at the full emf and fades."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d5b1fb2be7f96', 'les_261e697fbad815', 'learn', 2, 'worked_example', '{"title":"12 V, 4 Ω, 0.5 H","steps":[{"latex":"I_{final} = \\tfrac{12}{4} = 3\\ \\text{A},\\ \\tau = \\tfrac{0.5}{4} = 0.125\\ \\text{s}","explanation":""},{"latex":"I(\\tau) = 3(1 - e^{-1}) \\approx 1.90\\ \\text{A}","explanation":""},{"latex":"t_{1/2} = \\tau\\ln 2 \\approx 0.087\\ \\text{s}","explanation":"After the battery is removed, the current halves in this time."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1ca83cff52aaf', 'les_261e697fbad815', 'learn', 3, 'definition', '{"term":"Switching rules","body":"At the instant of switching, an inductor''s current can''t jump, since that would need infinite emf. Long afterward, it acts like a wire. That''s the mirror image of a capacitor, whose voltage can''t jump."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93f570639e8b22', 'les_261e697fbad815', 'experiment', 4, 'activity', '{"activity":"inductor-circuit","title":"LR rise and decay","params":{"mode":"rise","emf":12,"resistance":4,"inductance":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9d35c62a11e80a', 'les_261e697fbad815', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Relay coils, motor windings and ignition coils are LR circuits; flyback diodes give the inductor''s current somewhere to go when switched off."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a833d66c72108', 'les_261e697fbad815', 1, 'practice', 'numeric', 2, 'Find τ for a 2 H inductor with a 50 Ω resistor, in ms.', '{"answer":40,"unit":"ms"}', '[]', '$\frac{2}{50} = 0.04$ s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d5b1fb2be7f96', 'les_261e697fbad815', 2, 'practice', 'numeric', 3, 'In the example, find the energy stored in the inductor at t = τ, to two decimal places.', '{"answer":0.9,"tolerance":0.01,"unit":"J"}', '[]', '$\frac12(0.5)(1.896^2) \approx 0.90$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c1ca83cff52aaf', 'les_261e697fbad815', 3, 'practice', 'multiple_choice', 2, 'Just after the switch closes in an LR circuit, the current is…', '{"choices":["ε/R","zero","maximum","ε/L"],"answer":1}', '[]', 'It can''t jump from zero.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93f570639e8b22', 'les_261e697fbad815', 4, 'review', 'multiple_choice', 3, 'Doubling R in an LR circuit makes the current reach its (new) final value…', '{"choices":["faster","slower","at the same rate","never"],"answer":0}', '[]', '$\tau = \frac LR$ halves.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_261e697fbad815', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_261e697fbad815', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 1);

-- Lesson: em-magnetic-flux-calculus
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bd5fbd9bb32d36', 'em-magnetic-flux-calculus', 'Magnetic flux', 'Compute magnetic flux as ∫B·dA, including through a rectangle near a long wire where B varies, and explain why net flux through any closed surface is zero.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1b31269a607b62', 'les_bd5fbd9bb32d36', 1, 'Compute Φ_B = ∫B·dA for uniform and non-uniform fields.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_edfdc396bc582e', 'les_bd5fbd9bb32d36', 2, 'Find the flux through a rectangular loop beside a long straight wire.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ed14736805720', 'les_bd5fbd9bb32d36', 3, 'State Gauss''s law for magnetism: ∮B·dA = 0.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b31269a607b62', 'les_bd5fbd9bb32d36', 'learn', 1, 'definition', '{"term":"Flux","body":"$\\Phi_B = \\int\\vec B\\cdot d\\vec A$ (webers). For a uniform field through a flat loop, $BA\\cos\\theta$. Magnetic field lines always close on themselves (there are no magnetic monopoles), so through any closed surface $\\oint\\vec B\\cdot d\\vec A = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_edfdc396bc582e', 'les_bd5fbd9bb32d36', 'learn', 2, 'worked_example', '{"title":"A rectangular loop, b = 0.2 m along a long wire carrying 10 A, spanning 0.05 m to 0.15 m from it","steps":[{"latex":"d\\Phi = \\tfrac{\\mu_0I}{2\\pi r}\\,b\\,dr","explanation":"Strips parallel to the wire, where B is constant."},{"latex":"\\Phi = \\tfrac{\\mu_0Ib}{2\\pi}\\ln\\tfrac{0.15}{0.05}","explanation":""},{"latex":"\\Phi = (2\\times10^{-7})(10)(0.2)\\ln 3 \\approx 4.39\\times10^{-7}\\ \\text{Wb}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ed14736805720', 'les_bd5fbd9bb32d36', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Transformer cores are shaped to guide flux through both coils; current clamps measure the flux around a wire without touching it."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b31269a607b62', 'les_bd5fbd9bb32d36', 1, 'practice', 'numeric', 2, 'B = 0.3x T (perpendicular to a square loop from x = 0 to 2 m, height 1 m). Find the flux.', '{"answer":0.6,"unit":"Wb"}', '[]', '$\int_0^2 0.3x\,dx$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_edfdc396bc582e', 'les_bd5fbd9bb32d36', 2, 'practice', 'numeric', 3, 'Repeat the wire example with the loop from 0.1 m to 0.3 m. Find Φ, in units of $10^{-7}$ Wb, to two decimal places.', '{"answer":4.39,"tolerance":0.01}', '[]', 'The ratio is still 3: same flux.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ed14736805720', 'les_bd5fbd9bb32d36', 3, 'practice', 'multiple_choice', 2, 'The net magnetic flux through a closed surface around a bar magnet is…', '{"choices":["positive","negative","zero","depends on the magnet"],"answer":2}', '[]', 'No monopoles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c46ad698e32f22', 'les_bd5fbd9bb32d36', 4, 'review', 'multiple_choice', 3, 'Doubling the loop''s distance from the wire (same ratio of far to near edge) changes the flux by…', '{"choices":["half","nothing","a quarter","double"],"answer":1}', '[]', 'It depends only on the ratio of distances.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bd5fbd9bb32d36', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bd5fbd9bb32d36', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bd5fbd9bb32d36', (SELECT id FROM formulas WHERE slug = 'induction-circuits'), 2);

-- Lesson: em-magnetic-force-vectors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4ed99fbc971465', 'em-magnetic-force-vectors', 'Magnetic fields and forces on moving charges', 'Compute magnetic forces with the cross product F = qv × B, analyze circular and helical motion, and combine electric and magnetic forces (Lorentz force).', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_43ff8e363d5b33', 'les_4ed99fbc971465', 1, 'Compute F = qv × B with components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_041d597f52f657', 'les_4ed99fbc971465', 2, 'Find the radius, period and pitch of circular and helical motion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f8b4bd6499128', 'les_4ed99fbc971465', 3, 'Use the Lorentz force F = q(E + v × B), and the velocity selector.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43ff8e363d5b33', 'les_4ed99fbc971465', 'learn', 1, 'definition', '{"term":"Cross product","body":"$\\vec F = q\\vec v\\times\\vec B$. With components, $\\vec v\\times\\vec B = (v_yB_z - v_zB_y,\\ v_zB_x - v_xB_z,\\ v_xB_y - v_yB_x)$. The force is perpendicular to $\\vec v$, so it does no work and speed stays constant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_041d597f52f657', 'les_4ed99fbc971465', 'learn', 2, 'worked_example', '{"title":"A proton with v = (2, 0, 1) × 10⁵ m/s in B = (0, 0.5, 0) T","steps":[{"latex":"(v_yB_z - v_zB_y,\\ v_zB_x - v_xB_z,\\ v_xB_y - v_yB_x)","explanation":"Components of v × B."},{"latex":"= (0 - (1)(0.5),\\ 0,\\ (2)(0.5) - 0)\\times10^5","explanation":""},{"latex":"\\vec v\\times\\vec B = (-0.5,\\ 0,\\ 1)\\times10^5\\ \\text{T·m/s}","explanation":""},{"latex":"\\vec F = q(\\vec v\\times\\vec B)","explanation":"Multiply by q = 1.6 × 10⁻¹⁹ C."},{"latex":"\\vec F = (-0.8,\\ 0,\\ 1.6)\\times10^{-14}\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f8b4bd6499128', 'les_4ed99fbc971465', 'learn', 3, 'definition', '{"term":"Helical motion","body":"The velocity component perpendicular to $\\vec B$ gives a circle of radius $r = \\frac{mv_\\perp}{qB}$ and period $T = \\frac{2\\pi m}{qB}$; the parallel component is unchanged. Together they make a helix with pitch $v_\\parallel T$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de21464c26bc17', 'les_4ed99fbc971465', 'learn', 4, 'definition', '{"term":"Lorentz force","body":"$\\vec F = q(\\vec E + \\vec v\\times\\vec B)$. Crossed fields pass undeflected only the particles with $v = \\frac EB$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8d871ef1e2d232', 'les_4ed99fbc971465', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Auroras (helices along Earth''s field lines), mass spectrometers, cyclotrons and the Hall-effect sensors in phones."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43ff8e363d5b33', 'les_4ed99fbc971465', 1, 'practice', 'numeric', 2, 'An electron moves at v = 3 × 10⁶ m/s î in B = 0.01 T k̂. Find the force''s y-component, in units of $10^{-15}$ N.', '{"answer":4.8,"tolerance":0.01}', '[]', '$q(\vec v\times\vec B) = (-1.6\times10^{-19})(3\times10^6)(0.01)(\hat\imath\times\hat k)$, and $\hat\imath\times\hat k = -\hat\jmath$, so $+4.8\times10^{-15}\,\hat\jmath$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_041d597f52f657', 'les_4ed99fbc971465', 2, 'practice', 'numeric', 3, 'A proton moves at 4 × 10⁵ m/s at 30° to a 0.2 T field. Find the helix pitch, in cm, to one decimal place.', '{"answer":11.4,"tolerance":0.1,"unit":"cm"}', '[]', '$T = \frac{2\pi m}{qB} \approx 3.28\times10^{-7}$ s; $v_\parallel = 4\times10^5\cos 30° \approx 3.46\times10^5$; pitch ≈ 0.114 m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f8b4bd6499128', 'les_4ed99fbc971465', 3, 'practice', 'multiple_choice', 2, 'The magnetic force on a moving charge changes its…', '{"choices":["speed","kinetic energy","direction only","charge"],"answer":2}', '[]', 'Always perpendicular to v.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de21464c26bc17', 'les_4ed99fbc971465', 4, 'review', 'multiple_choice', 3, 'A charge moving parallel to B follows…', '{"choices":["a circle","a straight line","a helix","a parabola"],"answer":1}', '[]', '$\vec v\times\vec B = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4ed99fbc971465', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4ed99fbc971465', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4ed99fbc971465', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 2);

-- Lesson: em-potential-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bf7955ca3ce659', 'em-potential-energy', 'Electric potential energy', 'Derive U = kq₁q₂/r from the work integral, find the energy needed to assemble several charges, and relate the field''s work to ΔU.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_efb7688ea4ded6', 'les_bf7955ca3ce659', 1, 'Derive U(r) = kq₁q₂/r from W = ∫F·dr with U(∞) = 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_611114124ed401', 'les_bf7955ca3ce659', 2, 'Find the potential energy of a configuration by summing over pairs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d0a1c341dd171c', 'les_bf7955ca3ce659', 3, 'Use W_field = −ΔU and energy conservation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_efb7688ea4ded6', 'les_bf7955ca3ce659', 'learn', 1, 'definition', '{"term":"From force to energy","body":"The electric force is conservative, so $\\Delta U = -\\int\\vec F\\cdot d\\vec r$. Bringing $q_2$ from infinity to $r$: $U = -\\int_\\infty^r\\frac{kq_1q_2}{r''^2}\\,dr'' = \\frac{kq_1q_2}{r}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_611114124ed401', 'les_bf7955ca3ce659', 'learn', 2, 'definition', '{"term":"Configurations","body":"The energy to assemble a group of charges from infinity is the sum over every pair: $U = \\sum_{i<j}\\frac{kq_iq_j}{r_{ij}}$. Three charges have three pair terms."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d0a1c341dd171c', 'les_bf7955ca3ce659', 'learn', 3, 'worked_example', '{"title":"Charges of 1, 2 and 3 μC at the corners of an equilateral triangle with 0.1 m sides","steps":[{"latex":"U = \\tfrac{k}{0.1}\\left[(1)(2) + (1)(3) + (2)(3)\\right]\\times10^{-12}","explanation":""},{"latex":"U = \\tfrac{8.99\\times10^9(11\\times10^{-12})}{0.1} \\approx 0.989\\ \\text{J}","explanation":"Positive: work had to be done to push them together."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_db436f42c402b4', 'les_bf7955ca3ce659', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Lattice energies of ionic crystals, the energy released in nuclear fission (the fragments'' Coulomb repulsion) and the binding of atoms are all sums like this."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_efb7688ea4ded6', 'les_bf7955ca3ce659', 1, 'practice', 'numeric', 2, 'Find U for +4 μC and −2 μC charges 0.2 m apart, to three decimal places.', '{"answer":-0.36,"tolerance":0.001,"unit":"J"}', '[]', '$\frac{8.99\times10^9(-8\times10^{-12})}{0.2} \approx -0.360$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_611114124ed401', 'les_bf7955ca3ce659', 2, 'practice', 'numeric', 3, 'Four +1 μC charges sit at the corners of a 0.1 m square. Find the total potential energy, to three decimal places.', '{"answer":0.487,"tolerance":0.002,"unit":"J"}', '[]', 'Four sides at 0.1 m and two diagonals at 0.1414 m: $k\times10^{-12}\left(\frac{4}{0.1} + \frac{2}{0.1414}\right)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d0a1c341dd171c', 'les_bf7955ca3ce659', 3, 'practice', 'multiple_choice', 2, 'When a charge moves where the field does positive work on it, its potential energy…', '{"choices":["increases","decreases","stays the same","becomes zero"],"answer":1}', '[]', '$W = -\Delta U$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_db436f42c402b4', 'les_bf7955ca3ce659', 4, 'review', 'multiple_choice', 3, 'A system of charges has negative total potential energy. This means…', '{"choices":["it can''t exist","work must be added to separate them completely","it flies apart on its own","the charges are all negative"],"answer":1}', '[]', 'It''s bound, like an atom.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bf7955ca3ce659', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bf7955ca3ce659', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: em-potential-field
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_15d2f47e1e3bb2', 'em-potential-field', 'Electric potential and electric field', 'Move between field and potential with V = −∫E·dr and E = −dV/dx (the gradient), and read equipotential maps.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dee29fa861a97b', 'les_15d2f47e1e3bb2', 1, 'Compute ΔV = −∫E·dr along a path.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d9a7839ed95f28', 'les_15d2f47e1e3bb2', 2, 'Find E = −dV/dx (and −∇V in more dimensions).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bc3d36061ae480', 'les_15d2f47e1e3bb2', 3, 'Explain why E is perpendicular to equipotentials and points downhill in V.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dee29fa861a97b', 'les_15d2f47e1e3bb2', 'learn', 1, 'definition', '{"term":"Two directions","body":"$V_B - V_A = -\\int_A^B\\vec E\\cdot d\\vec r$; conversely, $E_x = -\\frac{\\partial V}{\\partial x}$, and in general $\\vec E = -\\nabla V$. The field points in the direction V decreases fastest, perpendicular to equipotentials."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9a7839ed95f28', 'les_15d2f47e1e3bb2', 'learn', 2, 'worked_example', '{"title":"V(x) = 3x² − 2x volts","steps":[{"latex":"E_x = -\\tfrac{dV}{dx} = -(6x - 2)","explanation":""},{"latex":"E_x(1) = -4\\ \\text{V/m}","explanation":"Pointing in −x."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc3d36061ae480', 'les_15d2f47e1e3bb2', 'learn', 3, 'worked_example', '{"title":"Potential difference across a sphere''s field, from r = 0.2 m out to r = 0.4 m (Q = 6 nC)","steps":[{"latex":"\\Delta V = -\\int_{0.2}^{0.4}\\tfrac{kQ}{r^2}\\,dr = kQ\\left(\\tfrac1{0.4} - \\tfrac1{0.2}\\right)","explanation":""},{"latex":"\\Delta V \\approx -135\\ \\text{V}","explanation":"Potential falls moving outward from a positive charge."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dcf47106b47b9e', 'les_15d2f47e1e3bb2', 'experiment', 4, 'activity', '{"activity":"electric-potential","title":"Field lines cross equipotentials at right angles","params":{"q1":3,"q2":-2,"separation":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56a33fceb8c2a2', 'les_15d2f47e1e3bb2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Topographic maps work the same way: contour lines are equipotentials, and water flows downhill perpendicular to them."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dee29fa861a97b', 'les_15d2f47e1e3bb2', 1, 'practice', 'numeric', 2, 'V(x) = 50/x volts. Find E_x at x = 2 m.', '{"answer":12.5,"unit":"V/m"}', '[]', '$-\frac{d}{dx}\frac{50}{x} = \frac{50}{x^2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9a7839ed95f28', 'les_15d2f47e1e3bb2', 2, 'practice', 'numeric', 2, 'A uniform field E = 300 î V/m. Find V_B − V_A from x = 0 to x = 0.5 m.', '{"answer":-150,"unit":"V"}', '[]', '$-300(0.5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc3d36061ae480', 'les_15d2f47e1e3bb2', 3, 'practice', 'multiple_choice', 2, 'Where equipotential lines are closest together, the field is…', '{"choices":["weakest","strongest","zero","parallel to them"],"answer":1}', '[]', 'Large $\frac{dV}{dx}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dcf47106b47b9e', 'les_15d2f47e1e3bb2', 4, 'review', 'multiple_choice', 3, 'A positive charge released from rest moves toward…', '{"choices":["higher potential","lower potential","constant potential","higher field"],"answer":1}', '[]', 'It accelerates along E, downhill in V.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_15d2f47e1e3bb2', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_15d2f47e1e3bb2', (SELECT id FROM formulas WHERE slug = 'gauss-ampere'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_15d2f47e1e3bb2', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 2);

-- Lesson: em-potential-integral
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a84ff1046d224b', 'em-potential-integral', 'Electric potential', 'Compute electric potential of point charges and continuous distributions with V = ∫k dq/r, a scalar integral with no components to track.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5d5cfc84f1d10', 'les_a84ff1046d224b', 1, 'Define V = U/q and use V = kq/r with V(∞) = 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2324d5420a56b2', 'les_a84ff1046d224b', 2, 'Compute V for rings and rods with V = ∫k dq/r.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_508da62cb0367c', 'les_a84ff1046d224b', 3, 'Explain why potential integrals are simpler than field integrals.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5d5cfc84f1d10', 'les_a84ff1046d224b', 'learn', 1, 'definition', '{"term":"Potential","body":"$V = \\frac Uq$, the potential energy per unit test charge. For a point charge, $V = \\frac{kq}{r}$. For a continuous distribution, $V = \\int\\frac{k\\,dq}{r}$, a scalar sum with no directions to cancel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2324d5420a56b2', 'les_a84ff1046d224b', 'learn', 2, 'worked_example', '{"title":"A ring (Q = 5 nC, R = 0.3 m), at x = 0.4 m on its axis","steps":[{"latex":"\\text{every}\\ dq\\ \\text{is}\\ \\sqrt{x^2 + R^2}\\ \\text{away}","explanation":""},{"latex":"V = \\tfrac{kQ}{\\sqrt{x^2 + R^2}} = \\tfrac{8.99\\times10^9(5\\times10^{-9})}{0.5}","explanation":""},{"latex":"V \\approx 89.9\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_508da62cb0367c', 'les_a84ff1046d224b', 'learn', 3, 'worked_example', '{"title":"A rod (Q = 4 nC, L = 0.2 m), on its axis 0.1 m beyond one end","steps":[{"latex":"V = k\\lambda\\int_{0.1}^{0.3}\\tfrac{dx}{x} = k\\lambda\\ln 3","explanation":""},{"latex":"V = (8.99\\times10^9)(2\\times10^{-8})\\ln 3 \\approx 198\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd60477b584657', 'les_a84ff1046d224b', 'experiment', 4, 'activity', '{"activity":"electric-potential","title":"Potential adds as a scalar","params":{"q1":2,"q2":2,"separation":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfe79bebf1c6f0', 'les_a84ff1046d224b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Lightning rods, electron guns and electrostatic precipitators are designed using potential maps, because V is easier to compute than E."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5d5cfc84f1d10', 'les_a84ff1046d224b', 1, 'practice', 'numeric', 2, 'Find V at the center of the ring in the example.', '{"answer":150,"tolerance":0.5,"unit":"V"}', '[]', '$\frac{kQ}{R} = \frac{44.95}{0.3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2324d5420a56b2', 'les_a84ff1046d224b', 2, 'practice', 'numeric', 3, 'A thin semicircle of radius 0.2 m carries 3 nC. Find V at its center, to the nearest volt.', '{"answer":135,"tolerance":1,"unit":"V"}', '[]', 'All charge is 0.2 m away: $\frac{8.99\times10^9(3\times10^{-9})}{0.2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_508da62cb0367c', 'les_a84ff1046d224b', 3, 'practice', 'multiple_choice', 2, 'Why is V easier to integrate than E?', '{"choices":["V is always zero","V is a scalar, so no components to cancel","V has no units","E doesn''t exist for distributions"],"answer":1}', '[]', 'Scalar addition.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd60477b584657', 'les_a84ff1046d224b', 4, 'review', 'multiple_choice', 3, 'Two charges of +q and −q. At their midpoint…', '{"choices":["V = 0 and E = 0","V = 0 but E ≠ 0","V ≠ 0 but E = 0","both nonzero"],"answer":1}', '[]', 'Potentials cancel; fields both point toward −q.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a84ff1046d224b', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a84ff1046d224b', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: em-rc-calculus
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_39dc5554b5c0ba', 'em-rc-calculus', 'Resistor-capacitor (RC) circuits', 'Derive and solve the differential equations for charging and discharging capacitors, and track where the battery''s energy goes.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c1b06912aad6de', 'les_39dc5554b5c0ba', 1, 'Write the loop equation ε − IR − q/C = 0 with I = dq/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b502e29643142', 'les_39dc5554b5c0ba', 2, 'Solve it: q = Cε(1 − e^(−t/RC)) and I = (ε/R)e^(−t/RC).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0b18f40d3e3abe', 'les_39dc5554b5c0ba', 3, 'Show that charging dissipates exactly half the battery''s energy in the resistor.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c1b06912aad6de', 'les_39dc5554b5c0ba', 'learn', 1, 'definition', '{"term":"Charging","body":"Around the loop, $\\varepsilon - R\\frac{dq}{dt} - \\frac qC = 0$. Separating variables, $\\int_0^q\\frac{dq''}{C\\varepsilon - q''} = \\int_0^t\\frac{dt''}{RC}$, so $q = C\\varepsilon(1 - e^{-t/RC})$ and $I = \\frac{dq}{dt} = \\frac\\varepsilon Re^{-t/RC}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b502e29643142', 'les_39dc5554b5c0ba', 'learn', 2, 'definition', '{"term":"Discharging","body":"With no battery, $R\\frac{dq}{dt} + \\frac qC = 0$, so $q = Q_0e^{-t/RC}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b18f40d3e3abe', 'les_39dc5554b5c0ba', 'learn', 3, 'worked_example', '{"title":"Energy bookkeeping while charging fully","steps":[{"latex":"W_{battery} = \\varepsilon Q = C\\varepsilon^2","explanation":""},{"latex":"U_C = \\tfrac12 C\\varepsilon^2","explanation":""},{"latex":"\\int_0^\\infty I^2R\\,dt = \\tfrac{\\varepsilon^2}{R}\\cdot\\tfrac{RC}{2} = \\tfrac12C\\varepsilon^2","explanation":"Half is always lost as heat, whatever R is."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af9886faa1875c', 'les_39dc5554b5c0ba', 'experiment', 4, 'activity', '{"activity":"rc-circuit","title":"Charging and discharging curves","params":{"mode":"charge","voltage":9,"resistance":10,"capacitance":100}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84cb78378b7454', 'les_39dc5554b5c0ba', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Camera-flash chargers, timing circuits, and the signal delays in computer chips (RC delays in wiring) all follow these exponentials."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c1b06912aad6de', 'les_39dc5554b5c0ba', 1, 'practice', 'numeric', 2, 'A 100 μF capacitor discharges through 20 kΩ from 12 V. Find the voltage after 3 s, to two decimal places.', '{"answer":2.68,"tolerance":0.01,"unit":"V"}', '[]', '$\tau = 2$ s; $12e^{-1.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b502e29643142', 'les_39dc5554b5c0ba', 2, 'practice', 'numeric', 3, 'How long until a charging RC circuit (τ = 0.5 s) reaches 90% of full charge? Give two decimal places.', '{"answer":1.15,"tolerance":0.01,"unit":"s"}', '[]', '$1 - e^{-t/\tau} = 0.9$, so $t = \tau\ln 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0b18f40d3e3abe', 'les_39dc5554b5c0ba', 3, 'practice', 'multiple_choice', 2, 'Right after the switch closes, the uncharged capacitor behaves like…', '{"choices":["an open circuit","a wire","a resistor of value R","a battery"],"answer":1}', '[]', '$q = 0$, so its voltage is zero.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af9886faa1875c', 'les_39dc5554b5c0ba', 4, 'review', 'multiple_choice', 3, 'Charging a capacitor through a smaller resistor changes the energy lost as heat by…', '{"choices":["less","more","nothing","it depends on C only"],"answer":2}', '[]', 'Always $\frac12C\varepsilon^2$; a smaller R just makes it happen faster.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_39dc5554b5c0ba', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_39dc5554b5c0ba', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: em-resistivity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_15a2c38db87a32', 'em-resistivity', 'Resistance, resistivity and Ohm''s law', 'Connect E = ρJ to V = IR, compute resistance from resistivity and geometry (including by integration), and model temperature dependence.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6af93d2a85d191', 'les_15a2c38db87a32', 1, 'Use the microscopic form of Ohm''s law, E = ρJ, and the macroscopic form V = IR.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_885bbf7848c314', 'les_15a2c38db87a32', 2, 'Compute R = ρL/A, and R = ∫ρ dx/A(x) for non-uniform conductors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a2d3142c72f860', 'les_15a2c38db87a32', 3, 'Use ρ = ρ₀(1 + αΔT).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6af93d2a85d191', 'les_15a2c38db87a32', 'learn', 1, 'definition', '{"term":"Two forms","body":"Inside an ohmic material, $\\vec E = \\rho\\vec J$, where resistivity $\\rho$ (Ω·m) is a material property (copper $1.68\\times10^{-8}$; glass about $10^{12}$). For a uniform wire, integrating gives $V = IR$ with $R = \\frac{\\rho L}{A}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_885bbf7848c314', 'les_15a2c38db87a32', 'learn', 2, 'worked_example', '{"title":"10 m of copper wire, cross-section 1 mm²","steps":[{"latex":"R = \\tfrac{(1.68\\times10^{-8})(10)}{10^{-6}} = 0.168\\ \\Omega","explanation":""},{"latex":"R = 0.168(1 + 0.0039 \\times 50) \\approx 0.201\\ \\Omega","explanation":"50 °C hotter, with α = 0.0039/°C."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2d3142c72f860', 'les_15a2c38db87a32', 'learn', 3, 'definition', '{"term":"Non-uniform conductors","body":"If the cross-section changes, add thin slices in series: $R = \\int_0^L\\frac{\\rho\\,dx}{A(x)}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22cdb08d23dd1c', 'les_15a2c38db87a32', 'learn', 4, 'worked_example', '{"title":"A cone-shaped resistor whose radius grows linearly from a to b over length L","steps":[{"latex":"R = \\int_0^L\\tfrac{\\rho\\,dx}{\\pi\\left(a + \\tfrac{(b - a)x}{L}\\right)^2} = \\tfrac{\\rho L}{\\pi ab}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b14b990dce6d2a', 'les_15a2c38db87a32', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Strain gauges and thermistors measure force and temperature through resistance changes; power lines use thick aluminum to keep R low."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6af93d2a85d191', 'les_15a2c38db87a32', 1, 'practice', 'numeric', 2, 'A 2 m nichrome wire (ρ = 1.1 × 10⁻⁶ Ω·m) has a cross-section of 0.5 mm². Find its resistance.', '{"answer":4.4,"unit":"Ω"}', '[]', '$\frac{1.1\times10^{-6}(2)}{5\times10^{-7}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_885bbf7848c314', 'les_15a2c38db87a32', 2, 'practice', 'numeric', 3, 'A cone with a = 1 mm, b = 2 mm, L = 0.1 m and ρ = 1 × 10⁻⁵ Ω·m. Find R, to two decimal places.', '{"answer":0.16,"tolerance":0.01,"unit":"Ω"}', '[]', '$\frac{10^{-5}(0.1)}{\pi(10^{-3})(2\times10^{-3})} \approx 0.159$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2d3142c72f860', 'les_15a2c38db87a32', 3, 'practice', 'multiple_choice', 2, 'A wire is stretched to twice its length (same volume). Its resistance becomes…', '{"choices":["2R","4R","R/2","R"],"answer":1}', '[]', 'L doubles and A halves.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22cdb08d23dd1c', 'les_15a2c38db87a32', 4, 'review', 'multiple_choice', 3, 'In a wire carrying steady current, the field inside points…', '{"choices":["nowhere; it''s zero","along the current","perpendicular to it","against the current"],"answer":1}', '[]', '$\vec E = \rho\vec J$. Conductors only have E = 0 when no current flows.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_15a2c38db87a32', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_15a2c38db87a32', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: emission-spectra-chem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4573fa5c4bd017', 'emission-spectra-chem', 'Light and atomic emission spectra', 'Relate wavelength, frequency and photon energy, explain line spectra from electron transitions, and use flame tests to identify elements.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4fd0c02509680c', 'les_4573fa5c4bd017', 1, 'Use c = λν and E = hν.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a710bd096e972f', 'les_4573fa5c4bd017', 2, 'Explain line spectra as electrons dropping between fixed energy levels.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fdaab445b27205', 'les_4573fa5c4bd017', 3, 'Use flame colors and spectra to identify elements.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fd0c02509680c', 'les_4573fa5c4bd017', 'learn', 1, 'definition', '{"term":"Light","body":"Light travels at $c = 3.00\\times10^8$ m/s, with $c = \\lambda\\nu$ (chemists write frequency as ν). Each photon carries energy $E = h\\nu$, with $h = 6.626\\times10^{-34}$ J·s, so shorter wavelengths carry more energy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a710bd096e972f', 'les_4573fa5c4bd017', 'learn', 2, 'definition', '{"term":"Line spectra","body":"Heated atoms'' electrons jump to higher energy levels, then fall back, emitting photons whose energies equal the gaps. Since each element has its own set of levels, it emits only certain wavelengths: a bright-line spectrum that acts as a fingerprint."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fdaab445b27205', 'les_4573fa5c4bd017', 'learn', 3, 'worked_example', '{"title":"Hydrogen''s red line at 656 nm","steps":[{"latex":"\\nu = \\tfrac{3.00\\times10^8}{656\\times10^{-9}} \\approx 4.57\\times10^{14}\\ \\text{Hz}","explanation":""},{"latex":"E = h\\nu \\approx 3.03\\times10^{-19}\\ \\text{J}","explanation":"Per photon."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1f1bc6cfa2c0e', 'les_4573fa5c4bd017', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Fireworks colors (strontium red, copper blue-green, sodium yellow), sodium streetlights, and astronomers identifying elements in distant stars."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fd0c02509680c', 'les_4573fa5c4bd017', 1, 'practice', 'numeric', 2, 'Find the energy of a sodium photon at 589 nm, in units of $10^{-19}$ J, to two decimal places.', '{"answer":3.37,"tolerance":0.01}', '[]', '$\frac{(6.626\times10^{-34})(3.00\times10^8)}{589\times10^{-9}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a710bd096e972f', 'les_4573fa5c4bd017', 2, 'practice', 'numeric', 2, 'Find the wavelength of light with frequency 6.0 × 10¹⁴ Hz, in nm.', '{"answer":500,"unit":"nm"}', '[]', '$\frac{3.00\times10^8}{6.0\times10^{14}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fdaab445b27205', 'les_4573fa5c4bd017', 3, 'practice', 'multiple_choice', 2, 'Which carries the most energy per photon?', '{"choices":["red light","green light","violet light","infrared"],"answer":2}', '[]', 'Shortest wavelength.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1f1bc6cfa2c0e', 'les_4573fa5c4bd017', 4, 'review', 'multiple_choice', 3, 'An element''s emission lines appear only at specific wavelengths because…', '{"choices":["light is a wave","electron energies are quantized","atoms are hot","flames are colored"],"answer":1}', '[]', 'Only certain gaps exist.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4627f09e2fbf74', 'subj_chem', 'atomic-structure', 'Atomic structure', 'The particles inside atoms and how electrons are arranged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4573fa5c4bd017', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4573fa5c4bd017', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 1);

-- Lesson: energy-heat-chem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_73b77f7af4d71b', 'energy-heat-chem', 'Energy, heat and specific heat', 'Distinguish heat from temperature, classify processes as endothermic or exothermic, and compute heat with q = mcΔT.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98fa849c402931', 'les_73b77f7af4d71b', 1, 'Distinguish heat (energy transfer) from temperature.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e9b2fb40e12a82', 'les_73b77f7af4d71b', 2, 'Classify reactions and changes as endothermic or exothermic, from the system''s view.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_231eb1ba9a4a53', 'les_73b77f7af4d71b', 3, 'Use q = mcΔT and convert between joules and calories.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98fa849c402931', 'les_73b77f7af4d71b', 'learn', 1, 'definition', '{"term":"System and surroundings","body":"In an exothermic process the system releases heat to the surroundings, which warm up (combustion, freezing). In an endothermic process the system absorbs heat, so the surroundings cool (melting, cold packs). 1 cal = 4.184 J, and a food Calorie is 1000 cal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9b2fb40e12a82', 'les_73b77f7af4d71b', 'learn', 2, 'definition', '{"term":"Specific heat","body":"$q = mc\\Delta T$, with water''s $c = 4.184$ J/(g·°C). Positive q means heat absorbed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_231eb1ba9a4a53', 'les_73b77f7af4d71b', 'learn', 3, 'worked_example', '{"title":"Heat 50.0 g of water from 25.0 °C to 75.0 °C","steps":[{"latex":"q = 50.0(4.184)(50.0)","explanation":""},{"latex":"q = 10{,}460\\ \\text{J} \\approx 10.5\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b2545f2ed1b28', 'les_73b77f7af4d71b', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Instant cold packs (dissolving NH₄NO₃ is endothermic), hand warmers (iron oxidizing is exothermic) and nutrition labels."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98fa849c402931', 'les_73b77f7af4d71b', 1, 'practice', 'numeric', 2, 'How much heat warms 200. g of water by 15.0 °C, in kJ? Two decimal places.', '{"answer":12.55,"tolerance":0.01,"unit":"kJ"}', '[]', '$200(4.184)(15.0) = 12{,}552$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e9b2fb40e12a82', 'les_73b77f7af4d71b', 2, 'practice', 'numeric', 2, 'A 25.0 g metal absorbs 450. J and warms by 40.0 °C. Find its specific heat, in J/(g·°C), to three decimal places.', '{"answer":0.45,"tolerance":0.001,"unit":"J/(g·°C)"}', '[]', '$\frac{450}{25.0(40.0)}$ (iron).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_231eb1ba9a4a53', 'les_73b77f7af4d71b', 3, 'practice', 'multiple_choice', 2, 'Ice melting in your hand is…', '{"choices":["exothermic","endothermic","neither","both"],"answer":1}', '[]', 'The ice absorbs heat from your hand.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b2545f2ed1b28', 'les_73b77f7af4d71b', 4, 'review', 'multiple_choice', 3, 'Equal masses of water and iron absorb the same heat. Which warms more?', '{"choices":["water","iron","equal","depends on the starting temperature"],"answer":1}', '[]', 'Iron''s specific heat is much lower.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_60cc8b0e3374de', 'subj_chem', 'thermochemistry', 'Thermochemistry', 'Heat changes in reactions and physical processes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_73b77f7af4d71b', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_73b77f7af4d71b', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: enthalpy-calorimetry
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_666e2578ac3fab', 'enthalpy-calorimetry', 'Enthalpy and calorimetry', 'Use enthalpy change ΔH with thermochemical equations, measure ΔH with a coffee-cup calorimeter, and combine reactions with Hess''s law.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2aa67a2a149ace', 'les_666e2578ac3fab', 1, 'Interpret ΔH and its sign in thermochemical equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c736a4d1f8f420', 'les_666e2578ac3fab', 2, 'Calculate ΔH from calorimetry data: q_rxn = −q_solution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c08381253f9bb', 'les_666e2578ac3fab', 3, 'Use Hess''s law to add reactions and their ΔH values.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2aa67a2a149ace', 'les_666e2578ac3fab', 'learn', 1, 'definition', '{"term":"Enthalpy","body":"ΔH is the heat absorbed by a reaction at constant pressure; negative means exothermic. In $\\text{CH}_4 + 2\\text{O}_2 \\to \\text{CO}_2 + 2\\text{H}_2\\text{O}$, ΔH = −890 kJ: that much heat per mole of CH₄ as written. Doubling the equation doubles ΔH; reversing it flips the sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c736a4d1f8f420', 'les_666e2578ac3fab', 'learn', 2, 'definition', '{"term":"Calorimetry","body":"In a coffee-cup calorimeter, the reaction''s heat goes into the solution: $q_{rxn} = -q_{soln} = -mc\\Delta T$. Then $\\Delta H = \\frac{q_{rxn}}{n}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c08381253f9bb', 'les_666e2578ac3fab', 'learn', 3, 'worked_example', '{"title":"50.0 mL of 1.00 M HCl and 50.0 mL of 1.00 M NaOH mix; the temperature rises 6.7 °C","steps":[{"latex":"q_{soln} = 100.0(4.184)(6.7) \\approx 2800\\ \\text{J}","explanation":"About 100 g of solution."},{"latex":"n = 0.0500\\ \\text{mol of water formed}","explanation":""},{"latex":"\\Delta H = \\tfrac{-2.80\\ \\text{kJ}}{0.0500\\ \\text{mol}} \\approx -56\\ \\text{kJ/mol}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f211b28f082e5f', 'les_666e2578ac3fab', 'learn', 4, 'definition', '{"term":"Hess''s law","body":"If a reaction is the sum of steps, its ΔH is the sum of their ΔH values, whatever the path."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57c8d9ad965361', 'les_666e2578ac3fab', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Food calorie values come from bomb calorimetry; engineers compare fuels by kJ per gram; Hess''s law gives ΔH for reactions too slow or dangerous to measure."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2aa67a2a149ace', 'les_666e2578ac3fab', 1, 'practice', 'numeric', 2, '2H₂ + O₂ → 2H₂O has ΔH = −572 kJ. Find ΔH for forming 1 mol of water.', '{"answer":-286,"unit":"kJ"}', '[]', 'Halve the equation.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c736a4d1f8f420', 'les_666e2578ac3fab', 2, 'practice', 'numeric', 3, 'Dissolving 2.00 g of NH₄NO₃ (80.04 g/mol) in water drops the temperature of 100. g of solution by 1.53 °C. Find ΔH in kJ/mol, to one decimal place.', '{"answer":25.6,"tolerance":0.1,"unit":"kJ/mol"}', '[]', '$q_{soln} = 100(4.184)(-1.53) = -640$ J, so $q_{rxn} = +640$ J; $n = \frac{2.00}{80.04} = 0.0250$ mol; $\Delta H = \frac{0.640}{0.0250} \approx +25.6$ kJ/mol (endothermic).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c08381253f9bb', 'les_666e2578ac3fab', 3, 'practice', 'multiple_choice', 2, 'If A → B has ΔH = +40 kJ, then B → A has ΔH =', '{"choices":["+40 kJ","−40 kJ","0","+80 kJ"],"answer":1}', '[]', 'Reversing flips the sign.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f211b28f082e5f', 'les_666e2578ac3fab', 4, 'review', 'multiple_choice', 3, 'A calorimeter''s temperature rises. The reaction is…', '{"choices":["endothermic","exothermic","neither","impossible to tell"],"answer":1}', '[]', 'It released heat into the solution.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_60cc8b0e3374de', 'subj_chem', 'thermochemistry', 'Thermochemistry', 'Heat changes in reactions and physical processes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_666e2578ac3fab', (SELECT id FROM concepts WHERE slug = 'thermochemistry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_666e2578ac3fab', (SELECT id FROM formulas WHERE slug = 'heat-enthalpy'), 1);

-- Lesson: equilibrium-le-chatelier
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5f8a4eb8119b2b', 'equilibrium-le-chatelier', 'Chemical equilibrium and Le Châtelier''s principle', 'Describe dynamic equilibrium, write equilibrium expressions, compare Q with K, and predict shifts from concentration, pressure and temperature changes.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f5fc9f1ba70fb', 'les_5f8a4eb8119b2b', 1, 'Describe dynamic equilibrium: forward and reverse rates are equal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5bba3dffaa71a2', 'les_5f8a4eb8119b2b', 2, 'Write K expressions and interpret large and small K.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e1320679d0c5e0', 'les_5f8a4eb8119b2b', 3, 'Use Q vs K and Le Châtelier''s principle to predict shifts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f5fc9f1ba70fb', 'les_5f8a4eb8119b2b', 'learn', 1, 'definition', '{"term":"Dynamic equilibrium","body":"In a closed system, a reversible reaction reaches a state where forward and reverse rates are equal, so concentrations stop changing, though both reactions continue. For $aA + bB \\rightleftharpoons cC + dD$, $K = \\frac{[C]^c[D]^d}{[A]^a[B]^b}$. Leave out pure solids and liquids. A large K favors products; a small K, reactants."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5bba3dffaa71a2', 'les_5f8a4eb8119b2b', 'learn', 2, 'worked_example', '{"title":"N₂O₄ ⇌ 2NO₂ at equilibrium has [NO₂] = 0.040 M and [N₂O₄] = 0.20 M","steps":[{"latex":"K = \\tfrac{(0.040)^2}{0.20} = 0.0080","explanation":"Reactants are favored."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1320679d0c5e0', 'les_5f8a4eb8119b2b', 'learn', 3, 'definition', '{"term":"Le Châtelier''s principle","body":"A system at equilibrium shifts to partly undo a stress. Add a reactant or remove a product: it shifts right. Raise pressure by shrinking the volume: it shifts toward fewer gas moles. Raising temperature favors the endothermic direction, and changes K itself."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_436540bde575c3', 'les_5f8a4eb8119b2b', 'experiment', 4, 'activity', '{"activity":"equilibrium","title":"Stress the equilibrium","params":{"K":4,"A0":1,"B0":1,"amount":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b004de9dd988d', 'les_5f8a4eb8119b2b', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Add A and compare Q with K right after: Q < K, so the bars shift toward C. Now add C instead."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89c17893ed10cb', 'les_5f8a4eb8119b2b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"The Haber process makes ammonia at high pressure (4 gas moles → 2), and hemoglobin''s oxygen binding shifts with altitude."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f5fc9f1ba70fb', 'les_5f8a4eb8119b2b', 1, 'practice', 'numeric', 2, 'For H₂ + I₂ ⇌ 2HI, [H₂] = [I₂] = 0.10 M and [HI] = 0.70 M. Find K.', '{"answer":49}', '[]', '$\frac{0.49}{0.01}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5bba3dffaa71a2', 'les_5f8a4eb8119b2b', 2, 'practice', 'multiple_choice', 2, 'For N₂ + 3H₂ ⇌ 2NH₃, increasing the pressure shifts it…', '{"choices":["left","right","not at all","toward N₂ only"],"answer":1}', '[]', '4 gas moles → 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1320679d0c5e0', 'les_5f8a4eb8119b2b', 3, 'practice', 'multiple_choice', 2, 'If Q > K, the reaction…', '{"choices":["shifts right","shifts left","is at equilibrium","stops"],"answer":1}', '[]', 'Too much product.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_436540bde575c3', 'les_5f8a4eb8119b2b', 4, 'review', 'multiple_choice', 3, 'Adding a catalyst to a system at equilibrium…', '{"choices":["shifts it right","shifts it left","doesn''t change the equilibrium position","changes K"],"answer":2}', '[]', 'It speeds both directions equally.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_255790fdd5bd7f', 'subj_chem', 'equilibrium', 'Chemical equilibrium', 'The balance of forward and reverse reactions and how it responds to change.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5f8a4eb8119b2b', (SELECT id FROM concepts WHERE slug = 'equilibrium'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5f8a4eb8119b2b', (SELECT id FROM formulas WHERE slug = 'equilibrium-constant'), 1);

-- Lesson: ionic-bonding
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9773bf2195e393', 'ionic-bonding', 'Ionic bonding and ionic compounds', 'Explain ionic bonding as electron transfer, predict ion charges, write formulas by balancing charges, and relate structure to properties.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b174592bec7a20', 'les_9773bf2195e393', 1, 'Predict common ion charges from group number.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35312da48642a2', 'les_9773bf2195e393', 2, 'Write formulas of ionic compounds by balancing total charge.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3de52b97b4f524', 'les_9773bf2195e393', 3, 'Explain the properties of ionic compounds from their crystal lattice.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b174592bec7a20', 'les_9773bf2195e393', 'learn', 1, 'definition', '{"term":"Electron transfer","body":"Metals lose electrons to reach a noble-gas configuration (Na → Na⁺); nonmetals gain them (Cl → Cl⁻). The oppositely charged ions attract strongly, forming a lattice. Common charges: Group 1 +1, Group 2 +2, Al +3, N −3, O −2, halogens −1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35312da48642a2', 'les_9773bf2195e393', 'learn', 2, 'definition', '{"term":"Formulas","body":"The formula unit has zero net charge. Use the lowest whole-number ratio: crossing the charge magnitudes often works, then reduce."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3de52b97b4f524', 'les_9773bf2195e393', 'learn', 3, 'worked_example', '{"title":"Aluminum oxide and calcium nitride","steps":[{"latex":"\\text{Al}^{3+},\\ \\text{O}^{2-} \\Rightarrow \\text{Al}_2\\text{O}_3","explanation":"2(+3) + 3(−2) = 0."},{"latex":"\\text{Ca}^{2+},\\ \\text{N}^{3-} \\Rightarrow \\text{Ca}_3\\text{N}_2","explanation":"3(+2) + 2(−3) = 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3154e969ebcd75', 'les_9773bf2195e393', 'learn', 4, 'definition', '{"term":"Properties","body":"Ionic solids are hard, brittle and have high melting points (NaCl melts at 801 °C). They conduct electricity when melted or dissolved, when ions are free to move, but not as solids."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_77a8f9dc9d7192', 'les_9773bf2195e393', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Table salt, the calcium phosphate in bones, and electrolytes in sports drinks and batteries."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b174592bec7a20', 'les_9773bf2195e393', 1, 'practice', 'multiple_choice', 2, 'What is the formula of magnesium chloride?', '{"choices":["MgCl","MgCl₂","Mg₂Cl","Mg₂Cl₃"],"answer":1}', '[]', 'Mg²⁺ needs two Cl⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35312da48642a2', 'les_9773bf2195e393', 2, 'practice', 'numeric', 2, 'How many ions are in one formula unit of Al₂O₃?', '{"answer":5}', '[]', '2 Al³⁺ + 3 O²⁻.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3de52b97b4f524', 'les_9773bf2195e393', 3, 'practice', 'multiple_choice', 2, 'Solid NaCl doesn''t conduct electricity because…', '{"choices":["it has no ions","its ions are locked in place","it''s a metal","chlorine is a gas"],"answer":1}', '[]', 'Ions must be free to move.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3154e969ebcd75', 'les_9773bf2195e393', 4, 'review', 'multiple_choice', 3, 'Which pair forms an ionic compound?', '{"choices":["C and O","K and Br","N and H","S and O"],"answer":1}', '[]', 'A metal and a nonmetal.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_793ae6aa1f37d6', 'subj_chem', 'chemical-bonding', 'Chemical bonding', 'Ionic, covalent and metallic bonds and the shapes and polarity of molecules.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9773bf2195e393', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: isotopes-atomic-mass
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7301c7bdb1723e', 'isotopes-atomic-mass', 'Isotopes and average atomic mass', 'Define isotopes, write isotope notation, and compute the weighted-average atomic mass on the periodic table from isotope abundances.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2d4e7d0a6e7f45', 'les_7301c7bdb1723e', 1, 'Define isotopes and write isotope symbols.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d27e2924bb72e1', 'les_7301c7bdb1723e', 2, 'Compute average atomic mass as an abundance-weighted average.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e7ae9530ffd09', 'les_7301c7bdb1723e', 3, 'Work backward from an average mass to an isotope abundance.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d4e7d0a6e7f45', 'les_7301c7bdb1723e', 'learn', 1, 'definition', '{"term":"Isotopes","body":"Isotopes are atoms of the same element (same number of protons) with different numbers of neutrons, such as carbon-12 and carbon-14. They behave almost identically in chemical reactions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d27e2924bb72e1', 'les_7301c7bdb1723e', 'learn', 2, 'definition', '{"term":"Average atomic mass","body":"The atomic mass on the periodic table is the weighted average of the isotopes'' masses: $\\bar m = \\sum(\\text{fraction})\\times(\\text{isotope mass})$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e7ae9530ffd09', 'les_7301c7bdb1723e', 'learn', 3, 'worked_example', '{"title":"Chlorine: 75.78% Cl-35 (34.969 u) and 24.22% Cl-37 (36.966 u)","steps":[{"latex":"\\bar m = 0.7578(34.969) + 0.2422(36.966)","explanation":""},{"latex":"\\bar m \\approx 35.45\\ \\text{u}","explanation":"Closer to 35 because Cl-35 is more common."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9ddc86cc990de', 'les_7301c7bdb1723e', 'learn', 4, 'worked_example', '{"title":"Boron (10.81 u) is B-10 (10.013 u) and B-11 (11.009 u). Find the B-10 fraction x","steps":[{"latex":"10.013x + 11.009(1 - x) = 10.81","explanation":""},{"latex":"x = \\tfrac{11.009 - 10.81}{0.996} \\approx 0.20","explanation":"About 20% B-10."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aec4034539b764', 'les_7301c7bdb1723e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbon-14 dating, uranium enrichment and isotope-ratio tests that catch counterfeit honey and doping athletes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2d4e7d0a6e7f45', 'les_7301c7bdb1723e', 1, 'practice', 'numeric', 2, 'Copper is 69.15% Cu-63 (62.930 u) and 30.85% Cu-65 (64.928 u). Find its average atomic mass, to two decimal places.', '{"answer":63.55,"tolerance":0.01,"unit":"u"}', '[]', '$0.6915(62.930) + 0.3085(64.928)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d27e2924bb72e1', 'les_7301c7bdb1723e', 2, 'practice', 'numeric', 3, 'Gallium (69.72 u) is Ga-69 (68.926 u) and Ga-71 (70.925 u). Find the percent of Ga-69, to the nearest percent.', '{"answer":60,"tolerance":1,"unit":"%"}', '[]', '$x = \frac{70.925 - 69.72}{1.999} \approx 0.603$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e7ae9530ffd09', 'les_7301c7bdb1723e', 3, 'practice', 'multiple_choice', 2, 'Carbon-12 and carbon-14 differ in…', '{"choices":["protons","electrons","neutrons","chemical behavior"],"answer":2}', '[]', 'Same element.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a9ddc86cc990de', 'les_7301c7bdb1723e', 4, 'review', 'multiple_choice', 3, 'Why is no atom of chlorine exactly 35.45 u?', '{"choices":["rounding","it''s an average of isotopes","electrons have mass","measurement error"],"answer":1}', '[]', 'Individual atoms are 35 or 37.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_4627f09e2fbf74', 'subj_chem', 'atomic-structure', 'Atomic structure', 'The particles inside atoms and how electrons are arranged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7301c7bdb1723e', (SELECT id FROM concepts WHERE slug = 'atomic-structure'));

-- Lesson: kmt-chemistry
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_86cea50cb48424', 'kmt-chemistry', 'Kinetic molecular theory', 'State the postulates of kinetic molecular theory, explain gas properties with them, and compare effusion rates with Graham''s law.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4eb0dd0f8f7ec2', 'les_86cea50cb48424', 1, 'State the postulates of kinetic molecular theory.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_284c5bd0d7f31b', 'les_86cea50cb48424', 2, 'Explain pressure, diffusion and compressibility with particle motion.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0ec234661f3ddf', 'les_86cea50cb48424', 3, 'Use Graham''s law: rate₁/rate₂ = √(M₂/M₁).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4eb0dd0f8f7ec2', 'les_86cea50cb48424', 'learn', 1, 'definition', '{"term":"Postulates","body":"Gas particles: are tiny compared with the spaces between them; move constantly and randomly in straight lines; collide elastically; don''t attract or repel each other; and have an average kinetic energy proportional to the kelvin temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_284c5bd0d7f31b', 'les_86cea50cb48424', 'learn', 2, 'definition', '{"term":"Graham''s law","body":"At the same temperature, all gases have the same average kinetic energy, so lighter molecules move faster: $\\frac{\\text{rate}_1}{\\text{rate}_2} = \\sqrt{\\frac{M_2}{M_1}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ec234661f3ddf', 'les_86cea50cb48424', 'learn', 3, 'worked_example', '{"title":"How much faster does helium (4.00 g/mol) effuse than oxygen (32.00 g/mol)?","steps":[{"latex":"\\sqrt{\\tfrac{32.00}{4.00}} = \\sqrt8 \\approx 2.83\\ \\text{times faster}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37e0f709faccb4', 'les_86cea50cb48424', 'experiment', 4, 'activity', '{"activity":"ideal-gas","title":"Particles and pressure"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_830b100f7c3b61', 'les_86cea50cb48424', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Helium balloons deflate faster than air-filled ones, and uranium was enriched for reactors by repeated effusion of UF₆."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4eb0dd0f8f7ec2', 'les_86cea50cb48424', 1, 'practice', 'numeric', 2, 'How much faster does H₂ (2.016 g/mol) effuse than CO₂ (44.01 g/mol)? Two decimal places.', '{"answer":4.67,"tolerance":0.01}', '[]', '$\sqrt{\frac{44.01}{2.016}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_284c5bd0d7f31b', 'les_86cea50cb48424', 2, 'practice', 'multiple_choice', 2, 'Gases are easily compressed because…', '{"choices":["particles are soft","there''s mostly empty space between particles","particles attract","they''re hot"],"answer":1}', '[]', 'Postulate 1.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ec234661f3ddf', 'les_86cea50cb48424', 3, 'practice', 'multiple_choice', 2, 'Raising the temperature of a gas raises the particles''…', '{"choices":["mass","average kinetic energy","size","number"],"answer":1}', '[]', 'KE is proportional to T in kelvin.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37e0f709faccb4', 'les_86cea50cb48424', 4, 'review', 'multiple_choice', 3, 'Real gases deviate most from the KMT model at…', '{"choices":["high T, low P","low T, high P","room conditions","in vacuum"],"answer":1}', '[]', 'Particles are close and attract.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_86cea50cb48424', (SELECT id FROM concepts WHERE slug = 'kinetic-molecular-theory'));

-- Lesson: molarity-dilution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_44896c7ca7b24b', 'molarity-dilution', 'Molarity and dilution', 'Calculate molarity, prepare solutions from solids, and dilute stock solutions with M₁V₁ = M₂V₂.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_07b2ec05bb6463', 'les_44896c7ca7b24b', 1, 'Calculate molarity, M = mol solute / L solution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5aa128c0e540df', 'les_44896c7ca7b24b', 2, 'Find the mass of solute needed to make a solution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4159f0c7e47cc2', 'les_44896c7ca7b24b', 3, 'Use M₁V₁ = M₂V₂ for dilutions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_07b2ec05bb6463', 'les_44896c7ca7b24b', 'learn', 1, 'definition', '{"term":"Molarity","body":"$M = \\frac{\\text{moles of solute}}{\\text{liters of solution}}$. Note: liters of solution, not of solvent. To make a solution, dissolve the solute and then add water up to the final volume."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5aa128c0e540df', 'les_44896c7ca7b24b', 'learn', 2, 'worked_example', '{"title":"5.85 g of NaCl is dissolved to make 250.0 mL of solution","steps":[{"latex":"n = \\tfrac{5.85}{58.44} = 0.100\\ \\text{mol}","explanation":""},{"latex":"M = \\tfrac{0.100}{0.2500} = 0.400\\ \\text{M}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4159f0c7e47cc2', 'les_44896c7ca7b24b', 'learn', 3, 'definition', '{"term":"Dilution","body":"Adding water doesn''t change the moles of solute: $M_1V_1 = M_2V_2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b12711663ba5b', 'les_44896c7ca7b24b', 'learn', 4, 'worked_example', '{"title":"Dilute 50.0 mL of 2.0 M HCl to 0.50 M","steps":[{"latex":"V_2 = \\tfrac{2.0(50.0)}{0.50} = 200\\ \\text{mL}","explanation":"Add water to a total of 200 mL."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9b56ae9e8500e6', 'les_44896c7ca7b24b', 'learn', 5, 'callout', '{"tone":"warning","title":"Safety","body":"When diluting concentrated acids, add acid to water, never water to acid: the heat released can make water boil and spatter."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_629b42d803a7b0', 'les_44896c7ca7b24b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"IV saline (0.154 M NaCl), blood tests reported in mmol/L, and lab stock solutions diluted for each experiment."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_07b2ec05bb6463', 'les_44896c7ca7b24b', 1, 'practice', 'numeric', 2, 'How many grams of NaOH (40.00 g/mol) make 500. mL of 0.200 M solution?', '{"answer":4,"tolerance":0.01,"unit":"g"}', '[]', '$0.200(0.500)(40.00)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5aa128c0e540df', 'les_44896c7ca7b24b', 2, 'practice', 'numeric', 2, '25.0 mL of 6.0 M H₂SO₄ is diluted to 300. mL. Find the new molarity.', '{"answer":0.5,"unit":"M"}', '[]', '$\frac{6.0(25.0)}{300}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4159f0c7e47cc2', 'les_44896c7ca7b24b', 3, 'practice', 'numeric', 2, 'How many moles of solute are in 75.0 mL of 0.40 M KCl?', '{"answer":0.03,"tolerance":0.0001,"unit":"mol"}', '[]', '$0.40 \times 0.0750$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b12711663ba5b', 'les_44896c7ca7b24b', 4, 'review', 'multiple_choice', 3, 'Dissolving 1 mol of sugar in 1 L of water gives a concentration that is…', '{"choices":["exactly 1 M","slightly less than 1 M","slightly more than 1 M","2 M"],"answer":1}', '[]', 'The final volume is more than 1 L.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8facaaa9e16a70', 'subj_chem', 'solutions', 'Solutions', 'Homogeneous mixtures, their concentrations and properties.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_44896c7ca7b24b', (SELECT id FROM concepts WHERE slug = 'solutions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_44896c7ca7b24b', (SELECT id FROM formulas WHERE slug = 'molarity-dilution'), 1);

-- Lesson: mole-molar-mass
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5967982035fb27', 'mole-molar-mass', 'The mole and molar mass', 'Count particles with the mole, compute molar masses from the periodic table, and convert among grams, moles and particles.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_382c6d021d3c42', 'les_5967982035fb27', 1, 'Define the mole: 6.022 × 10²³ particles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_94d7fb60ad1295', 'les_5967982035fb27', 2, 'Compute molar mass from a formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_50557d2119b389', 'les_5967982035fb27', 3, 'Convert between mass, moles and number of particles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_382c6d021d3c42', 'les_5967982035fb27', 'learn', 1, 'definition', '{"term":"The mole","body":"One mole is $6.022\\times10^{23}$ particles (Avogadro''s number), chosen so that one mole of an element has a mass in grams equal to its atomic mass. Molar mass (g/mol) of a compound is the sum of its atoms'' masses: H₂O is $2(1.008) + 16.00 = 18.02$ g/mol."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_94d7fb60ad1295', 'les_5967982035fb27', 'learn', 2, 'definition', '{"term":"Conversions","body":"grams $\\xrightarrow{\\div M}$ moles $\\xrightarrow{\\times N_A}$ particles, and back the other way."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50557d2119b389', 'les_5967982035fb27', 'learn', 3, 'worked_example', '{"title":"How many moles and molecules are in 36.04 g of water?","steps":[{"latex":"n = \\tfrac{36.04}{18.02} = 2.000\\ \\text{mol}","explanation":""},{"latex":"N = 2.000(6.022\\times10^{23}) = 1.204\\times10^{24}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_772ebf6167a52a', 'les_5967982035fb27', 'learn', 4, 'worked_example', '{"title":"What is the mass of 0.250 mol of NaCl?","steps":[{"latex":"M = 22.99 + 35.45 = 58.44\\ \\text{g/mol}","explanation":""},{"latex":"m = 0.250(58.44) = 14.6\\ \\text{g}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_212563ac78a474', 'les_5967982035fb27', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every recipe in a chemistry lab, drug dosages calculated per mole, and the reason a teaspoon of water holds more molecules than there are stars in the observable universe."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_382c6d021d3c42', 'les_5967982035fb27', 1, 'practice', 'numeric', 1, 'Find the molar mass of CO₂ (C 12.01, O 16.00).', '{"answer":44.01,"tolerance":0.01,"unit":"g/mol"}', '[]', '$12.01 + 2(16.00)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_94d7fb60ad1295', 'les_5967982035fb27', 2, 'practice', 'numeric', 2, 'How many molecules are in 0.500 mol of O₂, in units of $10^{23}$?', '{"answer":3.011,"tolerance":0.001}', '[]', '$0.5 \times 6.022$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50557d2119b389', 'les_5967982035fb27', 3, 'practice', 'numeric', 2, 'How many moles are in 100. g of CaCO₃ (100.09 g/mol)? Give three decimal places.', '{"answer":0.999,"tolerance":0.001,"unit":"mol"}', '[]', '$\frac{100}{100.09}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_772ebf6167a52a', 'les_5967982035fb27', 4, 'review', 'multiple_choice', 3, 'Which contains the most atoms?', '{"choices":["1 mol of He","1 mol of H₂O","1 mol of CH₄","1 mol of NaCl"],"answer":2}', '[]', 'CH₄ has 5 atoms per molecule.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5967982035fb27', (SELECT id FROM concepts WHERE slug = 'the-mole'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5967982035fb27', (SELECT id FROM formulas WHERE slug = 'molar-mass-moles'), 1);

-- Lesson: mole-ratio-stoichiometry
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5c067360b5d572', 'mole-ratio-stoichiometry', 'Mole ratios and stoichiometry', 'Use mole ratios from balanced equations to convert between amounts of reactants and products, with the grams → moles → moles → grams path.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_32a9f248272b1d', 'les_5c067360b5d572', 1, 'Read mole ratios from a balanced equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc53e372cf2a1c', 'les_5c067360b5d572', 2, 'Convert mass of one substance to mass of another through moles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4960ae4a89077', 'les_5c067360b5d572', 3, 'Check answers with conservation of mass.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32a9f248272b1d', 'les_5c067360b5d572', 'learn', 1, 'definition', '{"term":"Mole ratios","body":"Coefficients in a balanced equation give mole ratios, not mass ratios. In $2\\text{H}_2 + \\text{O}_2 \\to 2\\text{H}_2\\text{O}$, 2 mol of H₂ react with 1 mol of O₂ to make 2 mol of H₂O."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc53e372cf2a1c', 'les_5c067360b5d572', 'learn', 2, 'definition', '{"term":"The path","body":"grams A $\\xrightarrow{\\div M_A}$ mol A $\\xrightarrow{\\times\\text{ratio}}$ mol B $\\xrightarrow{\\times M_B}$ grams B."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4960ae4a89077', 'les_5c067360b5d572', 'learn', 3, 'worked_example', '{"title":"What mass of CO₂ forms when 10.0 g of methane burns? CH₄ + 2O₂ → CO₂ + 2H₂O","steps":[{"latex":"n_{\\text{CH}_4} = \\tfrac{10.0}{16.04} = 0.623\\ \\text{mol}","explanation":""},{"latex":"n_{\\text{CO}_2} = 0.623\\ \\text{mol}","explanation":"A 1 : 1 ratio."},{"latex":"m = 0.623(44.01) \\approx 27.4\\ \\text{g}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5477e7232462f4', 'les_5c067360b5d572', 'experiment', 4, 'activity', '{"activity":"stoichiometry","title":"Reactant amounts and products"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b99d9c2300ac9', 'les_5c067360b5d572', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pharmaceutical manufacturing, airbag design (how much NaN₃ gives enough N₂) and spacecraft life support that scrubs CO₂ with LiOH."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32a9f248272b1d', 'les_5c067360b5d572', 1, 'practice', 'numeric', 2, 'In 2H₂ + O₂ → 2H₂O, how many moles of O₂ react with 6 mol of H₂?', '{"answer":3,"unit":"mol"}', '[]', 'Ratio 1 : 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc53e372cf2a1c', 'les_5c067360b5d572', 2, 'practice', 'numeric', 2, 'How many grams of water form from 4.00 g of H₂ with excess O₂? Give one decimal place.', '{"answer":35.7,"tolerance":0.1,"unit":"g"}', '[]', '$\frac{4.00}{2.016} = 1.984$ mol H₂, so 1.984 mol H₂O $\times 18.02$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4960ae4a89077', 'les_5c067360b5d572', 3, 'practice', 'numeric', 3, '2KClO₃ → 2KCl + 3O₂. How many grams of O₂ come from 24.5 g of KClO₃ (122.55 g/mol)? Give two decimal places.', '{"answer":9.6,"tolerance":0.02,"unit":"g"}', '[]', '$0.1999$ mol $\times \frac32 = 0.300$ mol $\times 32.00$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5477e7232462f4', 'les_5c067360b5d572', 4, 'review', 'multiple_choice', 3, 'Coefficients in a balanced equation give ratios of…', '{"choices":["masses","moles","volumes of liquids","densities"],"answer":1}', '[]', 'They count particles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5c067360b5d572', (SELECT id FROM concepts WHERE slug = 'stoichiometry'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5c067360b5d572', (SELECT id FROM formulas WHERE slug = 'molar-mass-moles'), 1);

-- Lesson: molecular-geometry-vsepr
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_65267568dd22a2', 'molecular-geometry-vsepr', 'Molecular geometry (VSEPR)', 'Predict molecular shapes and bond angles from Lewis structures using VSEPR theory, including the effect of lone pairs.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1dfde0709c82e1', 'les_65267568dd22a2', 1, 'Count electron domains (bonds and lone pairs) on a central atom.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a9d82a40fd828', 'les_65267568dd22a2', 2, 'Predict electron geometry and molecular geometry.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_55c45dc3ddb732', 'les_65267568dd22a2', 3, 'Explain why lone pairs compress bond angles.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1dfde0709c82e1', 'les_65267568dd22a2', 'learn', 1, 'definition', '{"term":"VSEPR","body":"Valence-shell electron-pair repulsion: electron domains around a central atom spread out as far as possible. A single, double or triple bond counts as one domain, and so does each lone pair. The electron geometry uses all domains; the molecular geometry names only the atoms'' positions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a9d82a40fd828', 'les_65267568dd22a2', 'learn', 2, 'worked_example', '{"title":"CH₄, NH₃ and H₂O all have 4 electron domains","steps":[{"latex":"\\text{CH}_4:\\ 4\\ \\text{bonds, 0 lone pairs}","explanation":"Tetrahedral, 109.5°."},{"latex":"\\text{NH}_3:\\ 3\\ \\text{bonds, 1 lone pair}","explanation":"Trigonal pyramidal, about 107°."},{"latex":"\\text{H}_2\\text{O}:\\ 2\\ \\text{bonds, 2 lone pairs}","explanation":"Bent, about 104.5°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_55c45dc3ddb732', 'les_65267568dd22a2', 'experiment', 3, 'activity', '{"activity":"vsepr","title":"Build the shapes","params":{"domains":4,"lonePairs":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7edb19d4e94911', 'les_65267568dd22a2', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"With 4 domains, add lone pairs one at a time and watch the molecular shape change from tetrahedral to pyramidal to bent. Then try 6 domains with 2 lone pairs: the lone pairs sit opposite each other, leaving a square plane."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_40244602538132', 'les_65267568dd22a2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Shape decides how molecules fit together: enzymes recognize substrates by shape, and water''s bent shape makes it polar, which makes life''s chemistry possible."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1dfde0709c82e1', 'les_65267568dd22a2', 1, 'practice', 'multiple_choice', 1, 'What is the shape of CO₂?', '{"choices":["bent","linear","trigonal planar","tetrahedral"],"answer":1}', '[]', 'Two domains (two double bonds), no lone pairs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a9d82a40fd828', 'les_65267568dd22a2', 2, 'practice', 'multiple_choice', 2, 'What is the molecular geometry of PCl₃?', '{"choices":["trigonal planar","trigonal pyramidal","T-shaped","tetrahedral"],"answer":1}', '[]', '3 bonds and 1 lone pair on P.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_55c45dc3ddb732', 'les_65267568dd22a2', 3, 'practice', 'multiple_choice', 2, 'BF₃ has a bond angle of…', '{"choices":["90°","109.5°","120°","180°"],"answer":2}', '[]', 'Trigonal planar: boron has no lone pairs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7edb19d4e94911', 'les_65267568dd22a2', 4, 'review', 'multiple_choice', 3, 'Why is water''s bond angle smaller than methane''s?', '{"choices":["oxygen is larger","lone pairs repel more strongly than bonding pairs","hydrogen is small","it''s a double bond"],"answer":1}', '[]', 'Lone pairs spread out and squeeze the bonds.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_793ae6aa1f37d6', 'subj_chem', 'chemical-bonding', 'Chemical bonding', 'Ionic, covalent and metallic bonds and the shapes and polarity of molecules.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_65267568dd22a2', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: naming-ionic-compounds
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_46619bc03b1dfc', 'naming-ionic-compounds', 'Naming ionic compounds', 'Name and write formulas for binary ionic compounds, transition-metal compounds with Roman numerals, and compounds with polyatomic ions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_361d122db1cee0', 'les_46619bc03b1dfc', 1, 'Name binary ionic compounds: metal name + nonmetal root + -ide.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b552c5a62a7f55', 'les_46619bc03b1dfc', 2, 'Use Roman numerals for metals with more than one possible charge.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9c848613c4f525', 'les_46619bc03b1dfc', 3, 'Recognize common polyatomic ions and use parentheses in formulas.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_361d122db1cee0', 'les_46619bc03b1dfc', 'learn', 1, 'definition', '{"term":"Binary ionic","body":"Name the cation (the metal), then the anion with -ide: NaCl is sodium chloride, CaO calcium oxide, Al₂S₃ aluminum sulfide."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b552c5a62a7f55', 'les_46619bc03b1dfc', 'learn', 2, 'definition', '{"term":"Variable charges","body":"Transition metals often have several charges; a Roman numeral gives it: FeCl₃ is iron(III) chloride (Fe³⁺), FeCl₂ is iron(II) chloride, Cu₂O is copper(I) oxide. Find the charge by balancing the anions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c848613c4f525', 'les_46619bc03b1dfc', 'learn', 3, 'definition', '{"term":"Polyatomic ions","body":"Memorize the common ones: NH₄⁺ ammonium, OH⁻ hydroxide, NO₃⁻ nitrate, SO₄²⁻ sulfate, CO₃²⁻ carbonate, PO₄³⁻ phosphate. Use parentheses when you need more than one: Ca₃(PO₄)₂."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b67a912fafb9e', 'les_46619bc03b1dfc', 'learn', 4, 'worked_example', '{"title":"Write formulas for calcium phosphate and copper(II) sulfate","steps":[{"latex":"\\text{Ca}^{2+},\\ \\text{PO}_4^{3-} \\Rightarrow \\text{Ca}_3(\\text{PO}_4)_2","explanation":"3(+2) + 2(−3) = 0."},{"latex":"\\text{Cu}^{2+},\\ \\text{SO}_4^{2-} \\Rightarrow \\text{CuSO}_4","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4a7b9b09b16ae', 'les_46619bc03b1dfc', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ingredient labels (sodium bicarbonate, calcium carbonate), fertilizers (ammonium nitrate) and the iron(II) sulfate in iron supplements."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_361d122db1cee0', 'les_46619bc03b1dfc', 1, 'practice', 'multiple_choice', 1, 'Name K₂O.', '{"choices":["potassium oxide","dipotassium oxide","potassium(II) oxide","potassium oxygen"],"answer":0}', '[]', 'Group 1 has only one charge.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b552c5a62a7f55', 'les_46619bc03b1dfc', 2, 'practice', 'multiple_choice', 2, 'Name Fe₂O₃.', '{"choices":["iron(II) oxide","iron(III) oxide","diiron trioxide","iron oxide(III)"],"answer":1}', '[]', '3(−2) = −6 shared by 2 Fe: +3 each.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c848613c4f525', 'les_46619bc03b1dfc', 3, 'practice', 'multiple_choice', 2, 'What is the formula of ammonium sulfate?', '{"choices":["NH₄SO₄","(NH₄)₂SO₄","NH₄(SO₄)₂","(NH₄)₃SO₄"],"answer":1}', '[]', 'Two +1 ions balance one −2 ion.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b67a912fafb9e', 'les_46619bc03b1dfc', 4, 'review', 'multiple_choice', 3, 'Which needs a Roman numeral in its name?', '{"choices":["NaCl","MgO","CuCl₂","Al₂O₃"],"answer":2}', '[]', 'Copper can be +1 or +2.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b2c28fd94c8809', 'subj_chem', 'nomenclature', 'Chemical nomenclature', 'Systematic names and formulas for compounds.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_46619bc03b1dfc', (SELECT id FROM concepts WHERE slug = 'nomenclature'));

-- Lesson: naming-molecular-acids
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e6eeba34a0b378', 'naming-molecular-acids', 'Naming molecular compounds and acids', 'Name binary molecular compounds with Greek prefixes, and name binary acids and oxyacids from their anions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_92a67caec67539', 'les_e6eeba34a0b378', 1, 'Use prefixes (mono-, di-, tri-, tetra-, penta-, hexa-…) for molecular compounds.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4df5e6a7adffd', 'les_e6eeba34a0b378', 2, 'Name binary acids: hydro- + root + -ic acid.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_25e2b93eec79fa', 'les_e6eeba34a0b378', 3, 'Name oxyacids: -ate → -ic acid, -ite → -ous acid.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92a67caec67539', 'les_e6eeba34a0b378', 'learn', 1, 'definition', '{"term":"Molecular compounds","body":"Two nonmetals: use prefixes for the number of each atom, ending the second with -ide. Drop mono- on the first element. CO is carbon monoxide, N₂O₅ dinitrogen pentoxide, SF₆ sulfur hexafluoride."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4df5e6a7adffd', 'les_e6eeba34a0b378', 'learn', 2, 'definition', '{"term":"Acids","body":"Binary acids (H with one nonmetal, in water): hydro- + root + -ic acid, so HCl is hydrochloric acid. Oxyacids come from polyatomic anions: -ate becomes -ic (NO₃⁻ → HNO₃, nitric acid; SO₄²⁻ → H₂SO₄, sulfuric acid); -ite becomes -ous (SO₃²⁻ → H₂SO₃, sulfurous acid)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25e2b93eec79fa', 'les_e6eeba34a0b378', 'learn', 3, 'worked_example', '{"title":"Name P₄O₁₀ and HClO₂ (from chlorite, ClO₂⁻)","steps":[{"latex":"\\text{P}_4\\text{O}_{10}:\\ \\text{tetraphosphorus decoxide}","explanation":""},{"latex":"\\text{HClO}_2:\\ \\text{chlorous acid}","explanation":"-ite → -ous."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dcccaba4247153', 'les_e6eeba34a0b378', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Nitrous oxide (N₂O) is laughing gas; carbon monoxide is a deadly pollutant; sulfuric acid is the most-produced industrial chemical in the world."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_92a67caec67539', 'les_e6eeba34a0b378', 1, 'practice', 'multiple_choice', 1, 'Name N₂O₄.', '{"choices":["nitrogen oxide","dinitrogen tetroxide","nitrogen(IV) oxide","dinitrogen oxide"],"answer":1}', '[]', 'Prefixes for both elements.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4df5e6a7adffd', 'les_e6eeba34a0b378', 2, 'practice', 'multiple_choice', 2, 'Name HBr dissolved in water.', '{"choices":["bromic acid","hydrobromic acid","hydrogen bromate","bromous acid"],"answer":1}', '[]', 'A binary acid.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_25e2b93eec79fa', 'les_e6eeba34a0b378', 3, 'practice', 'multiple_choice', 2, 'Name HNO₂ (from nitrite).', '{"choices":["nitric acid","nitrous acid","hydronitric acid","hydronitrous acid"],"answer":1}', '[]', '-ite → -ous.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dcccaba4247153', 'les_e6eeba34a0b378', 4, 'review', 'multiple_choice', 3, 'What is the formula of phosphoric acid (from phosphate, PO₄³⁻)?', '{"choices":["HPO₄","H₂PO₄","H₃PO₄","H₃PO₃"],"answer":2}', '[]', 'Three H⁺ balance −3.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b2c28fd94c8809', 'subj_chem', 'nomenclature', 'Chemical nomenclature', 'Systematic names and formulas for compounds.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e6eeba34a0b378', (SELECT id FROM concepts WHERE slug = 'nomenclature'));

-- Lesson: neutralization-titration
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6e79eeaa32a85e', 'neutralization-titration', 'Neutralization and titration', 'Write neutralization reactions, find unknown concentrations by titration, and read titration curves and indicators.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_033c9377ce54b3', 'les_6e79eeaa32a85e', 1, 'Write neutralization reactions: acid + base → salt + water.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7cb872d0c8a260', 'les_6e79eeaa32a85e', 2, 'Find an unknown concentration from titration data with mole ratios.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_beb5e61ca89a1a', 'les_6e79eeaa32a85e', 3, 'Read the equivalence point on a titration curve and choose an indicator.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_033c9377ce54b3', 'les_6e79eeaa32a85e', 'learn', 1, 'definition', '{"term":"Neutralization","body":"$\\text{HCl} + \\text{NaOH} \\to \\text{NaCl} + \\text{H}_2\\text{O}$: the net reaction is $\\text{H}^+ + \\text{OH}^- \\to \\text{H}_2\\text{O}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7cb872d0c8a260', 'les_6e79eeaa32a85e', 'learn', 2, 'definition', '{"term":"Titration","body":"A solution of known concentration (the titrant) is added from a buret until the equivalence point, when moles of H⁺ equal moles of OH⁻. An indicator changes color at or near that point. For 1 : 1 acid–base pairs, $M_aV_a = M_bV_b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_beb5e61ca89a1a', 'les_6e79eeaa32a85e', 'learn', 3, 'worked_example', '{"title":"25.0 mL of HCl needs 18.6 mL of 0.100 M NaOH","steps":[{"latex":"n_{\\text{NaOH}} = 0.100(0.0186) = 1.86\\times10^{-3}\\ \\text{mol}","explanation":""},{"latex":"M_{\\text{HCl}} = \\tfrac{1.86\\times10^{-3}}{0.0250} = 0.0744\\ \\text{M}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_67a72d5144287c', 'les_6e79eeaa32a85e', 'experiment', 4, 'activity', '{"activity":"titration","title":"Run a titration","params":{"acid":"strong","acidConc":0.1,"baseConc":0.1,"baseVolume":20}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47922774c20364', 'les_6e79eeaa32a85e', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch to acetic acid: the equivalence pH rises above 7, because the acetate ion is a weak base. Phenolphthalein (changes near pH 8–10) suits this titration better than methyl orange."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9b8e9afa27202', 'les_6e79eeaa32a85e', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Quality control of vinegar and juice acidity, water testing, and antacid tablets that neutralize stomach acid."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_033c9377ce54b3', 'les_6e79eeaa32a85e', 1, 'practice', 'numeric', 2, 'How many mL of 0.200 M NaOH neutralize 30.0 mL of 0.150 M HCl?', '{"answer":22.5,"unit":"mL"}', '[]', '$\frac{0.150(30.0)}{0.200}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7cb872d0c8a260', 'les_6e79eeaa32a85e', 2, 'practice', 'numeric', 3, '20.0 mL of H₂SO₄ is neutralized by 32.0 mL of 0.250 M NaOH. Find [H₂SO₄]. (Each H₂SO₄ gives 2 H⁺.)', '{"answer":0.2,"unit":"M"}', '[]', '$n_{OH} = 0.008$, so $n_{acid} = 0.004$ and $\frac{0.004}{0.0200}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_beb5e61ca89a1a', 'les_6e79eeaa32a85e', 3, 'practice', 'multiple_choice', 2, 'At the equivalence point of a strong acid–strong base titration, pH is about…', '{"choices":["1","4","7","10"],"answer":2}', '[]', 'The salt is neutral.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_67a72d5144287c', 'les_6e79eeaa32a85e', 4, 'review', 'multiple_choice', 3, 'Titrating a weak acid with a strong base, the equivalence pH is…', '{"choices":["below 7","exactly 7","above 7","0"],"answer":2}', '[]', 'The conjugate base raises the pH.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_745130d4876933', 'subj_chem', 'acids-bases', 'Acids and bases', 'Proton donors and acceptors, pH and neutralization.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6e79eeaa32a85e', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6e79eeaa32a85e', (SELECT id FROM formulas WHERE slug = 'molarity-dilution'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6e79eeaa32a85e', (SELECT id FROM formulas WHERE slug = 'ph-scale'), 2);

-- Lesson: percent-composition-empirical
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a7b30e2185d791', 'percent-composition-empirical', 'Percent composition and empirical formulas', 'Compute percent composition by mass, find empirical formulas from percentages or masses, and find molecular formulas from molar mass.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_23bd5c6f1fad23', 'les_a7b30e2185d791', 1, 'Compute percent by mass of each element in a compound.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1c47a8c0f93b44', 'les_a7b30e2185d791', 2, 'Find an empirical formula: grams → moles → simplest ratio.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f4fa7450951f7a', 'les_a7b30e2185d791', 3, 'Find a molecular formula from the empirical formula and molar mass.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23bd5c6f1fad23', 'les_a7b30e2185d791', 'learn', 1, 'definition', '{"term":"Percent composition","body":"$\\%\\ \\text{element} = \\frac{\\text{mass of element in 1 mol}}{\\text{molar mass}}\\times100\\%$. In water, $\\frac{2.016}{18.015} \\approx 11.19\\%$ hydrogen."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c47a8c0f93b44', 'les_a7b30e2185d791', 'learn', 2, 'definition', '{"term":"Empirical formula","body":"The simplest whole-number ratio of atoms. Assume 100 g so percentages become grams, convert to moles, divide by the smallest, and multiply to clear simple fractions such as .5 or .33."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4fa7450951f7a', 'les_a7b30e2185d791', 'learn', 3, 'worked_example', '{"title":"A sugar is 40.0% C, 6.7% H and 53.3% O by mass; its molar mass is 180 g/mol","steps":[{"latex":"\\text{C}: \\tfrac{40.0}{12.01} = 3.33\\ \\text{mol}","explanation":"Moles in 100 g."},{"latex":"\\text{H}: \\tfrac{6.7}{1.008} = 6.65\\ \\text{mol}","explanation":""},{"latex":"\\text{O}: \\tfrac{53.3}{16.00} = 3.33\\ \\text{mol}","explanation":""},{"latex":"\\div 3.33:\\ 1 : 2 : 1 \\Rightarrow \\text{CH}_2\\text{O}","explanation":"Empirical formula, 30.03 g/mol."},{"latex":"\\tfrac{180}{30.03} \\approx 6 \\Rightarrow \\text{C}_6\\text{H}_{12}\\text{O}_6","explanation":"Glucose."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54c9c035337d69', 'les_a7b30e2185d791', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Combustion analysis identifies new compounds in pharmaceutical labs, and fertilizer bags list percent N, P and K."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_23bd5c6f1fad23', 'les_a7b30e2185d791', 1, 'practice', 'numeric', 2, 'Find the percent oxygen in CO₂, to one decimal place.', '{"answer":72.7,"tolerance":0.1,"unit":"%"}', '[]', '$\frac{32.00}{44.01}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c47a8c0f93b44', 'les_a7b30e2185d791', 2, 'practice', 'multiple_choice', 2, 'A compound is 75% C and 25% H by mass. Its empirical formula is…', '{"choices":["CH₂","CH₃","CH₄","C₂H₅"],"answer":2}', '[]', '$\frac{75}{12.01} = 6.24$, $\frac{25}{1.008} = 24.8$: ratio 1 : 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4fa7450951f7a', 'les_a7b30e2185d791', 3, 'practice', 'numeric', 3, 'A compound with empirical formula CH₂ has molar mass 84.16 g/mol. How many carbon atoms are in its molecular formula?', '{"answer":6}', '[]', '$\frac{84.16}{14.03} = 6$: C₆H₁₂.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_54c9c035337d69', 'les_a7b30e2185d791', 4, 'review', 'multiple_choice', 3, 'Which pair has the same empirical formula?', '{"choices":["C₂H₂ and C₆H₆","CO and CO₂","H₂O and H₂O₂","CH₄ and C₂H₆"],"answer":0}', '[]', 'Both reduce to CH.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a7b30e2185d791', (SELECT id FROM concepts WHERE slug = 'the-mole'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a7b30e2185d791', (SELECT id FROM formulas WHERE slug = 'molar-mass-moles'), 1);

-- Lesson: periodic-table-organization
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c3bc4d5c16e837', 'periodic-table-organization', 'Organization of the periodic table', 'Read groups and periods, locate metals, nonmetals and metalloids, name the major families, and connect the table''s blocks to electron configurations.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_955fb5aaaf863e', 'les_c3bc4d5c16e837', 1, 'Identify groups (columns) and periods (rows).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9dc882307bf34a', 'les_c3bc4d5c16e837', 2, 'Locate metals, nonmetals, metalloids and the major families.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7d7706fdfd8ec8', 'les_c3bc4d5c16e837', 3, 'Relate the s, p, d and f blocks to electron configurations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_955fb5aaaf863e', 'les_c3bc4d5c16e837', 'learn', 1, 'definition', '{"term":"Layout","body":"Mendeleev ordered elements by mass and grouped similar ones, leaving gaps for undiscovered elements; the modern table orders by atomic number. Elements in a group share valence-electron counts and behave similarly; a period number tells the outermost energy level."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9dc882307bf34a', 'les_c3bc4d5c16e837', 'learn', 2, 'definition', '{"term":"Regions and families","body":"Metals (left and center) are shiny, conductive and lose electrons. Nonmetals (upper right) gain or share electrons. Metalloids (B, Si, Ge, As, Sb, Te) lie along the staircase. Families: alkali metals (Group 1), alkaline earth metals (2), transition metals (3–12), halogens (17), noble gases (18)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7d7706fdfd8ec8', 'les_c3bc4d5c16e837', 'learn', 3, 'definition', '{"term":"Blocks","body":"The s-block (Groups 1–2), p-block (13–18), d-block (transition metals) and f-block (lanthanides and actinides) show which sublevel is being filled."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4594542e1f9235', 'les_c3bc4d5c16e837', 'experiment', 4, 'activity', '{"activity":"periodic-trends","title":"Explore the main-group elements"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_046b81471e633e', 'les_c3bc4d5c16e837', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Silicon, a metalloid, became the basis of computer chips; noble gases'' stability makes them useful in lighting and welding."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_955fb5aaaf863e', 'les_c3bc4d5c16e837', 1, 'practice', 'multiple_choice', 1, 'Elements in the same group have the same…', '{"choices":["mass","number of valence electrons","number of energy levels","number of neutrons"],"answer":1}', '[]', 'That''s why they react alike.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9dc882307bf34a', 'les_c3bc4d5c16e837', 2, 'practice', 'multiple_choice', 2, 'Which is a halogen?', '{"choices":["sodium","neon","bromine","calcium"],"answer":2}', '[]', 'Group 17.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7d7706fdfd8ec8', 'les_c3bc4d5c16e837', 3, 'practice', 'numeric', 2, 'In which period is potassium ([Ar] 4s¹)?', '{"answer":4}', '[]', 'Its outermost level is n = 4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4594542e1f9235', 'les_c3bc4d5c16e837', 4, 'review', 'multiple_choice', 3, 'Which element is a metalloid?', '{"choices":["Al","Si","P","Mg"],"answer":1}', '[]', 'On the staircase.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c3bc4d5c16e837', (SELECT id FROM concepts WHERE slug = 'periodic-trends'));

-- Lesson: ph-poh
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a26233c1c689c2', 'ph-poh', 'pH and pOH', 'Use the self-ionization of water, compute pH and pOH from concentrations and back, and interpret the logarithmic pH scale.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d20e3e0e5a0008', 'les_a26233c1c689c2', 1, 'Use Kw = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ at 25 °C.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_13d0e3f585d747', 'les_a26233c1c689c2', 2, 'Compute pH = −log[H⁺], pOH = −log[OH⁻] and pH + pOH = 14.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3fb74bdb5422a0', 'les_a26233c1c689c2', 3, 'Convert pH back to [H⁺] = 10^(−pH), and interpret factor-of-10 changes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d20e3e0e5a0008', 'les_a26233c1c689c2', 'learn', 1, 'definition', '{"term":"Water and Kw","body":"Water ionizes slightly: $[\\text{H}^+][\\text{OH}^-] = 1.0\\times10^{-14}$ at 25 °C. Neutral water has both at $10^{-7}$ M, pH 7. Acidic: pH < 7; basic: pH > 7."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13d0e3f585d747', 'les_a26233c1c689c2', 'learn', 2, 'worked_example', '{"title":"[OH⁻] = 2.5 × 10⁻⁴ M","steps":[{"latex":"\\text{pOH} = -\\log(2.5\\times10^{-4}) \\approx 3.60","explanation":""},{"latex":"\\text{pH} = 14 - 3.60 = 10.40","explanation":"Basic."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3fb74bdb5422a0', 'les_a26233c1c689c2', 'learn', 3, 'worked_example', '{"title":"A solution has pH 4.50. Find [H⁺]","steps":[{"latex":"[\\text{H}^+] = 10^{-4.50} \\approx 3.2\\times10^{-5}\\ \\text{M}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22eb8a45d4385d', 'les_a26233c1c689c2', 'learn', 4, 'callout', '{"tone":"note","title":"A log scale","body":"Each pH unit is a factor of 10 in [H⁺]: pH 3 is 100 times more acidic than pH 5."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54b41062167687', 'les_a26233c1c689c2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Blood is held near pH 7.4; swimming pools are kept at 7.2–7.8; acid rain is below 5.6."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d20e3e0e5a0008', 'les_a26233c1c689c2', 1, 'practice', 'numeric', 1, 'Find the pH of 0.001 M HCl.', '{"answer":3}', '[]', '$[\text{H}^+] = 10^{-3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13d0e3f585d747', 'les_a26233c1c689c2', 2, 'practice', 'numeric', 2, 'Find the pH of 0.020 M NaOH, to two decimal places.', '{"answer":12.3,"tolerance":0.01}', '[]', '$\text{pOH} = 1.70$, so pH = 12.30.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3fb74bdb5422a0', 'les_a26233c1c689c2', 3, 'practice', 'numeric', 2, 'How many times more [H⁺] does pH 2 have than pH 5?', '{"answer":1000}', '[]', '$10^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22eb8a45d4385d', 'les_a26233c1c689c2', 4, 'review', 'multiple_choice', 3, '[H⁺] = 1 × 10⁻⁹ M. The solution is…', '{"choices":["acidic","neutral","basic","impossible"],"answer":2}', '[]', 'pH 9.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_745130d4876933', 'subj_chem', 'acids-bases', 'Acids and bases', 'Proton donors and acceptors, pH and neutralization.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a26233c1c689c2', (SELECT id FROM concepts WHERE slug = 'acids-bases'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a26233c1c689c2', (SELECT id FROM formulas WHERE slug = 'ph-scale'), 1);

-- Lesson: physical-chemical-changes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_63b9b88332c24a', 'physical-chemical-changes', 'Physical and chemical changes', 'Distinguish physical from chemical changes and properties, recognize evidence of chemical reactions, and apply conservation of mass.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fbce6d6ea199f7', 'les_63b9b88332c24a', 1, 'Distinguish physical and chemical properties and changes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_54ad696e80c32d', 'les_63b9b88332c24a', 2, 'Recognize evidence of a chemical change.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_412df3d4f2a3d5', 'les_63b9b88332c24a', 3, 'Apply the law of conservation of mass.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbce6d6ea199f7', 'les_63b9b88332c24a', 'learn', 1, 'definition', '{"term":"Physical vs chemical","body":"A physical change alters form but not identity: melting, dissolving, cutting. A chemical change makes new substances: burning, rusting, cooking. Physical properties (density, boiling point, color) can be measured without changing the substance; chemical properties (flammability, reactivity) describe how it reacts."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54ad696e80c32d', 'les_63b9b88332c24a', 'learn', 2, 'definition', '{"term":"Evidence of a chemical change","body":"Gas produced (bubbles not from boiling), a precipitate forming, an unexpected color change, light or heat given off, or a new odor. None is proof alone; boiling also makes bubbles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_412df3d4f2a3d5', 'les_63b9b88332c24a', 'learn', 3, 'definition', '{"term":"Conservation of mass","body":"In a closed system, the total mass before a reaction equals the total mass after: atoms are rearranged, not created or destroyed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a28b3ddff66e1', 'les_63b9b88332c24a', 'learn', 4, 'worked_example', '{"title":"Heating 10.0 g of limestone (CaCO₃) leaves 5.6 g of lime (CaO). How much CO₂ escaped?","steps":[{"latex":"m_{CO_2} = 10.0 - 5.6 = 4.4\\ \\text{g}","explanation":"Mass is conserved."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42ef4a71730c7e', 'les_63b9b88332c24a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Cooking (chemical), ice melting (physical), and Lavoisier''s careful weighings that founded modern chemistry by showing mass is conserved."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbce6d6ea199f7', 'les_63b9b88332c24a', 1, 'practice', 'multiple_choice', 1, 'Which is a chemical change?', '{"choices":["ice melting","sugar dissolving","wood burning","glass breaking"],"answer":2}', '[]', 'New substances (CO₂, water, ash) form.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_54ad696e80c32d', 'les_63b9b88332c24a', 2, 'practice', 'multiple_choice', 2, 'Which is a chemical property?', '{"choices":["density","boiling point","flammability","color"],"answer":2}', '[]', 'It describes how the substance reacts.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_412df3d4f2a3d5', 'les_63b9b88332c24a', 3, 'practice', 'numeric', 2, '4.0 g of hydrogen reacts completely with 32.0 g of oxygen. What mass of water forms?', '{"answer":36,"unit":"g"}', '[]', '$4.0 + 32.0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a28b3ddff66e1', 'les_63b9b88332c24a', 4, 'review', 'multiple_choice', 3, 'A burning candle loses mass. This doesn''t violate conservation of mass because…', '{"choices":["mass is destroyed in fire","products escape as gases","candles are an exception","light has mass"],"answer":1}', '[]', 'CO₂ and water vapor leave the system.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8c7bb9f61d2349', 'subj_chem', 'matter', 'Matter', 'Anything with mass and volume, classified as pure substances or mixtures.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_63b9b88332c24a', (SELECT id FROM concepts WHERE slug = 'matter'));

-- Lesson: polarity-imfs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a107607530ebb2', 'polarity-imfs', 'Polarity and intermolecular forces', 'Predict bond and molecular polarity from electronegativity and shape, rank intermolecular forces, and explain boiling-point trends.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_14f797a5a62785', 'les_a107607530ebb2', 1, 'Classify bonds as nonpolar, polar covalent or ionic from electronegativity differences.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1f42cd291cbb1e', 'les_a107607530ebb2', 2, 'Decide whether a molecule is polar from its bond polarities and shape.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c73060bbb2e1e', 'les_a107607530ebb2', 3, 'Rank London dispersion, dipole–dipole and hydrogen bonding, and predict boiling points.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14f797a5a62785', 'les_a107607530ebb2', 'learn', 1, 'definition', '{"term":"Bond polarity","body":"Electronegativity is an atom''s pull on shared electrons. A difference under about 0.4 gives a nonpolar bond; 0.4–1.7 polar covalent; above about 1.7 mostly ionic. For O–H: 3.44 − 2.20 = 1.24, polar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f42cd291cbb1e', 'les_a107607530ebb2', 'learn', 2, 'definition', '{"term":"Molecular polarity","body":"A molecule is polar if its bond dipoles don''t cancel. CO₂ has polar bonds but is linear, so they cancel: nonpolar. H₂O is bent, so they don''t: polar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c73060bbb2e1e', 'les_a107607530ebb2', 'learn', 3, 'definition', '{"term":"Intermolecular forces","body":"London dispersion forces exist between all molecules and grow with molecular size. Polar molecules add dipole–dipole attractions. Hydrogen bonds (H bonded to N, O or F, attracted to another N, O or F) are the strongest. Stronger forces mean higher boiling points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed78861f356d7f', 'les_a107607530ebb2', 'learn', 4, 'worked_example', '{"title":"Why does water (18 g/mol) boil at 100 °C but methane (16 g/mol) at −162 °C?","steps":[{"latex":"\\text{CH}_4:\\ \\text{dispersion only}","explanation":"Nonpolar."},{"latex":"\\text{H}_2\\text{O}:\\ \\text{hydrogen bonding}","explanation":"Much stronger attractions to overcome."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96dd2838cfe7ab', 'les_a107607530ebb2', 'experiment', 5, 'activity', '{"activity":"vsepr","title":"Shape decides whether dipoles cancel","params":{"domains":4,"lonePairs":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c77aa3040a82a', 'les_a107607530ebb2', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ice floats because hydrogen bonds hold it in an open lattice; soap works because one end is polar and the other nonpolar; DNA''s two strands are held by hydrogen bonds."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14f797a5a62785', 'les_a107607530ebb2', 1, 'practice', 'numeric', 2, 'Find the electronegativity difference for a C–Cl bond (C 2.55, Cl 3.16), to two decimal places.', '{"answer":0.61,"tolerance":0.001}', '[]', 'Polar covalent.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f42cd291cbb1e', 'les_a107607530ebb2', 2, 'practice', 'multiple_choice', 2, 'Which molecule is nonpolar despite having polar bonds?', '{"choices":["H₂O","NH₃","CCl₄","HCl"],"answer":2}', '[]', 'Tetrahedral symmetry cancels the dipoles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c73060bbb2e1e', 'les_a107607530ebb2', 3, 'practice', 'multiple_choice', 2, 'Which has the highest boiling point?', '{"choices":["CH₄","HF","Ne","F₂"],"answer":1}', '[]', 'Hydrogen bonding.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed78861f356d7f', 'les_a107607530ebb2', 4, 'review', 'multiple_choice', 3, 'Going down the halogens (F₂ → I₂), boiling points rise because…', '{"choices":["hydrogen bonding increases","London dispersion forces grow with size","they become ionic","polarity increases"],"answer":1}', '[]', 'Larger electron clouds are more polarizable.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_793ae6aa1f37d6', 'subj_chem', 'chemical-bonding', 'Chemical bonding', 'Ionic, covalent and metallic bonds and the shapes and polarity of molecules.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a107607530ebb2', (SELECT id FROM concepts WHERE slug = 'chemical-bonding'));

-- Lesson: pressure-gas-laws
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c4c00eac858fd6', 'pressure-gas-laws', 'Pressure and the gas laws', 'Convert pressure units and apply Boyle''s, Charles''s, Gay-Lussac''s and the combined gas law, always with kelvin temperatures.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b25912c75cf0b1', 'les_c4c00eac858fd6', 1, 'Convert among atm, mmHg (torr) and kPa.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_21994adc9f53b2', 'les_c4c00eac858fd6', 2, 'Apply Boyle''s (P₁V₁ = P₂V₂), Charles''s (V/T) and Gay-Lussac''s (P/T) laws.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1595fa54d0636a', 'les_c4c00eac858fd6', 3, 'Use the combined gas law, P₁V₁/T₁ = P₂V₂/T₂.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b25912c75cf0b1', 'les_c4c00eac858fd6', 'learn', 1, 'definition', '{"term":"Pressure","body":"Pressure is force per area from gas particles hitting walls. $1\\ \\text{atm} = 760\\ \\text{mmHg} = 760\\ \\text{torr} = 101.325\\ \\text{kPa}$. A barometer balances the atmosphere against a column of mercury."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21994adc9f53b2', 'les_c4c00eac858fd6', 'learn', 2, 'definition', '{"term":"The laws","body":"For a fixed amount of gas: Boyle, $P_1V_1 = P_2V_2$ (constant T); Charles, $\\frac{V_1}{T_1} = \\frac{V_2}{T_2}$ (constant P); Gay-Lussac, $\\frac{P_1}{T_1} = \\frac{P_2}{T_2}$ (constant V). Combined: $\\frac{P_1V_1}{T_1} = \\frac{P_2V_2}{T_2}$, with T in kelvin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1595fa54d0636a', 'les_c4c00eac858fd6', 'learn', 3, 'worked_example', '{"title":"2.0 L of gas at 1.0 atm and 273 K is changed to 0.50 atm and 300 K","steps":[{"latex":"V_2 = V_1\\tfrac{P_1}{P_2}\\tfrac{T_2}{T_1} = 2.0\\left(\\tfrac{1.0}{0.50}\\right)\\left(\\tfrac{300}{273}\\right)","explanation":""},{"latex":"V_2 \\approx 4.4\\ \\text{L}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c5e129f10667c', 'les_c4c00eac858fd6', 'experiment', 4, 'activity', '{"activity":"ideal-gas","title":"Hold one variable fixed"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc3b787beb8cd0', 'les_c4c00eac858fd6', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scuba tanks (Boyle: air expands as divers rise), hot-air balloons (Charles) and tire-pressure changes with the seasons (Gay-Lussac)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b25912c75cf0b1', 'les_c4c00eac858fd6', 1, 'practice', 'numeric', 1, 'Convert 1.50 atm to mmHg.', '{"answer":1140,"unit":"mmHg"}', '[]', '$1.50 \times 760$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21994adc9f53b2', 'les_c4c00eac858fd6', 2, 'practice', 'numeric', 2, 'A 2.0 L balloon at 1.0 atm is squeezed to 4.0 atm at constant temperature. Find its volume.', '{"answer":0.5,"unit":"L"}', '[]', '$\frac{2.0(1.0)}{4.0}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1595fa54d0636a', 'les_c4c00eac858fd6', 3, 'practice', 'numeric', 2, 'A 2.0 L sample at 300 K is heated to 450 K at constant pressure. Find the new volume.', '{"answer":3,"unit":"L"}', '[]', '$2.0 \times \frac{450}{300}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c5e129f10667c', 'les_c4c00eac858fd6', 4, 'review', 'multiple_choice', 3, 'Doubling the Celsius temperature from 20 °C to 40 °C (constant P) makes the volume…', '{"choices":["double","increase by about 7%","halve","stay the same"],"answer":1}', '[]', '$\frac{313}{293} \approx 1.07$: use kelvin.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c4c00eac858fd6', (SELECT id FROM concepts WHERE slug = 'gas-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c4c00eac858fd6', (SELECT id FROM formulas WHERE slug = 'combined-gas-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c4c00eac858fd6', (SELECT id FROM formulas WHERE slug = 'celsius-to-kelvin'), 2);

-- Lesson: reaction-types
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_73eb8a4f3264f9', 'reaction-types', 'Types of chemical reactions', 'Classify reactions as synthesis, decomposition, single replacement, double replacement or combustion, and predict products using the activity series and solubility rules.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_11d3bcf13b5d1b', 'les_73eb8a4f3264f9', 1, 'Classify reactions into the five basic types.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa83140596dd09', 'les_73eb8a4f3264f9', 2, 'Predict single-replacement products with the activity series.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5bd1629352356f', 'les_73eb8a4f3264f9', 3, 'Predict double-replacement products and precipitates with solubility rules.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_11d3bcf13b5d1b', 'les_73eb8a4f3264f9', 'learn', 1, 'definition', '{"term":"Five patterns","body":"Synthesis: A + B → AB. Decomposition: AB → A + B. Single replacement: A + BC → AC + B. Double replacement: AB + CD → AD + CB. Combustion: a fuel + O₂ → CO₂ + H₂O (for hydrocarbons)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa83140596dd09', 'les_73eb8a4f3264f9', 'learn', 2, 'definition', '{"term":"Activity series","body":"A metal replaces another metal (or H) only if it is more active: K > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Ag > Au. Zinc displaces copper from CuSO₄; copper does nothing in ZnSO₄."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5bd1629352356f', 'les_73eb8a4f3264f9', 'learn', 3, 'definition', '{"term":"Precipitates","body":"A double replacement goes forward when it forms a precipitate, a gas or water. All nitrates and Group 1 and ammonium compounds are soluble; most chlorides are soluble except those of Ag⁺, Pb²⁺ and Hg₂²⁺."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad6505d0b0a689', 'les_73eb8a4f3264f9', 'learn', 4, 'worked_example', '{"title":"Silver nitrate and sodium chloride solutions are mixed","steps":[{"latex":"\\text{AgNO}_3(aq) + \\text{NaCl}(aq) \\to","explanation":"Double replacement: the ions swap partners."},{"latex":"\\text{AgCl}(s) + \\text{NaNO}_3(aq)","explanation":"AgCl precipitates as a white solid."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_268abb7c2eac19', 'les_73eb8a4f3264f9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Water softening (precipitating calcium), galvanizing steel with zinc (the more active metal corrodes first), and every flame from gas stoves to rockets."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_11d3bcf13b5d1b', 'les_73eb8a4f3264f9', 1, 'practice', 'multiple_choice', 1, '2H₂O → 2H₂ + O₂ is…', '{"choices":["synthesis","decomposition","combustion","single replacement"],"answer":1}', '[]', 'One reactant breaks apart.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa83140596dd09', 'les_73eb8a4f3264f9', 2, 'practice', 'multiple_choice', 2, 'Will copper metal react with zinc sulfate solution?', '{"choices":["yes, forming CuSO₄","no, copper is less active than zinc","yes, producing H₂","only when heated"],"answer":1}', '[]', 'Check the activity series.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5bd1629352356f', 'les_73eb8a4f3264f9', 3, 'practice', 'multiple_choice', 2, 'Which pair of solutions forms a precipitate?', '{"choices":["NaCl + KNO₃","AgNO₃ + KCl","NaNO₃ + KCl","NH₄Cl + NaNO₃"],"answer":1}', '[]', 'AgCl is insoluble.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad6505d0b0a689', 'les_73eb8a4f3264f9', 4, 'review', 'multiple_choice', 3, 'What are the products of burning methane completely?', '{"choices":["C + H₂O","CO + H₂","CO₂ + H₂O","CO₂ + H₂"],"answer":2}', '[]', 'Complete hydrocarbon combustion.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c310af44564c4d', 'subj_chem', 'chemical-reactions', 'Chemical reactions', 'How substances rearrange into new ones, described by balanced equations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_73eb8a4f3264f9', (SELECT id FROM concepts WHERE slug = 'chemical-reactions'));

-- Lesson: solubility-dissolving
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f61c5f032299fd', 'solubility-dissolving', 'Solubility and the dissolving process', 'Describe how solutes dissolve, apply ''like dissolves like'', read solubility curves, and explain how temperature and pressure affect solubility.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_93cffe59e97289', 'les_f61c5f032299fd', 1, 'Describe dissolving at the particle level (solvation).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_47ed356de0c486', 'les_f61c5f032299fd', 2, 'Predict solubility with ''like dissolves like''.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0496e2f63d8869', 'les_f61c5f032299fd', 3, 'Classify solutions as unsaturated, saturated or supersaturated using solubility data.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93cffe59e97289', 'les_f61c5f032299fd', 'learn', 1, 'definition', '{"term":"Dissolving","body":"Solvent molecules surround and pull apart solute particles. Water''s partial charges pull ions out of a crystal and surround each one. Polar and ionic solutes dissolve in polar solvents; nonpolar solutes in nonpolar solvents: like dissolves like. Oil and water don''t mix."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47ed356de0c486', 'les_f61c5f032299fd', 'learn', 2, 'definition', '{"term":"Saturation","body":"Solubility is the maximum amount that dissolves in a given amount of solvent at a given temperature, often in g per 100 g of water. Below it: unsaturated; at it: saturated; above it, for a while: supersaturated and unstable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0496e2f63d8869', 'les_f61c5f032299fd', 'learn', 3, 'definition', '{"term":"Temperature and pressure","body":"Most solids dissolve better in hotter water. Gases do the opposite: they''re less soluble when warm (warm soda goes flat) and more soluble at higher pressure (Henry''s law)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_757899b089bb00', 'les_f61c5f032299fd', 'learn', 4, 'worked_example', '{"title":"KNO₃''s solubility is 64 g/100 g water at 40 °C. Is 50 g in 100 g of water at 40 °C saturated?","steps":[{"latex":"50 < 64","explanation":"Unsaturated: 14 g more could dissolve."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26ca4954066869', 'les_f61c5f032299fd', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbonated drinks bottled under pressure, the bends in divers (nitrogen coming out of solution), and fish kills when warm water holds too little oxygen."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93cffe59e97289', 'les_f61c5f032299fd', 1, 'practice', 'multiple_choice', 1, 'Which dissolves best in hexane (nonpolar)?', '{"choices":["salt","sugar","oil","ammonia"],"answer":2}', '[]', 'Like dissolves like.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47ed356de0c486', 'les_f61c5f032299fd', 2, 'practice', 'numeric', 2, 'A salt''s solubility is 36 g/100 g water. How many grams dissolve in 250 g of water?', '{"answer":90,"unit":"g"}', '[]', '$36 \times 2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0496e2f63d8869', 'les_f61c5f032299fd', 3, 'practice', 'multiple_choice', 2, 'A soda goes flat faster when warm because…', '{"choices":["sugar evaporates","gases are less soluble at higher temperature","pressure rises","CO₂ reacts"],"answer":1}', '[]', 'Opposite to most solids.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_757899b089bb00', 'les_f61c5f032299fd', 4, 'review', 'multiple_choice', 3, 'Adding a seed crystal to a supersaturated solution causes…', '{"choices":["nothing","rapid crystallization of the excess solute","more dissolving","boiling"],"answer":1}', '[]', 'It''s unstable.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_8facaaa9e16a70', 'subj_chem', 'solutions', 'Solutions', 'Homogeneous mixtures, their concentrations and properties.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f61c5f032299fd', (SELECT id FROM concepts WHERE slug = 'solutions'));

